    /// **Whose size is it** (user ruling 2026-08-08), as the three rules that decide it.
    ///
    /// Windows delivers the same `Resized` event for a hand on the frame, for a window created at
    /// a restored size, and for the resize that rides along with a DPI change. Only the first is a
    /// user saying "this is my size"; getting that wrong either folds a window somebody dragged
    /// narrow or leaves a restored-too-small session showing slivers.
    #[test]
    fn a_resize_is_the_users_unless_the_program_asked_for_it() {
        let opened = PhysicalSize::new(1600, 900);
        let dragged = PhysicalSize::new(700, 400);

        // ① Startup, exactly as it really arrives. `Runtime::create` leaves a standing claim and
        // the first rectangle answers it — whatever the OS made of the request. Repeat deliveries
        // of that same rectangle change nothing, so a session restored into a window too small for
        // its tree still folds.
        let (mut policy, mut claimed) = (SizePolicy::Lawful, None);
        for _ in 0..3 {
            (policy, claimed) = size_authority_for_rectangle(policy, claimed, opened);
        }
        assert_eq!(
            claimed,
            Some(opened),
            "the pending claim adopted the opening rectangle"
        );
        assert_eq!(
            policy,
            SizePolicy::Lawful,
            "a restored session must still fold; startup is not a gesture"
        );

        // ② A rectangle we did not ask for is a hand on the frame.
        (policy, claimed) = size_authority_for_rectangle(policy, claimed, dragged);
        assert_eq!(policy, SizePolicy::Sovereign);
        assert_eq!(
            claimed,
            Some(opened),
            "the claim is not rewritten by a gesture"
        );

        // ③ Sovereignty is not handed back by coincidence. Dragging back through the opening size
        // is not a change of mind about owning the window.
        let (back, _) = size_authority_for_rectangle(policy, claimed, opened);
        assert_eq!(
            back,
            SizePolicy::Sovereign,
            "only a claim returns the layout to law"
        );

        // ④ ...and the claim is `claim_lawful_layout`, whose whole content is the pair below. A
        // DPI change makes it *before* the new rectangle is known, so the resize Windows sends
        // alongside `WM_DPICHANGED` is adopted rather than read as a drag — no matter what size it
        // turns out to be, and no matter how many times it is announced.
        let (mut policy, mut claimed) = (SizePolicy::Lawful, None);
        let after_dpi = PhysicalSize::new(1050, 590);
        for _ in 0..2 {
            (policy, claimed) = size_authority_for_rectangle(policy, claimed, after_dpi);
        }
        assert_eq!((policy, claimed), (SizePolicy::Lawful, Some(after_dpi)));

        // ⑤ The transient that made this rule necessary: winit announced 826x1271 at startup while
        // the window's own inner size was 800x1200. Judging on the presentation rectangle — the
        // number the solver is actually handed — never sees it.
        let (policy, _) = size_authority_for_rectangle(
            SizePolicy::Lawful,
            Some(PhysicalSize::new(800, 1200)),
            PhysicalSize::new(800, 1200),
        );
        assert_eq!(policy, SizePolicy::Lawful);
    }

    #[test]
    fn repeated_tab_switches_do_not_feed_window_chrome_back_into_inner_size() {
        // The 2026-08-08 ruling closed this regression at the source: the minimum is the technical
        // floor, so it is the same number for every tab and there is no aggregate left to
        // alternate. The guard stays anyway — it is what keeps a *re-applied* minimum from being
        // handed to the frame at all, and winit's setter is still the setter it was.
        let metrics = seats::seat_metrics(1_000);
        let work_area = WorkAreaHint::Known(bt_layout::LogicalSize::px(2560, 1440));
        let floor = |seats: &seats::Seats| {
            let size = seats.min_inner_size(&metrics, work_area);
            (size.width.floor_px().max(1), size.height.floor_px().max(1))
        };
        let lone = seats::Seats::lone_terminal();
        let mut four = seats::Seats::lone_terminal();
        for _ in 0..3 {
            let target = four.terminal();
            four.split_terminal(&metrics, target, Axis::Row, false)
                .expect("a terminal leaf splits");
        }
        assert_eq!(
            floor(&lone),
            floor(&four),
            "four columns do not get to decide how small the window may be"
        );

        let mut applied = None;
        assert!(window_minimum_changed(&mut applied, floor(&lone)));
        let mut mock_inner_size = PhysicalSize::new(960, 600);
        let stable_inner_size = mock_inner_size;

        for switch in 0..32 {
            let showing = if switch % 2 == 0 { &lone } else { &four };
            if window_minimum_changed(&mut applied, floor(showing)) {
                // Model the winit 0.30 Windows behavior that exposed the regression: every setter
                // call re-requests the current client size through non-client adjustment.
                mock_inner_size.height += 40;
            }
            assert_eq!(
                mock_inner_size, stable_inner_size,
                "tab switch {switch} changed the window inner size"
            );
        }
    }

    /// Every DPI Windows can report, from 100% to 300%, including the quarter
    /// steps the display settings offer and the awkward ones a fractional
    /// scaling setting produces.
    const WINDOWS_SCALES: [f64; 8] = [1.0, 1.25, 1.4, 1.5, 1.75, 2.0, 2.5, 3.0];

    fn placement(bounds: WindowBoundsV1, maximized: bool) -> RestoredPlacement {
        RestoredPlacement {
            size: LogicalSize::new(f64::from(bounds.width), f64::from(bounds.height)),
            position: Some(LogicalPosition::new(
                f64::from(bounds.x),
                f64::from(bounds.y),
            )),
            maximized,
        }
    }

    /// The bug this pins: the window grew by one native frame margin — 26x71
    /// physical at 192 DPI — on every single start, because it was saved as an
    /// outer rect and restored as a client size, and winit adds
    /// `AdjustWindowRectExForDpi` to the second. Restart is a fixed point or the
    /// window walks off the screen in a fortnight.
    #[test]
    fn a_window_nobody_touched_is_restored_and_re_saved_byte_for_byte() {
        // Somewhere the OS would have put a window that had no saved position.
        let elsewhere = bt_platform::WindowRect {
            left: 100,
            top: 100,
            right: 900,
            bottom: 700,
        };
        for scale in WINDOWS_SCALES {
            for bounds in [
                WindowBoundsV1 {
                    x: 0,
                    y: 0,
                    width: 960,
                    height: 600,
                },
                // The odd extents and the negative origin of a window parked on a
                // secondary monitor left of the primary one.
                WindowBoundsV1 {
                    x: -1128,
                    y: 66,
                    width: 987,
                    height: 583,
                },
                WindowBoundsV1 {
                    x: 1,
                    y: -3,
                    width: 1,
                    height: 1,
                },
            ] {
                let rect = startup_window_rect(Some(placement(bounds, false)), elsewhere, scale);
                assert_eq!(
                    persisted_window_bounds(rect, scale),
                    bounds,
                    "scale {scale} lost {bounds:?} across one restart"
                );
                // And it stays a fixed point under repetition, which is the shape
                // the bug actually had: a margin added once is invisible, added
                // fifty times it walks the window off the screen.
                let mut generation = bounds;
                for restart in 0..50 {
                    let rect =
                        startup_window_rect(Some(placement(generation, false)), elsewhere, scale);
                    generation = persisted_window_bounds(rect, scale);
                    assert_eq!(
                        generation, bounds,
                        "scale {scale} drifted from {bounds:?} by restart {restart}"
                    );
                }
            }
        }
    }

    /// The restored rectangle is the saved one scaled, and nothing else. Stated
    /// against the exact margin that used to be added, at the DPI it was measured
    /// at: `AdjustWindowRectExForDpi(WS_OVERLAPPEDWINDOW, 192)` is 26x71.
    #[test]
    fn restoring_adds_no_native_frame_margin() {
        let saved = WindowBoundsV1 {
            x: 74,
            y: 74,
            width: 960,
            height: 600,
        };
        let rect = startup_window_rect(
            Some(placement(saved, false)),
            bt_platform::WindowRect {
                left: 0,
                top: 0,
                right: 1,
                bottom: 1,
            },
            2.0,
        );
        assert_eq!(rect.right - rect.left, 1920);
        assert_eq!(rect.bottom - rect.top, 1200);
        assert_eq!((rect.left, rect.top), (148, 148));
    }

    /// §3.1's fallback, in its own words: a rectangle no monitor can see forfeits
    /// its position, and only its position. A size is never off-screen.
    #[test]
    fn a_window_whose_monitor_is_gone_keeps_its_size_where_the_os_opened_it() {
        let opened_at = bt_platform::WindowRect {
            left: 40,
            top: 60,
            right: 640,
            bottom: 460,
        };
        let orphaned = RestoredPlacement {
            size: LogicalSize::new(800.0, 500.0),
            position: None,
            maximized: false,
        };
        let rect = startup_window_rect(Some(orphaned), opened_at, 2.0);
        assert_eq!((rect.left, rect.top), (40, 60));
        assert_eq!(
            (rect.right - rect.left, rect.bottom - rect.top),
            (1600, 1000)
        );
    }

    /// The rectangle Windows actually reported for this app's window while it was
    /// minimized, measured on the machine the bug was found on. Nothing about it
    /// is a place a window was ever put: the origin is far off any monitor and
    /// the size is the taskbar button's, not the window's.
    const ICONIC_BOUNDS: WindowBoundsV1 = WindowBoundsV1 {
        x: -16000,
        y: -16000,
        width: 157,
        height: 25,
    };

    /// A rectangle a user really did leave a window at.
    const CHOSEN_BOUNDS: WindowBoundsV1 = WindowBoundsV1 {
        x: 240,
        y: 130,
        width: 1100,
        height: 720,
    };

    /// The bug this pins, end to end: minimize, quit while minimized, start
    /// again. The snapshot recorded the *icon's* rectangle, and the next start
    /// could not seat three panes in a 157x25 window, so it exited with
    /// "place a body rectangle for terminal seat SeatId(2) from its own solve"
    /// instead of opening.
    ///
    /// Stated over the two pure halves the real path is made of — what a
    /// snapshot records, and what a start makes of what it read — so the whole
    /// round trip is checked without a window.
    #[test]
    fn quitting_while_minimized_starts_again_at_the_rectangle_the_user_chose() {
        let (bounds, maximized) = recorded_window_placement(
            WindowPosture::Minimized,
            Some(ICONIC_BOUNDS),
            CHOSEN_BOUNDS,
            false,
        );
        assert_eq!(
            bounds, CHOSEN_BOUNDS,
            "a minimized window wrote the icon's rectangle to the session file"
        );
        assert!(!maximized);
        assert_eq!(
            sane_restored_size(bounds),
            LogicalSize::new(
                f64::from(CHOSEN_BOUNDS.width),
                f64::from(CHOSEN_BOUNDS.height)
            ),
            "the rectangle the user chose was not handed back intact"
        );
    }

    /// `IsZoomed` answers false for an iconic window even when it will restore
    /// maximized, so a snapshot that trusted it would quietly demote a maximized
    /// window every time it was minimized. The posture holds both facts.
    #[test]
    fn minimizing_a_maximized_window_does_not_forget_that_it_was_maximized() {
        let (bounds, maximized) = recorded_window_placement(
            WindowPosture::Minimized,
            Some(ICONIC_BOUNDS),
            CHOSEN_BOUNDS,
            true,
        );
        assert_eq!(bounds, CHOSEN_BOUNDS);
        assert!(maximized, "a minimize demoted a maximized window");
    }

    /// fb13766's rule, restated where the new one lives so that extending it to
    /// a third posture cannot quietly drop it: a maximized window keeps the
    /// normal rectangle it had, and is still recorded as maximized.
    #[test]
    fn a_maximized_window_still_keeps_the_rectangle_it_had_while_normal() {
        let monitor_sized = WindowBoundsV1 {
            x: 0,
            y: 0,
            width: 2560,
            height: 1440,
        };
        let (bounds, maximized) = recorded_window_placement(
            WindowPosture::Maximized,
            Some(monitor_sized),
            CHOSEN_BOUNDS,
            false,
        );
        assert_eq!(bounds, CHOSEN_BOUNDS);
        assert!(maximized);
    }

    /// The posture that does record: a normal window's rectangle is the user's,
    /// and it is written exactly. The fallback to what was saved covers only the
    /// case where the rectangle could not be measured at all.
    #[test]
    fn a_normal_window_records_the_rectangle_it_was_measured_at() {
        let measured = WindowBoundsV1 {
            x: 12,
            y: 34,
            width: 800,
            height: 600,
        };
        assert_eq!(
            recorded_window_placement(WindowPosture::Normal, Some(measured), CHOSEN_BOUNDS, true),
            (measured, false)
        );
        assert_eq!(
            recorded_window_placement(WindowPosture::Normal, None, CHOSEN_BOUNDS, true),
            (CHOSEN_BOUNDS, false),
            "an unmeasurable window discarded the rectangle it already had"
        );
    }

    /// The second line, for a file an older build already damaged or a hand edit
    /// produced: a size below one seat's own minimum is not a size a window was
    /// left at, and startup takes the product's opening size instead of failing.
    #[test]
    fn a_saved_size_no_window_could_have_had_falls_back_to_the_opening_size() {
        let opening = LogicalSize::new(INITIAL_WIDTH, INITIAL_HEIGHT);
        let floor_width = MIN_PANE_W.floor_px() as u32;
        let floor_height = MIN_PANE_H.floor_px() as u32;
        for absurd in [
            ICONIC_BOUNDS,
            // Zero area, which no window has.
            WindowBoundsV1 {
                x: 0,
                y: 0,
                width: 0,
                height: 0,
            },
            // One pixel short on each axis in turn — the floor is a floor, not a
            // neighbourhood.
            WindowBoundsV1 {
                x: 0,
                y: 0,
                width: floor_width - 1,
                height: 900,
            },
            WindowBoundsV1 {
                x: 0,
                y: 0,
                width: 900,
                height: floor_height - 1,
            },
        ] {
            assert_eq!(
                sane_restored_size(absurd),
                opening,
                "{absurd:?} was honoured as a window size"
            );
        }
        // And everything a window could actually have been is left alone,
        // including a window sitting exactly on the floor.
        for legitimate in [
            CHOSEN_BOUNDS,
            WindowBoundsV1 {
                x: 0,
                y: 0,
                width: floor_width,
                height: floor_height,
            },
            WindowBoundsV1 {
                x: -1128,
                y: 66,
                width: 987,
                height: 583,
            },
        ] {
            assert_eq!(
                sane_restored_size(legitimate),
                LogicalSize::new(f64::from(legitimate.width), f64::from(legitimate.height)),
                "{legitimate:?} was overridden despite being a real window size"
            );
        }
    }

    /// A first run has no rectangle to honour, so the product's opening size is
    /// the one that is stated exactly — as an outer rect, which under the
    /// self-drawn frame is what the user sees.
    #[test]
    fn a_first_run_opens_at_the_products_own_size() {
        let opened_at = bt_platform::WindowRect {
            left: 11,
            top: 22,
            right: 33,
            bottom: 44,
        };
        let rect = startup_window_rect(None, opened_at, 2.0);
        assert_eq!((rect.left, rect.top), (11, 22));
        assert_eq!(
            (rect.right - rect.left, rect.bottom - rect.top),
            ((INITIAL_WIDTH * 2.0) as i32, (INITIAL_HEIGHT * 2.0) as i32)
        );
    }

    #[test]
    fn cursor_blink_resets_flips_and_stays_visible_while_unfocused() {
        let start = Instant::now();
        let mut blink = CursorBlink::new(start);
        assert!(blink.visible());
        assert_eq!(blink.deadline(), Some(start + CURSOR_BLINK_PHASE));

        assert!(blink.advance(start + CURSOR_BLINK_PHASE));
        assert!(!blink.visible(), "the first phase boundary hides the caret");
        let input_at = start + CURSOR_BLINK_PHASE + Duration::from_millis(10);
        assert!(blink.reset(input_at), "input reveals a hidden caret");
        assert!(blink.visible());
        assert_eq!(blink.deadline(), Some(input_at + CURSOR_BLINK_PHASE));

        let unfocused_at = input_at + Duration::from_millis(20);
        blink.set_focused(false, unfocused_at);
        assert!(blink.visible(), "the unfocused outline is always visible");
        assert_eq!(
            blink.deadline(),
            None,
            "unfocused cursors do not wake the loop"
        );
        assert!(!blink.advance(unfocused_at + Duration::from_secs(60)));
        assert!(blink.visible());

        let refocused_at = unfocused_at + Duration::from_secs(61);
        blink.set_focused(true, refocused_at);
        assert!(blink.visible());
        assert_eq!(blink.deadline(), Some(refocused_at + CURSOR_BLINK_PHASE));
    }

    #[test]
    fn cursor_blink_deadline_is_registered_with_the_event_loop_wake_set() {
        let start = Instant::now();
        let blink = CursorBlink::new(start);
        let later = start + Duration::from_secs(10);
        assert_eq!(
            earliest_deadline([Some(later), blink.deadline(), None]),
            blink.deadline()
        );
    }

    #[test]
    fn tab_state_machine_creates_switches_and_closes_to_the_adjacent_tab() {
        let mut tabs = vec!["first"];
        tabs.push("second");
        let mut active = tabs.len() - 1;
        assert_eq!(
            (tabs.as_slice(), active),
            (["first", "second"].as_slice(), 1)
        );

        active = 0;
        assert_eq!(active, 0, "clicking a tab changes only the active index");
        assert_eq!(
            tab_close_action(tabs.len(), active, 0),
            TabCloseAction::Keep { active_tab: 0 },
            "closing the active left tab activates its right neighbour"
        );
        tabs.remove(0);
        assert_eq!(tabs, ["second"]);
        assert_eq!(
            tab_close_action(tabs.len(), 0, 0),
            TabCloseAction::CloseWindow,
            "the last tab delegates to the existing WM_CLOSE path"
        );
    }

    #[test]
    fn closing_a_background_tab_preserves_the_same_active_identity() {
        assert_eq!(
            tab_close_action(4, 2, 0),
            TabCloseAction::Keep { active_tab: 1 }
        );
        assert_eq!(
            tab_close_action(4, 1, 3),
            TabCloseAction::Keep { active_tab: 1 }
        );
    }

    /// Ctrl+Tab and Ctrl+Shift+Tab walk the strip in opposite directions and both
    /// wrap, so a four-tab window is a ring with no dead end at either edge.
    #[test]
    fn the_tab_chords_walk_the_strip_in_a_ring() {
        assert_eq!(stepped_tab(4, 0, true), Some(1));
        assert_eq!(stepped_tab(4, 3, true), Some(0), "forward wraps at the end");
        assert_eq!(stepped_tab(4, 3, false), Some(2));
        assert_eq!(
            stepped_tab(4, 0, false),
            Some(3),
            "backward wraps at the start"
        );
        // A full lap in either direction returns to where it started.
        let mut index = 1;
        for _ in 0..4 {
            index = stepped_tab(4, index, true).expect("four tabs step");
        }
        assert_eq!(index, 1);

        // A lone tab is already the answer, so nothing is re-activated.
        assert_eq!(stepped_tab(1, 0, true), None);
        assert_eq!(stepped_tab(1, 0, false), None);
        assert_eq!(stepped_tab(0, 0, true), None);
    }

    /// PIN — **`Ctrl+Shift+↑/↓` walks the commands and stops at both ends**
    /// (§7.1.5c, mock-up 4690-4707).
    ///
    /// The opposite of the strip's ring one test above, and deliberately: a strip
    /// is a set of places you can be in any of, while a rail is a history with a
    /// beginning and an end. Arriving at the oldest command and being thrown to
    /// the newest is not what the key said, and the mock-up's own `if (at < 0)
    /// return` says so too.
    ///
    /// MUTATION: make either end wrap and the first two assertions of the second
    /// block go red — which is the ruling refusing to be turned into a ring.
    #[test]
    fn the_command_walk_stops_at_both_ends_instead_of_wrapping() {
        // Five commands, with the viewport showing the third.
        assert_eq!(
            stepped_command_mark(5, Some(2), Step::Forward),
            Some(3),
            "next is the command after the one on screen"
        );
        assert_eq!(stepped_command_mark(5, Some(2), Step::Back), Some(1));

        // The two ends.
        assert_eq!(
            stepped_command_mark(5, Some(4), Step::Forward),
            None,
            "there is nothing after the newest command"
        );
        assert_eq!(
            stepped_command_mark(5, Some(0), Step::Back),
            None,
            "and nothing before the oldest"
        );

        // A viewport above every mark — scrolled into output older than the
        // oldest surviving command. Forwards is the first of them; backwards has
        // nowhere to go, and inventing the newest would be a wrap by another name.
        assert_eq!(stepped_command_mark(5, None, Step::Forward), Some(0));
        assert_eq!(stepped_command_mark(5, None, Step::Back), None);

        // A pane whose shell sends no OSC 133 at all answers nothing, either way
        // and from anywhere (inventory C13).
        assert_eq!(stepped_command_mark(0, None, Step::Forward), None);
        assert_eq!(stepped_command_mark(0, None, Step::Back), None);

        // A lone command: the viewport is on it, and both keys are silent.
        assert_eq!(stepped_command_mark(1, Some(0), Step::Forward), None);
        assert_eq!(stepped_command_mark(1, Some(0), Step::Back), None);
    }

    /// **The takeover begins with the first character, not with the capsule**
    /// (§7.1.5d, S4).
    ///
    /// One search in the window, so the pane it is on is the only pane whose rail
    /// changes — and an empty field leaves even that one alone. The fourth case is
    /// the one the prototype gets wrong and the reason this predicate has a name.
    ///
    /// MUTATION: drop the `is_empty` clause and `Ctrl+F` recedes the command
    /// history to a fifth of its opacity before a question has been asked; drop the
    /// seat comparison and every pane in the window answers one pane's query.
    #[test]
    fn a_rail_carries_results_only_on_the_searched_pane_and_only_once_something_is_typed() {
        let searched = SeatId(3);
        let other = SeatId(4);
        assert!(rail_is_searching(Some(searched), "cargo", searched));
        assert!(
            !rail_is_searching(Some(searched), "", searched),
            "an open capsule with nothing typed has asked nothing"
        );
        assert!(
            !rail_is_searching(Some(searched), "cargo", other),
            "one search, one pane"
        );
        assert!(
            !rail_is_searching(None, "cargo", searched),
            "the query outlives the capsule (B62), the takeover does not"
        );
    }

    /// The jump's flash lands on the row that is **showing** the command, and on
    /// nothing at all when that content is not on the glass.
    ///
    /// Read out of the presented frame's own `cell_anchors` rather than from the
    /// projection, for the reason [`Runtime::command_flash_layer`] gives: the
    /// frame is the picture, and a second derivation of "which row is that
    /// content in" is a second thing that can be off by one.
    ///
    /// MUTATION: drop the containment check at the end of [`frame_row_of_anchor`]
    /// and the last assertion goes red — an anchor below the last drawable row
    /// would light the last one, which is a band drawn over the wrong command.
    #[test]
    fn the_flash_finds_the_row_a_frame_is_showing_a_command_on() {
        let mut session =
            DualPlaneSession::new(NonZeroU32::new(20).unwrap(), NonZeroU32::new(4).unwrap());
        let mut projection = session.new_projection(session.layout_key());
        session.feed(b"one\r\ntwo\r\nthree\r\n").unwrap();
        session.refresh_projection(&mut projection);
        let frame = session
            .viewport_frame(&mut projection)
            .expect("a frame for a four-row grid");
        let columns = frame.columns.get() as usize;

        // Every row of the frame answers itself, which is the property the whole
        // band is placed by.
        for row in 0..frame.drawable_rows() {
            let anchor = frame.cell_anchors[row * columns].start.clone();
            assert_eq!(
                frame_row_of_anchor(&frame, &anchor).map(|found| found.top_subpixels),
                Some(frame.row_map[row].top_subpixels),
                "row {row} does not find itself"
            );
        }

        // The alternate screen is an isolated namespace (§3.2), so its
        // coordinates are neither before nor after this frame's — the honest
        // answer is no row rather than a guessed one.
        assert!(
            frame_row_of_anchor(
                &frame,
                &bt_doc::ContentAnchor::Live {
                    screen: bt_doc::ScreenId::Alternate,
                    point: bt_doc::GridPoint { row: 0, column: 0 },
                    bias: bt_doc::Bias::Before,
                    generation: bt_doc::GridGeneration(1),
                }
            )
            .is_none(),
            "an alternate-screen anchor lights nothing on a primary frame"
        );

        // And content past the bottom of the frame: a row that has not been drawn
        // is not a row the last one may stand in for.
        let past = bt_doc::ContentAnchor::Live {
            screen: bt_doc::ScreenId::Primary,
            point: bt_doc::GridPoint {
                row: frame.grid_rows.get() + 40,
                column: 0,
            },
            bias: bt_doc::Bias::Before,
            generation: bt_doc::GridGeneration(1),
        };
        assert!(frame_row_of_anchor(&frame, &past).is_none());
    }

    /// Ctrl+Shift+1..9 counts the strip the way the user does, and an ordinal past
    /// the end of it names no tab at all.
    #[test]
    fn goto_tab_counts_from_one_and_ignores_an_ordinal_off_the_end() {
        assert_eq!(
            goto_tab_index(4, 1),
            Some(0),
            "the first tab is Ctrl+Shift+1"
        );
        assert_eq!(goto_tab_index(4, 4), Some(3));
        assert_eq!(
            goto_tab_index(4, 5),
            None,
            "there is no fifth tab, and clamping onto the fourth would answer a \
             question nobody asked"
        );
        assert_eq!(goto_tab_index(4, 9), None);
        assert_eq!(goto_tab_index(0, 1), None);
        assert_eq!(goto_tab_index(4, 0), None, "there is no zeroth tab");
    }

