    #[test]
    fn hyperlink_hover_delay_and_departure_are_event_driven() {
        let start = Instant::now();
        let link = hyperlink_hit("file:///actual-target");
        let mut hover = HyperlinkHover::default();

        // The underline is the immediate affordance: a fresh candidate republishes right away and
        // is the underline target long before the tooltip deadline; only the status text waits.
        assert!(hover.observe(Some(link.clone()), start));
        assert_eq!(hover.underline_target(), Some(&link));
        assert!(hover.active.is_none(), "tooltip must not appear instantly");
        assert!(!hover.activate_if_due(start + Duration::from_millis(299)));
        assert!(hover.activate_if_due(start + Duration::from_millis(300)));
        assert_eq!(
            hover.status_text(80).as_deref(),
            Some("file:///actual-target")
        );
        assert!(hover.observe(None, start + Duration::from_millis(301)));
        assert!(hover.active.is_none());
        assert!(hover.underline_target().is_none());
        assert!(hover.show_at.is_none());

        hover.show_blocked(link);
        assert_eq!(
            hover.status_text(80).as_deref(),
            Some("file:///actual-target · blocked")
        );
        assert_eq!(
            hover.status_text(20).as_deref(),
            Some("file:///a… · blocked"),
            "narrow chrome keeps the real target prefix and the blocked verdict visible"
        );
    }

    #[test]
    fn peek_hover_settles_after_the_delay_and_slides_along_one_span_without_restarting() {
        let start = Instant::now();
        let path = PathBuf::from(r"C:\img\a.png");
        let mut hover = PeekHover::default();

        let subject = PeekSubject::from_path(path.clone());
        let pane = SeatId(1);
        assert!(!hover.observe(
            Some((subject.clone(), pane)),
            PhysicalPosition::new(10.0, 10.0),
            start
        ));
        assert!(
            hover
                .activate_if_due(start + Duration::from_millis(299))
                .is_none()
        );
        // Sliding along the same path span refreshes the anchor but keeps the original clock:
        // the flyout settles where the pointer last was, without ever restarting the delay.
        assert!(!hover.observe(
            Some((subject.clone(), pane)),
            PhysicalPosition::new(30.0, 12.0),
            start + Duration::from_millis(200)
        ));
        let settled = hover
            .activate_if_due(start + Duration::from_millis(300))
            .expect("original deadline must fire");
        assert_eq!(settled.subject, subject);
        assert_eq!(settled.pointer.x, 30.0);
        // While active, staying on the span neither hides nor re-arms.
        assert!(!hover.observe(
            Some((subject.clone(), pane)),
            PhysicalPosition::new(31.0, 12.0),
            start + Duration::from_millis(400)
        ));
        assert!(hover.show_at.is_none());
        // Leaving the span hides the flyout and drops all state.
        assert!(hover.observe(
            None,
            PhysicalPosition::new(31.0, 40.0),
            start + Duration::from_millis(500)
        ));
        assert!(hover.active.is_none());
    }

    /// PIN — a peek belongs to the pane the pointer was in, and carries it.
    ///
    /// Two panes, and the *same file* printed in both — which is what makes the pin bite, because
    /// subject identity alone cannot tell the two hovers apart. Sliding from one pane's copy to the
    /// other's has genuinely left the reference the flyout was raised over: the old flyout must go
    /// down, a fresh settle clock must run, and what settles must name the pane it settled in, so
    /// the box can be sized and placed against that pane instead of against whichever one happens
    /// to hold the keyboard.
    ///
    /// Drop the seat from the span's identity and every assertion below reverses.
    #[test]
    fn one_file_printed_in_two_panes_is_two_hovers_and_each_names_its_own_pane() {
        let start = Instant::now();
        let subject = PeekSubject::from_path(PathBuf::from(r"C:\img\shared.png"));
        let left = SeatId(1);
        let right = SeatId(2);
        let mut hover = PeekHover::default();

        assert!(!hover.observe(
            Some((subject.clone(), left)),
            PhysicalPosition::new(100.0, 200.0),
            start
        ));
        let settled = hover
            .activate_if_due(start + Duration::from_millis(300))
            .expect("the left pane's hover settles");
        assert_eq!(
            settled.seat, left,
            "a settled peek names the pane whose cells the pointer was on",
        );

        // Straight across into the other pane's copy of the same file.
        assert!(
            hover.observe(
                Some((subject.clone(), right)),
                PhysicalPosition::new(900.0, 200.0),
                start + Duration::from_millis(400)
            ),
            "leaving the pane takes the flyout down even though the file is the same",
        );
        assert!(
            hover
                .activate_if_due(start + Duration::from_millis(600))
                .is_none(),
            "the second pane's hover runs its own settle clock",
        );
        let settled = hover
            .activate_if_due(start + Duration::from_millis(700))
            .expect("the right pane's hover settles in its turn");
        assert_eq!(settled.seat, right);
        assert_eq!(
            settled.pointer,
            PhysicalPosition::new(900.0, 200.0),
            "the anchor is the window point the hover settled on, untranslated",
        );

        // And staying inside one pane still slides along one span, as it always did.
        assert!(!hover.observe(
            Some((subject, right)),
            PhysicalPosition::new(920.0, 200.0),
            start + Duration::from_millis(800)
        ));
        assert!(hover.show_at.is_none());
    }

    #[test]
    fn peek_hover_switching_paths_hides_the_old_flyout_and_restarts_the_clock() {
        let start = Instant::now();
        let first = PeekSubject::from_path(PathBuf::from(r"C:\img\a.png"));
        let second = PeekSubject::from_path(PathBuf::from(r"C:\img\b.png"));
        let mut hover = PeekHover::default();
        let pane = SeatId(1);
        hover.observe(
            Some((first, pane)),
            PhysicalPosition::new(10.0, 10.0),
            start,
        );
        assert!(
            hover
                .activate_if_due(start + Duration::from_millis(300))
                .is_some()
        );
        let hidden = hover.observe(
            Some((second.clone(), pane)),
            PhysicalPosition::new(50.0, 10.0),
            start + Duration::from_millis(400),
        );
        assert!(hidden, "switching spans must hide the visible flyout");
        assert!(
            hover
                .activate_if_due(start + Duration::from_millis(600))
                .is_none(),
            "the second span runs a fresh settle clock"
        );
        let settled = hover
            .activate_if_due(start + Duration::from_millis(700))
            .expect("second span settles on its own deadline");
        assert_eq!(settled.subject, second);
    }

    /// PIN (user repro 2026-08-02, re-seated by the frame-derived ruling 2026-08-04): one hovered
    /// cell resolves to one reference, through the frame's own row stride, and where a printed path
    /// and a link target cover the same cell the pointer answers with the text it is standing on.
    ///
    /// What the four verbs share is this lookup: the scan produced the list, and hover, click and
    /// peek all ask it the same question about the same `GridHit`. The list's own contents — which
    /// shapes are in it, and that a `file://` to a `.txt` is in none — are bt-term's to pin, beside
    /// the detector that decides it (`underline_coverage_equals_peek_coverage_for_every_shape`).
    #[test]
    fn one_hit_resolves_to_one_reference_through_the_frames_own_stride() {
        let printed = PathBuf::from(r"D:\from-text.png");
        let linked = PathBuf::from(r"D:\layout-preview.png");
        let references = FrameImageReferences {
            columns: 10,
            references: vec![
                // The scan's order: printed text first, link targets after it.
                bt_term::FrameImageReference {
                    path: printed.clone(),
                    cells: vec![12, 13, 14],
                    verified: true,
                },
                bt_term::FrameImageReference {
                    path: linked.clone(),
                    cells: vec![10, 11, 12, 13, 14, 15],
                    verified: true,
                },
            ],
        };
        let at = |row, column| {
            references
                .at(bt_render::GridHit { row, column })
                .map(|reference| reference.path.clone())
        };
        assert_eq!(
            at(1, 2),
            Some(printed),
            "text under the pointer is what the pointer was put on",
        );
        assert_eq!(
            at(1, 0),
            Some(linked),
            "and the link answers where its label spells no file",
        );
        assert_eq!(at(1, 6), None, "one column past the link is ordinary text");
        assert_eq!(at(0, 2), None, "the row is part of the address");
        assert_eq!(
            FrameImageReferences::default().at(bt_render::GridHit { row: 0, column: 0 }),
            None,
            "a frame with no references answers nothing anywhere",
        );
    }

    /// PIN (band retirement ruling, 2026-08-03, docs §6.1): the peek's third source is an OSC 1337
    /// payload, which names no file, and the pipeline tells the two apart by exactly one property —
    /// whether a cache miss has anything to read.
    ///
    /// A named file's identity is its normalized path, so the same file spelled two ways is one
    /// hover and one cache entry. A payload's identity is the decoder's content key, and it carries
    /// no path at all: the bytes came through the stream and were remembered when the decode landed,
    /// so a miss is a hover that arrived early, never a disk read to schedule. That `path: None` is
    /// the whole of the difference is what keeps `show_or_request_peek` one function.
    #[test]
    fn a_stream_payload_is_a_peek_subject_with_nothing_to_read() {
        let by_path = PeekSubject::from_path(PathBuf::from(r"C:\img\a.png"));
        assert_eq!(
            by_path.key,
            normalized_local_image_path_key(std::path::Path::new(r"C:\img\a.png")),
            "a named file is identified the way the decoder identifies it",
        );
        assert!(by_path.path.is_some(), "a named file is readable on a miss");
        assert_eq!(
            PeekSubject::from_path(PathBuf::from(r"C:\IMG\A.PNG")),
            by_path,
            "one file spelled two ways is one hover and one cache entry",
        );

        let payload = PeekSubject::from_content_key("image:sha-abc".to_owned());
        assert_eq!(payload.key, "image:sha-abc");
        assert!(
            payload.path.is_none(),
            "a stream payload has no file behind it, so a cache miss reads nothing",
        );
        assert_ne!(payload, by_path);
    }

    /// PIN (verification ruling 2026-08-04, the warm peek): the decode a verified reference already
    /// paid for is filed under the very key the hover looks up, so the flyout opens from cache and
    /// no second read of the same file is ever scheduled.
    ///
    /// `show_or_request_peek` sends a `PeekImage` task on exactly one condition — a `None` entry
    /// under `PeekSubject::key`. So "the peek is warm" and "the two keys are the same string" are
    /// the same statement, and it is the one asserted here. The stream-payload arm is asserted
    /// beside it because both shapes go through this one function and must not converge: a payload
    /// has no path to key by.
    ///
    /// RED CHECK: keying a named file's verification decode by `decoded.key` (its content identity)
    /// instead of its path leaves the hover's lookup missing, and the first assertion goes red —
    /// which is precisely the "decoded twice, cached twice" defect the shared key rules out.
    #[test]
    fn a_verified_references_decode_is_filed_under_the_key_the_hover_asks_by() {
        let path = PathBuf::from(r"C:\img\Sunset.PNG");
        let decoded = bt_term::DecodedInlineImage {
            occurrence_id: 7,
            key: "image:0123456789abcdef0123456789abcdef".to_owned(),
            rgba: Arc::from(vec![0u8; 4]),
            width_px: 1,
            height_px: 1,
            animated: false,
        };

        assert_eq!(
            peek_cache_key_for_decode(
                &bt_term::InlineImageSource::LocalPath(path.clone()),
                &decoded
            ),
            PeekSubject::from_path(path.clone()).key,
            "the verification decode lands exactly where the hover will look for it",
        );
        assert_eq!(
            peek_cache_key_for_decode(
                &bt_term::InlineImageSource::LocalPath(PathBuf::from(r"c:/img/sunset.png")),
                &decoded
            ),
            PeekSubject::from_path(path).key,
            "and one file spelled two ways is still one warm entry",
        );
        assert_eq!(
            peek_cache_key_for_decode(
                &bt_term::InlineImageSource::Osc1337(b"AAAA".to_vec()),
                &decoded
            ),
            PeekSubject::from_content_key(decoded.key.clone()).key,
            "a stream payload has no path, so it stays keyed by content",
        );
    }

    /// Pin (a) of the peek raster defect: every peek pixel that reaches the renderer is one the
    /// flyout draws. The chain the app runs — the renderer's box, the worker's resample, the
    /// thumbnail slot, the overlay — is walked end to end here, so a future edit that hands the
    /// renderer a native decode again fails on the resident byte count and on the texture key.
    #[test]
    fn the_peek_overlay_carries_display_sized_pixels_under_a_display_sized_key() {
        // A decode far larger than any flyout: 1024x768 in a 640x480 pane.
        let (native_width_px, native_height_px) = (1024_u32, 768_u32);
        let native_rgba: Arc<[u8]> =
            Arc::from(vec![
                0x40_u8;
                native_width_px as usize * native_height_px as usize * 4
            ]);
        let content_key = "image:0123456789abcdef0123456789abcdef".to_owned();

        let (display_width_px, display_height_px) = bt_render::peek_thumbnail_extent(
            640.0,
            480.0,
            8.0,
            1.0,
            native_width_px,
            native_height_px,
        )
        .expect("the pane can host the flyout");
        assert!(
            display_width_px < native_width_px && display_height_px < native_height_px,
            "the 40% cap is what makes the flyout smaller than its decode",
        );

        let target: PeekThumbnailTarget =
            (content_key.clone(), display_width_px, display_height_px);
        let task = peek_scale_task(
            &target,
            Arc::clone(&native_rgba),
            native_width_px,
            native_height_px,
        );
        let thumbnail = PeekThumbnail::from_scaled(bt_term::scale_inline_image(&task));
        let overlay = thumbnail.overlay(
            bt_render::SeatViewport {
                x: 0,
                y: 0,
                width: 640,
                height: 480,
            },
            PhysicalPosition::new(120.0, 90.0),
        );
        assert_eq!(
            (overlay.width_px, overlay.height_px),
            (display_width_px, display_height_px),
        );
        assert_eq!(
            overlay.rgba.len(),
            display_width_px as usize * display_height_px as usize * 4,
            "the resident bytes the renderer uploads are the display box, not the decode",
        );
        assert!(
            overlay.rgba.len() * 16 < native_rgba.len(),
            "the defect uploaded {} bytes where {} suffice",
            native_rgba.len(),
            overlay.rgba.len(),
        );
        assert_eq!(
            overlay.key,
            bt_term::display_texture_key(&content_key, display_width_px, display_height_px),
            "the display size is part of the texture identity, so the shared LRU can never \
             serve a raster sized for another box",
        );
        assert!(
            thumbnail.matches(&target),
            "the slot answers the question the hover asked, so a raster for another box is \
             never presented as this one",
        );
    }

    #[test]
    fn osc_8_display_text_hits_the_real_target_uri() {
        let mut session =
            DualPlaneSession::new(NonZeroU32::new(24).unwrap(), NonZeroU32::new(2).unwrap());
        session
            .feed(b"\x1b]8;;https://actual.example/login\x1b\\trusted label\x1b]8;;\x1b\\")
            .unwrap();
        let mut projection = session.new_projection(session.layout_key());
        let mut frame = session.viewport_frame(&mut projection).unwrap();

        let hit = frame.hyperlink_at(0, 4).unwrap();
        assert_eq!(hit.uri, "https://actual.example/login");
        assert!(frame.underline_hyperlink(&hit));
        assert!(frame.cells[..13].iter().all(|cell| {
            cell.style
                .flags
                .contains(bt_transcript::CellFlags::UNDERLINE)
        }));
        assert!(
            !frame.cells[13]
                .style
                .flags
                .contains(bt_transcript::CellFlags::UNDERLINE)
        );
    }

    /// The resting dots belong to every pane; only the upgrade belongs to the pointer.
    ///
    /// `apply_hover_marks` is the hover half, and both build points run it for `hover_pane` alone
    /// — `publish_frame_inner` for the focused leaf, `redraw` for the rest. The resting dotted
    /// underline is projection's, applied inside `viewport_frame` for whichever leaf is being
    /// built, which is what lets a pane the pointer has never entered still advertise its links.
    ///
    /// Both branches are walked here the way `redraw` walks them: project, then offer the hover
    /// marks only to the pane under the pointer. Move the resting mark into `apply_hover_marks`,
    /// or gate projection on the hovered leaf, and the quiet pane's link comes out bare.
    #[test]
    fn a_pane_the_pointer_never_entered_still_wears_the_resting_link_dots() {
        let link = b"\x1b]8;;https://actual.example/login\x1b\\docs\x1b]8;;\x1b\\";
        let pane = || {
            let mut session =
                DualPlaneSession::new(NonZeroU32::new(24).unwrap(), NonZeroU32::new(2).unwrap());
            session.feed(link).unwrap();
            let projection = session.new_projection(session.layout_key());
            (session, projection)
        };
        let dots = |frame: &ViewportFrame| {
            frame.cells[..4]
                .iter()
                .filter(|cell| {
                    cell.style
                        .flags
                        .contains(bt_transcript::CellFlags::DOTTED_UNDERLINE)
                })
                .count()
        };
        let solid = |frame: &ViewportFrame| {
            frame.cells[..4]
                .iter()
                .filter(|cell| {
                    cell.style
                        .flags
                        .contains(bt_transcript::CellFlags::UNDERLINE)
                })
                .count()
        };

        // The pane nobody has pointed at: projected, and then left alone.
        let (quiet_session, mut quiet_projection) = pane();
        quiet_session.refresh_projection(&mut quiet_projection);
        let quiet = quiet_session.viewport_frame(&mut quiet_projection).unwrap();
        assert_eq!(
            dots(&quiet),
            4,
            "a link in a pane the pointer has never entered still wears its resting dots"
        );
        assert_eq!(
            solid(&quiet),
            0,
            "and wears nothing the pointer is supposed to have brought"
        );

        // The pane under the pointer: projected, and then decorated.
        let (hovered_session, mut hovered_projection) = pane();
        hovered_session.refresh_projection(&mut hovered_projection);
        let mut hovered = hovered_session
            .viewport_frame(&mut hovered_projection)
            .unwrap();
        let hit = hovered
            .hyperlink_at(0, 1)
            .expect("the link is under the pointer");
        assert!(hovered.underline_hyperlink(&hit));
        assert_eq!(
            solid(&hovered),
            4,
            "the pane under the pointer upgrades the same link to a solid underline"
        );
        assert_eq!(
            dots(&hovered),
            0,
            "and the upgrade replaces the dots rather than doubling them"
        );
    }

    struct PtyPresentationHarness {
        session: DualPlaneSession,
        projection: ViewportProjection,
        pending: LatestFrameSlot,
        last_presented: Option<ViewportFrame>,
        publications: usize,
        /// **What the P0 fix is measured in.** Every call this harness makes to
        /// `DualPlaneSession::viewport_frame` — the whole-grid capture, the
        /// projection and the decoration pass that an animation tick used to
        /// pay for sixty times a second.
        viewport_frames: usize,
        /// [`Runtime::terminal_content_revision`], on the same bump: a frame
        /// that actually entered the slot.
        content_revision: u64,
        /// [`Runtime::presented_picture_revision`], on the same bump: a frame
        /// that actually reached the glass.
        presented_revision: u64,
    }

    impl PtyPresentationHarness {
        fn new(columns: u32, rows: u32) -> Self {
            let session = DualPlaneSession::new(
                NonZeroU32::new(columns).unwrap(),
                NonZeroU32::new(rows).unwrap(),
            );
            let projection = session.new_projection(session.layout_key());
            Self {
                session,
                projection,
                pending: LatestFrameSlot::default(),
                last_presented: None,
                publications: 0,
                viewport_frames: 0,
                content_revision: 0,
                presented_revision: 0,
            }
        }

        /// What `Runtime::picture_on_glass` reads, off this harness's mirror of
        /// the same five facts.
        fn picture_on_glass(&self) -> PictureOnGlass {
            PictureOnGlass {
                frame_pending: self.pending.pending_frame().is_some(),
                has_presented_frame: self.last_presented.is_some(),
                presentation_hold: self.projection.presentation_hold(),
                content_revision: self.content_revision,
                presented_revision: self.presented_revision,
            }
        }

        /// One turn of the tab strip's indeterminate ring.
        ///
        /// `reuse` is the policy under test, injected rather than called
        /// directly so a test can run the *mutant* — the unconditional
        /// reprojection this window shipped with — through the identical loop
        /// and show what it costs.
        fn chrome_tick(&mut self, reuse: fn(PictureOnGlass) -> bool) {
            if reuse(self.picture_on_glass()) {
                // `Runtime::present_retained_picture`: the glass is redrawn
                // from the frame it already holds. No session, no projection.
                self.present_pending();
                return;
            }
            self.publish_expose_frame();
            self.present_pending();
        }

        /// `publish_frame_inner` for a source that is not PTY output: composes
        /// unconditionally, with no unchanged-frame gate to fall back on.
        fn publish_expose_frame(&mut self) -> bool {
            self.session.refresh_projection(&mut self.projection);
            self.viewport_frames += 1;
            let frame = self.session.viewport_frame(&mut self.projection).unwrap();
            if self.projection.presentation_hold() && self.last_presented.is_some() {
                return false;
            }
            self.content_revision += 1;
            self.pending
                .publish(
                    frame,
                    FrameTrigger {
                        occurred_at: Instant::now(),
                        source: FrameSource::Expose,
                    },
                )
                .unwrap();
            self.publications += 1;
            true
        }

        fn feed_drain(&mut self, bytes: &[u8]) -> bool {
            self.session.feed(bytes).unwrap();
            self.publish_pty_frame()
        }

        fn finish_synchronized_update(&mut self) -> (bool, bool) {
            let finished = self
                .session
                .finish_synchronized_update(Instant::now())
                .unwrap();
            let published = finished && self.publish_pty_frame();
            (finished, published)
        }

        fn publish_pty_frame(&mut self) -> bool {
            self.session.refresh_projection(&mut self.projection);
            self.viewport_frames += 1;
            let frame = self.session.viewport_frame(&mut self.projection).unwrap();
            // Mirror publish_frame_inner's combined review/exact-source presentation hold.
            if self.projection.presentation_hold() && self.last_presented.is_some() {
                return false;
            }
            if pty_frame_is_unchanged(
                self.pending.pending_frame(),
                self.last_presented.as_ref(),
                &frame,
            ) {
                return false;
            }
            self.pending
                .publish(
                    frame,
                    FrameTrigger {
                        occurred_at: Instant::now(),
                        source: FrameSource::PtyOutput,
                    },
                )
                .unwrap();
            self.content_revision += 1;
            self.publications += 1;
            true
        }

        fn present_pending(&mut self) -> bool {
            let Some((frame, _)) = self.pending.take() else {
                return false;
            };
            self.last_presented = Some(frame);
            self.presented_revision = self.content_revision;
            true
        }
    }

    /// The mutant: the window this fix replaced, which reprojected on every
    /// animation tick no matter what the picture on the glass already said.
    fn always_recompose(_: PictureOnGlass) -> bool {
        false
    }

    /// **P0.** Six hundred turns of the tab strip's ring — ten seconds of a
    /// command that prints nothing — must not project the grid once.
    ///
    /// This is the burn the diagnosis measured at 69% of a core: the ring's
    /// 16ms deadline held `session.working = true` for a command's whole life,
    /// and every tick of it composed a whole terminal picture to redraw a
    /// fifteen-pixel arc.
    #[test]
    fn strip_animation_ticks_project_nothing_while_the_grid_is_still() {
        let mut harness = PtyPresentationHarness::new(80, 24);
        harness.feed_drain(b"$ sleep 30\r\n");
        harness.present_pending();
        let projections_before = harness.viewport_frames;
        let revision_before = harness.content_revision;

        for _ in 0..600 {
            harness.chrome_tick(chrome_tick_reuses_picture);
        }

        assert_eq!(
            harness.viewport_frames - projections_before,
            0,
            "an animation tick must be answered from the picture on the glass"
        );
        assert_eq!(
            harness.content_revision, revision_before,
            "nothing said anything new, so no picture became newer than the glass"
        );
    }

    /// The same six hundred ticks under the mutant, so the assertion above is
    /// known to have teeth: the count it asserts is zero was six hundred.
    #[test]
    fn the_unconditional_reprojection_this_replaced_costs_one_projection_a_tick() {
        let mut harness = PtyPresentationHarness::new(80, 24);
        harness.feed_drain(b"$ sleep 30\r\n");
        harness.present_pending();
        let projections_before = harness.viewport_frames;

        for _ in 0..600 {
            harness.chrome_tick(always_recompose);
        }

        assert_eq!(harness.viewport_frames - projections_before, 600);
    }

    /// The other half of the contract: content that *does* change is projected,
    /// exactly once, and the ticks around it still cost nothing.
    #[test]
    fn output_between_animation_ticks_is_projected_exactly_once() {
        let mut harness = PtyPresentationHarness::new(80, 24);
        harness.feed_drain(b"$ sleep 30\r\n");
        harness.present_pending();

        for _ in 0..60 {
            harness.chrome_tick(chrome_tick_reuses_picture);
        }
        let projections_before = harness.viewport_frames;

        harness.feed_drain(b"a line of output\r\n");
        assert_eq!(
            harness.viewport_frames - projections_before,
            1,
            "the shell spoke once and the grid was projected once"
        );
        assert!(
            harness.pending.pending_frame().is_some(),
            "the new picture is composed and waiting for the glass"
        );

        // The tick that lands while it waits presents *that* frame rather than
        // composing a second one on top of it.
        harness.chrome_tick(chrome_tick_reuses_picture);
        assert_eq!(harness.viewport_frames - projections_before, 1);
        assert_eq!(harness.presented_revision, harness.content_revision);

        for _ in 0..60 {
            harness.chrome_tick(chrome_tick_reuses_picture);
        }
        assert_eq!(
            harness.viewport_frames - projections_before,
            1,
            "and the ticks after it are free again"
        );
    }

    /// **The ring turns at the rate the constant declares — no faster.**
    ///
    /// A second of wall clock offered to the loop one millisecond at a time,
    /// which is what a window whose every present wakes `about_to_wait` again
    /// actually looks like. Sixty-two steps, not a thousand.
    #[test]
    fn the_strip_animation_moves_at_its_own_declared_rate() {
        let start = Instant::now();
        let mut last = None;
        let mut ticks = 0;
        for millisecond in 0..1000 {
            let now = start + Duration::from_millis(millisecond);
            if strip_animation_tick_is_due(last, now) {
                last = Some(now);
                ticks += 1;
            }
        }
        assert_eq!(
            ticks,
            1000_u32.div_ceil(STRIP_ANIMATION_FRAME.as_millis() as u32),
            "one step per {}ms and not one more",
            STRIP_ANIMATION_FRAME.as_millis()
        );
    }

    /// And it is never *slower* than the constant either: a tick offered
    /// exactly one frame after the last is due, not one frame and a bit.
    #[test]
    fn a_tick_offered_exactly_one_frame_later_is_due() {
        let start = Instant::now();
        assert!(strip_animation_tick_is_due(None, start), "the first ever");
        assert!(strip_animation_tick_is_due(
            Some(start),
            start + STRIP_ANIMATION_FRAME
        ));
        assert!(!strip_animation_tick_is_due(
            Some(start),
            start + STRIP_ANIMATION_FRAME - Duration::from_micros(1)
        ));
    }

    /// A window with nothing on the glass yet composes, whatever else is true.
    /// There is exactly one such window per lifetime and it is the one whose
    /// first picture nobody else is coming to draw.
    #[test]
    fn the_first_picture_is_never_answered_from_an_empty_screen() {
        assert!(!chrome_tick_reuses_picture(PictureOnGlass {
            frame_pending: false,
            has_presented_frame: false,
            presentation_hold: false,
            content_revision: 0,
            presented_revision: 0,
        }));
    }

    /// A picture that was composed and never presented is not the picture on
    /// the glass, so the tick that finds one waiting presents it instead of
    /// building a third.
    #[test]
    fn a_composed_frame_still_waiting_is_presented_rather_than_recomposed() {
        assert!(chrome_tick_reuses_picture(PictureOnGlass {
            frame_pending: true,
            has_presented_frame: true,
            presentation_hold: false,
            content_revision: 9,
            presented_revision: 8,
        }));
    }

    /// A held picture is the picture by decision: composing under a hold builds
    /// a frame `publish_frame_inner` throws away a few lines later.
    #[test]
    fn a_presentation_hold_is_answered_from_the_glass_it_is_holding() {
        assert!(chrome_tick_reuses_picture(PictureOnGlass {
            frame_pending: false,
            has_presented_frame: true,
            presentation_hold: true,
            content_revision: 9,
            presented_revision: 4,
        }));
    }

    /// And the case the revisions exist for: a picture newer than the glass,
    /// with nothing queued to carry it there, is composed.
    #[test]
    fn a_picture_newer_than_the_glass_is_composed() {
        assert!(!chrome_tick_reuses_picture(PictureOnGlass {
            frame_pending: false,
            has_presented_frame: true,
            presentation_hold: false,
            content_revision: 9,
            presented_revision: 8,
        }));
    }

    fn frame_row_text(frame: &ViewportFrame, row: usize) -> String {
        let columns = frame.columns.get() as usize;
        frame.cells[row * columns..(row + 1) * columns]
            .iter()
            .map(|cell| cell.text.as_str())
            .collect()
    }

    /// Everything a pane is showing, as one string, so a test can ask whether a
    /// word is on the glass without knowing which row it landed on.
    fn frame_text(frame: &ViewportFrame) -> String {
        (0..frame.drawable_rows())
            .map(|row| frame_row_text(frame, row))
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// **The window this bug lives in**: the pane holding the keyboard, and a
    /// pane beside it.
    ///
    /// Driven through the same three steps the runtime takes on every turn of
    /// its loop, in the same order and with the same dependency between them:
    /// `drain_pty` hears every shell, `publish_frame_inner` composes **the
    /// focused leaf only** and may drop the frame, and `redraw` — which runs for
    /// a frame that reached the slot and for nothing else — is the one and only
    /// place the *other* pane is projected and drawn.
    ///
    /// That last sentence is the whole bug: judge the drain by the focused
    /// pane's picture and a sibling that has just spoken loses the pass it is
    /// painted in.
    struct TwoPaneHarness {
        focused: DualPlaneSession,
        focused_projection: ViewportProjection,
        sibling: DualPlaneSession,
        sibling_projection: ViewportProjection,
        pending: LatestFrameSlot,
        /// `Runtime::last_presented_frame` — the focused leaf's copy, and what
        /// the unchanged-frame gate compares against.
        focused_on_glass: Option<ViewportFrame>,
        /// `LeafSession::last_presented_frame` for the pane beside it: what the
        /// user can actually read in that half of the window.
        sibling_on_glass: Option<ViewportFrame>,
        /// [`Runtime::unpainted_pane_output`].
        unpainted_pane_output: bool,
        presents: usize,
        /// Every projection this window paid for, both panes counted — the P0
        /// meter, so that a repair for one pane can be shown not to have bought
        /// back the whole-window recompose P0 removed.
        viewport_frames: usize,
    }

    impl TwoPaneHarness {
        fn new(columns: u32, rows: u32) -> Self {
            let pane = || {
                let session = DualPlaneSession::new(
                    NonZeroU32::new(columns).unwrap(),
                    NonZeroU32::new(rows).unwrap(),
                );
                let projection = session.new_projection(session.layout_key());
                (session, projection)
            };
            let (focused, focused_projection) = pane();
            let (sibling, sibling_projection) = pane();
            Self {
                focused,
                focused_projection,
                sibling,
                sibling_projection,
                pending: LatestFrameSlot::default(),
                focused_on_glass: None,
                sibling_on_glass: None,
                unpainted_pane_output: false,
                presents: 0,
                viewport_frames: 0,
            }
        }

        /// One turn of `about_to_wait`: drain both shells, publish if anything
        /// arrived, then the redraw that publish asked for.
        fn turn(
            &mut self,
            focused_bytes: &[u8],
            sibling_bytes: &[u8],
            says_nothing_new: fn(bool, bool) -> bool,
        ) {
            let mut arrived = false;
            if !focused_bytes.is_empty() {
                self.focused.feed(focused_bytes).unwrap();
                arrived = true;
            }
            if !sibling_bytes.is_empty() {
                self.sibling.feed(sibling_bytes).unwrap();
                arrived = true;
                // `drain_tab_pty`: a leaf that is not this tab's focused leaf
                // has spoken, which is what `Runtime::drain_pty` raises the bit
                // for.
                self.unpainted_pane_output = true;
            }
            if arrived {
                self.publish_pty_frame(says_nothing_new);
            }
            self.redraw();
        }

        /// `publish_frame_inner` for a PTY drain: compose the focused leaf, then
        /// drop the frame only if the whole window has nothing to say.
        fn publish_pty_frame(&mut self, says_nothing_new: fn(bool, bool) -> bool) {
            self.focused
                .refresh_projection(&mut self.focused_projection);
            self.viewport_frames += 1;
            let frame = self
                .focused
                .viewport_frame(&mut self.focused_projection)
                .unwrap();
            if says_nothing_new(
                pty_frame_is_unchanged(
                    self.pending.pending_frame(),
                    self.focused_on_glass.as_ref(),
                    &frame,
                ),
                self.unpainted_pane_output,
            ) {
                return;
            }
            self.pending
                .publish(
                    frame,
                    FrameTrigger {
                        occurred_at: Instant::now(),
                        source: FrameSource::PtyOutput,
                    },
                )
                .unwrap();
        }

        /// `Runtime::redraw`. No frame in the slot, no pass — and the sibling
        /// goes on showing whatever it last showed.
        fn redraw(&mut self) {
            let Some((frame, _)) = self.pending.take() else {
                return;
            };
            self.sibling
                .refresh_projection(&mut self.sibling_projection);
            self.viewport_frames += 1;
            self.sibling_on_glass = Some(
                self.sibling
                    .viewport_frame(&mut self.sibling_projection)
                    .unwrap(),
            );
            self.focused_on_glass = Some(frame);
            self.unpainted_pane_output = false;
            self.presents += 1;
        }

        fn sibling_shows(&self, needle: &str) -> bool {
            self.sibling_on_glass
                .as_ref()
                .is_some_and(|frame| frame_text(frame).contains(needle))
        }

        fn focused_shows(&self, needle: &str) -> bool {
            self.focused_on_glass
                .as_ref()
                .is_some_and(|frame| frame_text(frame).contains(needle))
        }
    }

    /// **The mutant**: the policy this fix replaces, in which the focused pane's
    /// picture decided, alone, whether the window had anything to say.
    fn focused_frame_alone(focused_frame_unchanged: bool, _unpainted_pane_output: bool) -> bool {
        focused_frame_unchanged
    }

    /// **The bug, as a count.** A pane that is not holding the keyboard says
    /// something; it must be on the glass at the end of the same turn of the
    /// loop, having cost exactly one present — the rhythm the focused pane gets.
    ///
    /// The second turn is the one that matters: by then the focused pane's
    /// picture is a byte-for-byte match of the one on the glass, so the
    /// unchanged-frame gate — which only ever looks at that pane — says the
    /// window has nothing to say while the other half of it has just scrolled.
    #[test]
    fn a_pane_that_is_not_the_keyboards_reaches_the_glass_on_the_turn_it_speaks() {
        let mut harness = TwoPaneHarness::new(24, 6);
        harness.turn(b"prompt\r\n", b"first\r\n", pty_drain_says_nothing_new);
        assert!(harness.sibling_shows("first"));
        let presents_before = harness.presents;

        harness.turn(b"", b"second\r\n", pty_drain_says_nothing_new);

        assert!(
            harness.sibling_shows("second"),
            "the pane beside the keyboard spoke and is on the glass in the same turn"
        );
        assert_eq!(
            harness.presents,
            presents_before + 1,
            "and it cost one present, not a wait for some unrelated event"
        );
    }

    /// **Same rhythm, not merely eventual.** The turn count from "the shell
    /// spoke" to "it is on the glass" is measured for each pane in turn, under
    /// the identical script. Focus is the only difference between the two, and
    /// it must make no difference to this number.
    #[test]
    fn both_panes_reach_the_glass_in_the_same_number_of_turns() {
        let turns_until_shown = |sibling_speaks: bool| {
            let mut harness = TwoPaneHarness::new(24, 6);
            harness.turn(b"prompt\r\n", b"prompt\r\n", pty_drain_says_nothing_new);
            let (focused_bytes, sibling_bytes): (&[u8], &[u8]) = if sibling_speaks {
                (b"", b"needle\r\n")
            } else {
                (b"needle\r\n", b"")
            };
            let mut spoken = false;
            for turn in 1..=10 {
                harness.turn(
                    if spoken { b"" } else { focused_bytes },
                    if spoken { b"" } else { sibling_bytes },
                    pty_drain_says_nothing_new,
                );
                spoken = true;
                let shown = if sibling_speaks {
                    harness.sibling_shows("needle")
                } else {
                    harness.focused_shows("needle")
                };
                if shown {
                    return turn;
                }
            }
            u32::MAX
        };

        assert_eq!(turns_until_shown(false), 1, "the pane with the keyboard");
        assert_eq!(
            turns_until_shown(true),
            turns_until_shown(false),
            "and the pane without it, on the same turn"
        );
    }

    /// **The mutation.** The identical script with the focused pane's frame as
    /// the only judge — which is what this window shipped — and the sibling
    /// stays on a picture it has already outgrown, for as long as nothing else
    /// happens to publish. Measured on the real machine as 19 wheel notches out
    /// of 20 producing no picture at all.
    #[test]
    fn the_focused_frame_alone_strands_the_other_pane_on_a_stale_picture() {
        let mut harness = TwoPaneHarness::new(24, 6);
        harness.turn(b"prompt\r\n", b"first\r\n", focused_frame_alone);
        assert!(harness.sibling_shows("first"));
        let presents_before = harness.presents;

        for _ in 0..20 {
            harness.turn(b"", b"second\r\n", focused_frame_alone);
        }

        assert!(
            !harness.sibling_shows("second"),
            "twenty turns of a shell talking, and none of it on the glass"
        );
        assert_eq!(
            harness.presents, presents_before,
            "because not one frame was ever published to draw it in"
        );
    }

    /// **And P0 is not bought back.** With every pane beside the keyboard
    /// silent, the gate is the one P0 installed, exactly: the focused frame's
    /// own answer and nothing else.
    #[test]
    fn a_silent_sibling_leaves_the_unchanged_frame_gate_exactly_as_p0_left_it() {
        for focused_frame_unchanged in [false, true] {
            assert_eq!(
                pty_drain_says_nothing_new(focused_frame_unchanged, false),
                focused_frame_unchanged,
                "nothing else is speaking, so this is P0's question and no other"
            );
        }
        assert!(
            !pty_drain_says_nothing_new(true, true),
            "and a pane that has spoken is not answered by another pane's stillness"
        );
    }

    /// The same promise as a count, through the whole loop: once the sibling's
    /// words are on the glass, turns in which nobody speaks cost no projection
    /// and no present.
    #[test]
    fn turns_in_which_nobody_speaks_cost_nothing_in_a_split_window() {
        let mut harness = TwoPaneHarness::new(24, 6);
        harness.turn(b"prompt\r\n", b"first\r\n", pty_drain_says_nothing_new);
        harness.turn(b"", b"second\r\n", pty_drain_says_nothing_new);
        assert!(harness.sibling_shows("second"));
        let projections_before = harness.viewport_frames;
        let presents_before = harness.presents;

        for _ in 0..600 {
            harness.turn(b"", b"", pty_drain_says_nothing_new);
        }

        assert_eq!(harness.viewport_frames, projections_before);
        assert_eq!(harness.presents, presents_before);
    }

    #[test]
    fn a_resize_reflow_holds_until_projectable_staging_reanchors_the_reprint() {
        let start = Instant::now();
        let mut harness = PtyPresentationHarness::new(40, 10);
        let mut lines = Vec::new();
        for index in 0..60 {
            lines.extend_from_slice(format!("line-{index:03}\r\n").as_bytes());
        }
        harness.session.feed(&lines).unwrap();
        assert!(harness.publish_pty_frame());
        harness.present_pending();

        // Enter review.
        harness.projection.scroll_by_rows(20);
        assert!(harness.publish_pty_frame());
        harness.present_pending();
        assert_eq!(
            harness.last_presented.as_ref().unwrap().scroll_offset_rows,
            20
        );
        let publications_before = harness.publications;

        // A resize opens the transaction and Codex clears scrollback: the review anchor vanishes
        // and history is transiently empty. The interim frame is bottom-snapped, but presentation
        // must hold the last frame rather than flash to the bottom.
        harness
            .session
            .resize_at(
                NonZeroU32::new(40).unwrap(),
                NonZeroU32::new(12).unwrap(),
                start,
            )
            .unwrap();
        harness.session.mark_pty_resize_requested_at(
            NonZeroU32::new(40).unwrap(),
            NonZeroU32::new(12).unwrap(),
            start + Duration::from_millis(10),
        );
        harness
            .session
            .feed_at(b"\x1b[2J\x1b[3J\x1b[H", start + Duration::from_millis(20))
            .unwrap();
        assert!(
            !harness.publish_pty_frame(),
            "the hold skips publishing the bottom-snapped interim frame"
        );
        assert!(
            !harness.present_pending(),
            "nothing was published to present"
        );
        assert_eq!(
            harness.publications, publications_before,
            "no new publication during the hold"
        );
        assert_eq!(
            harness.last_presented.as_ref().unwrap().scroll_offset_rows,
            20,
            "the screen still shows the reviewing frame, not the bottom"
        );

        // The reprint enters projectable resize staging: publication resumes immediately at the
        // restored review position — a direct hand-off with no bottom frame ever presented.
        harness
            .session
            .feed_at(&lines, start + Duration::from_millis(30))
            .unwrap();
        assert!(
            harness.publish_pty_frame(),
            "resize staging releases the hold as soon as the reprint is reachable"
        );
        harness.present_pending();
        assert_eq!(
            harness.last_presented.as_ref().unwrap().scroll_offset_rows,
            20,
            "presentation resumes exactly at the staged review displacement"
        );

        // Quiescence commits the same staging ids through normal history relocation and must not
        // move the already-restored reading position.
        assert!(
            harness
                .session
                .finish_resize_if_quiescent(start + Duration::from_millis(280))
                .unwrap()
        );
        if harness.publish_pty_frame() {
            harness.present_pending();
        }
        assert_eq!(
            harness.last_presented.as_ref().unwrap().scroll_offset_rows,
            20,
            "final harvest preserves the already-restored review displacement"
        );
    }

    #[test]
    fn a_late_zoom_reprint_keeps_the_last_formula_frame_until_exact_source_reanchors() {
        let start = Instant::now();
        let mut harness = PtyPresentationHarness::new(40, 24);
        harness
            .session
            .feed_at(b"intro\r\n$$x$$\r\nbarrier", start)
            .unwrap();
        assert_eq!(
            harness
                .session
                .advance_live_stability(start + bt_term::LIVE_MATH_STABLE_INTERVAL),
            1
        );
        let mut initial_task = harness.session.take_live_worker_task().unwrap();
        let initial_raster =
            render_live_detection_task(&MathEngine::new(), &mut initial_task, foreground_rgb())
                .expect("initial formula rasterizes");
        assert!(
            harness
                .session
                .complete_live_worker_result(initial_task, Ok(initial_raster))
        );
        assert!(harness.publish_pty_frame());
        assert!(harness.present_pending());
        assert_eq!(
            harness.last_presented.as_ref().unwrap().math_blocks.len(),
            1
        );

        // Match reconcile_authoritative_dpi: metrics, grid resize, then the new-DPI layout key.
        let zoom_at = start + Duration::from_millis(210);
        harness.session.set_cell_height_subpixels(
            NonZeroI64::new(14 * bt_viewport::SUBPIXELS_PER_PX).unwrap(),
        );
        harness
            .session
            .set_cell_width_subpixels(NonZeroI64::new(7 * bt_viewport::SUBPIXELS_PER_PX).unwrap());
        harness.session.set_ascii_baseline_subpixels(
            NonZeroI64::new(11 * bt_viewport::SUBPIXELS_PER_PX).unwrap(),
        );
        harness
            .session
            .resize_at(
                NonZeroU32::new(52).unwrap(),
                NonZeroU32::new(32).unwrap(),
                zoom_at,
            )
            .unwrap();
        harness.session.mark_pty_resize_requested_at(
            NonZeroU32::new(52).unwrap(),
            NonZeroU32::new(32).unwrap(),
            zoom_at,
        );
        harness.session.set_layout_key(bt_doc::LayoutKey {
            width_cells: NonZeroU32::new(52).unwrap(),
            dpi_milli: NonZeroU32::new(800).unwrap(),
            font_rev: 1,
            theme_rev: harness.session.layout_key().theme_rev,
        });
        let delayed_relayout = harness.session.take_live_worker_task().unwrap();
        assert!(harness.publish_pty_frame());
        assert!(harness.present_pending());
        assert!(
            harness
                .session
                .finish_resize_if_quiescent(zoom_at + Duration::from_millis(300))
                .unwrap()
        );

        let publications_before_gap = harness.publications;
        harness
            .session
            .feed_at(
                b"\x1b[2J\x1b[H\x1b[3Jintro\r\n$",
                zoom_at + Duration::from_millis(310),
            )
            .unwrap();
        assert!(
            !harness.publish_pty_frame(),
            "publish_frame_inner must skip the diagnosed incomplete reprint frame"
        );
        assert!(!harness.present_pending());
        assert_eq!(harness.publications, publications_before_gap);
        assert_eq!(
            harness.last_presented.as_ref().unwrap().math_blocks.len(),
            1,
            "the swapchain remains on the last complete formula frame"
        );

        harness
            .session
            .feed_at(b"$x$$\r\nbarrier", zoom_at + Duration::from_millis(324))
            .unwrap();
        let reanchor_published = harness.publish_pty_frame();
        assert!(
            !harness.projection.presentation_hold(),
            "exact-source re-anchor releases the hold immediately"
        );
        if reanchor_published {
            assert!(harness.present_pending());
        }
        assert_eq!(
            harness.last_presented.as_ref().unwrap().math_blocks.len(),
            1
        );

        // The re-anchored stale frame may be content-identical to last_presented and therefore need
        // no publication. Either way, no incomplete grid frame entered the presentation slot.
        drop(delayed_relayout);
    }

    #[test]
    fn keyboard_mapping_is_ascii_only_and_preserves_terminal_controls() {
        assert_eq!(
            input::keyboard_bytes(
                &Key::Character("hello".into()),
                ModifiersState::empty(),
                false
            ),
            Some(b"hello".to_vec())
        );
        assert_eq!(
            input::keyboard_bytes(&Key::Named(NamedKey::Enter), ModifiersState::empty(), false),
            Some(vec![b'\r'])
        );
        assert_eq!(
            input::keyboard_bytes(
                &Key::Named(NamedKey::Backspace),
                ModifiersState::empty(),
                false
            ),
            Some(vec![0x7f])
        );
        assert_eq!(
            input::keyboard_bytes(&Key::Named(NamedKey::Space), ModifiersState::empty(), false),
            Some(vec![b' '])
        );
        assert_eq!(
            input::keyboard_bytes(&Key::Character("c".into()), ModifiersState::CONTROL, false),
            Some(vec![0x03])
        );
        // Every bare `Ctrl+letter` is the shell's and is sent as its control
        // code (2026-08-17: `^X` used to be swallowed here, and with it `^B`,
        // `^L`, `^R` — the whole readline alphabet the shortcut table promised
        // to leave alone).
        assert_eq!(
            input::keyboard_bytes(&Key::Character("x".into()), ModifiersState::CONTROL, false),
            Some(vec![0x18])
        );
        assert_eq!(
            input::keyboard_bytes(&Key::Character("中".into()), ModifiersState::empty(), false),
            None
        );
        assert_eq!(
            input::keyboard_bytes(
                &Key::Named(NamedKey::Process),
                ModifiersState::CONTROL,
                false
            ),
            None
        );
    }

    #[test]
    fn ime_commit_is_the_exact_utf8_pty_payload() {
        assert_eq!(
            ime_commit_bytes("你好世界"),
            vec![
                0xe4, 0xbd, 0xa0, 0xe5, 0xa5, 0xbd, 0xe4, 0xb8, 0x96, 0xe7, 0x95, 0x8c,
            ]
        );
    }

    #[test]
    fn committed_utf8_projects_as_alacritty_wide_lead_and_spacer_cells() {
        let mut session = DualPlaneSession::with_quotas_and_cell_height(
            NonZeroU32::new(8).unwrap(),
            NonZeroU32::new(2).unwrap(),
            DEFAULT_STAGING_QUOTA,
            M0_FROZEN_LINE_QUOTA,
            std::num::NonZeroI64::new(22 * bt_viewport::SUBPIXELS_PER_PX).unwrap(),
        );
        session.feed(&ime_commit_bytes("A你B")).unwrap();
        let mut projection = session.new_projection(session.layout_key());
        let frame = session.viewport_frame(&mut projection).unwrap();

        assert_eq!(frame.cells[0].text, "A");
        assert_eq!(frame.cells[1].text, "你");
        assert!(
            frame.cells[1]
                .style
                .flags
                .contains(bt_transcript::CellFlags::WIDE_CHAR)
        );
        assert!(frame.cells[2].wide_spacer);
        assert_eq!(frame.cells[3].text, "B");
    }

    #[test]
