    #[test]
    fn a_grabbed_tab_follows_the_hand_until_the_strip_runs_out() {
        // K115. The tab travels in x, and stops at the strip's own edges rather
        // than being carried out over the caption buttons.
        let viewport = [0.0, 900.0];
        let (slot_left, width) = (204.0_f32, 200.0);
        assert_eq!(
            grabbed_offset(slot_left, width, viewport, 300.0),
            96.0,
            "free of both edges, the offset is simply the distance"
        );
        assert_eq!(
            grabbed_offset(slot_left, width, viewport, -50.0),
            -slot_left,
            "held past the left edge it stops with its leading edge on it"
        );
        assert_eq!(
            grabbed_offset(slot_left, width, viewport, 5_000.0),
            700.0 - slot_left,
            "and past the right edge with its trailing edge on that one"
        );
        assert_eq!(
            grabbed_offset(0.0, 200.0, [0.0, 120.0], 5_000.0),
            0.0,
            "a viewport narrower than the tab keeps the leading edge, not the trailing one"
        );
    }

    /// **K115 in the rail: a grabbed row is held inside the list's own viewport
    /// and cannot be carried out past its top or its foot.**
    ///
    /// `grabbed_offset` never knew which axis it was on — it clamps a leading
    /// edge against a `[start, end]` pair — so what is new here is what the rail
    /// hands it: the *list's* clip box rather than the window's, and the row's
    /// height rather than a tab's width. The two bounds are asserted to be
    /// strictly inside the window, because that is the difference between a row
    /// stopped by the scroller and a row stopped by the framebuffer — the
    /// heading is above the first and the `+` row is below the second, and a
    /// grabbed row that could reach either would be drawn over furniture that is
    /// not part of the list.
    ///
    /// Red gate: project the run on `x` and `start`/`extent` come back as the
    /// row's left edge and its 203px width, so every clamp below lands on a
    /// different number.
    #[test]
    fn a_grabbed_row_is_held_inside_the_rails_own_viewport() {
        const HEIGHT: f32 = 618.0;
        // Enough rows that the list actually overflows: a rail with room to
        // spare has a viewport its rows never reach, and a clamp nothing tests.
        let trailers = vec![seats::TabTrailer::default(); 40];
        let rail = seats::rail_geometry(
            HEIGHT,
            1.0,
            &trailers,
            0,
            0.0,
            seats::RailState {
                layout: seats::TabLayoutMode::Vertical,
                mode: seats::RailMode::Expanded,
                collapsed: false,
                open: 1.0,
                text_opacity: 1.0,
                fold: None,
            },
        )
        .expect("an expanded rail is on screen");
        assert!(
            rail.max_scroll > 0.0,
            "the list overflows, so it has a foot"
        );
        let run = seats::rail_run(&rail);
        let [top, foot] = run.viewport;
        assert!(
            top > 0.0 && foot < HEIGHT,
            "the clip is the list's own box, not the window's: {:?}",
            run.viewport
        );
        // A row partway down the list rather than the first: the head's own top
        // edge already sits on the viewport's, so clamping it up is a move that
        // could be got right by doing nothing.
        const ROW: usize = 5;
        let start = run.start(ROW).expect("a row partway down the list");
        let height = run.extent(ROW).expect("and its height");
        // Everything is asserted through the row's *drawn* box, which is what
        // `RailTabGeometry::shifted` will move: the offset is a number nobody
        // looks at, and the promise is about where the row you can see ends up.
        let drawn = |offset: f32| {
            let row = rail.tabs[ROW].shifted(offset);
            [row.body[1], row.body[3]]
        };
        assert_eq!(
            grabbed_offset(start, height, run.viewport, start + 90.0),
            90.0,
            "free of both ends, the offset is simply the distance travelled"
        );
        assert_eq!(
            drawn(grabbed_offset(start, height, run.viewport, -5_000.0)),
            [top, top + height],
            "carried up past the head it stops with its top edge on the list's"
        );
        assert_eq!(
            drawn(grabbed_offset(start, height, run.viewport, 5_000.0)),
            [foot - height, foot],
            "and carried down past the foot with its bottom edge on that one"
        );
    }

    #[test]
    fn a_flip_runs_the_displacement_down_to_nothing_on_the_grab_curve() {
        // K117/K118. One motion, 160ms, cubic-bezier(.2, 0, 0, 1).
        let now = Instant::now();
        let mut flip = FlipTween::default();
        assert_eq!(flip.sample(now, Motion::Full), (0.0, false));
        flip.displace(-96.0, now, Motion::Full);
        let (start, moving) = flip.sample(now, Motion::Full);
        assert!((start + 96.0).abs() < 1e-3, "it starts where the tab was");
        assert!(moving);
        let (mid, moving) = flip.sample(now + Duration::from_millis(80), Motion::Full);
        assert!(moving);
        assert!(
            mid > -96.0 && mid < 0.0,
            "and travels the whole way in between"
        );
        assert!(
            mid.abs() < 48.0,
            "the curve leaves fast: half the time is well past half the distance"
        );
        assert_eq!(
            TAB_FLIP,
            Duration::from_millis(160),
            "`transform .16s` (mock-up 6570)"
        );
        assert!(
            flip.sample(now + Duration::from_millis(159), Motion::Full)
                .1,
            "still moving one millisecond short of the end"
        );
        assert_eq!(
            flip.sample(now + Duration::from_millis(160), Motion::Full),
            (0.0, false),
            "at 160ms the tab is simply in its slot"
        );
    }

    #[test]
    fn a_tab_displaced_again_mid_slide_starts_from_where_it_actually_is() {
        // The mock-up measures `getBoundingClientRect`, which includes the live
        // transform (6579-6583): a second swap inside the first slide's 160ms
        // must not snap the tab back to a slot it never reached.
        let now = Instant::now();
        let mut flip = FlipTween::default();
        flip.displace(-96.0, now, Motion::Full);
        let at = now + Duration::from_millis(80);
        let (mid, _) = flip.sample(at, Motion::Full);
        flip.displace(-204.0, at, Motion::Full);
        let (restarted, _) = flip.sample(at, Motion::Full);
        assert!(
            (restarted - (mid - 204.0)).abs() < 1e-3,
            "the new slide starts at the old one's live position plus the new delta"
        );
    }

    #[test]
    fn reduced_motion_puts_a_displaced_tab_straight_into_its_slot() {
        // **Ruling.** The mock-up writes these transitions from JavaScript, where
        // no `prefers-reduced-motion` block can reach them, so its silence here
        // is its medium rather than a decision. A transform travelling across the
        // screen is precisely what the preference is about — unlike the progress
        // ring's sweep, which carries a reading and is deliberately left running.
        let now = Instant::now();
        let mut flip = FlipTween::default();
        flip.displace(-96.0, now, Motion::Reduced);
        assert_eq!(flip.sample(now, Motion::Reduced), (0.0, false));
    }

    #[test]
    fn the_landing_wash_runs_out_over_its_own_two_hundred_milliseconds() {
        // K121. Only the `from` is a design value, so only how much of it is left
        // is a state.
        let now = Instant::now();
        let mut landing = LandTween::default();
        assert_eq!(landing.sample(now, Motion::Full), (0.0, false));
        landing.start(now, Motion::Full);
        assert_eq!(landing.sample(now, Motion::Full), (1.0, true));
        let mut last = 1.0;
        for step in 1..20 {
            let (left, moving) =
                landing.sample(now + Duration::from_millis(step * 10), Motion::Full);
            assert!(left <= last, "the wash only ever fades");
            assert!(moving);
            last = left;
        }
        assert_eq!(
            TAB_LAND,
            Duration::from_millis(200),
            "`animation: tab-land .2s` (mock-up 967)"
        );
        assert!(
            landing
                .sample(now + Duration::from_millis(199), Motion::Full)
                .1
        );
        assert_eq!(
            landing.sample(now + Duration::from_millis(200), Motion::Full),
            (0.0, false)
        );
    }

    /// PIN — U8. A pane's FLIP starts on the box it left and ends on the box the
    /// solver gave it, and it travels the whole way in between.
    ///
    /// The two ends are the assertions that make it a FLIP rather than a
    /// decoration: if `e = 0` does not reproduce the *before* rect exactly then
    /// the first frame of the animation is a jump, which is the one thing the
    /// technique exists to remove; and if `e = 1` is not the solver's own answer
    /// then the pane has been left somewhere the layout does not think it is.
    #[test]
    fn a_pane_flip_starts_on_the_rect_it_left_and_lands_on_the_one_it_was_given() {
        let now = Instant::now();
        let before = [100.0, 50.0, 300.0, 250.0];
        let after = [200.0, 150.0, 600.0, 550.0];
        let flip = PaneFlip::displace(before, after, now, Motion::Full)
            .expect("a pane that halved its corner and doubled its size is displaced");

        let (start, moving) = flip.sample(now, Motion::Full);
        assert!(moving);
        let opened = start.applied_to(after);
        for channel in 0..4 {
            assert!(
                (opened[channel] - before[channel]).abs() < 1e-3,
                "the first frame is the box the pane left, not a jump: {opened:?} vs {before:?}"
            );
        }

        // Monotone toward the destination, in the corner and in the extent.
        let mut last = opened;
        for step in 1..=20 {
            let at = now + Duration::from_millis(step * 10);
            let (transform, _) = flip.sample(at, Motion::Full);
            let box_now = transform.applied_to(after);
            assert!(
                box_now[0] >= last[0] - 1e-3 && box_now[1] >= last[1] - 1e-3,
                "the corner only ever travels toward its destination: {box_now:?} after {last:?}"
            );
            assert!(
                box_now[2] - box_now[0] >= last[2] - last[0] - 1e-3,
                "and the pane only ever widens toward its destination"
            );
            last = box_now;
        }

        let (midway, _) = flip.sample(now + PANE_FLIP / 2, Motion::Full);
        assert!(
            midway.dx.abs() < 0.15 * 100.0 && midway.dy.abs() < 0.15 * 100.0,
            "`cubic-bezier(.2, 0, 0, 1)` leaves immediately: half the time is \
             more than 85% of the distance, which `ease` next door is not \
             ({midway:?})"
        );

        assert!(
            flip.sample(now + PANE_FLIP - Duration::from_millis(1), Motion::Full)
                .1,
            "still moving one millisecond short of the end"
        );
        let (landed, moving) = flip.sample(now + PANE_FLIP, Motion::Full);
        assert!(!moving);
        assert_eq!(
            landed,
            PaneTransform::IDENTITY,
            "at 200ms the pane is simply where the solver put it"
        );
        assert_eq!(landed.applied_to(after), after);
    }

    /// PIN — the two spans the mock-up writes down for a pane, against the
    /// numbers next door that they get quietly rounded into.
    #[test]
    fn a_pane_flips_over_two_hundred_milliseconds_and_arrives_over_a_hundred_and_eighty() {
        assert_eq!(
            PANE_FLIP,
            Duration::from_millis(200),
            "`PANE_EASE = \"transform .2s cubic-bezier(.2, 0, 0, 1)\"` (mock-up 6555)"
        );
        assert_eq!(
            PANE_FADE_IN,
            Duration::from_millis(180),
            "`el.style.transition = \"opacity .18s ease\"` (mock-up 6572)"
        );
    }

    /// PIN — the pane FLIP and the tab FLIP share a curve and not a duration.
    ///
    /// Two ways this gets "simplified", and they pull opposite ways. Declare a
    /// second `[0.2, 0.0, 0.0, 1.0]` beside [`GRAB_EASE`] and the two drift the
    /// day somebody tunes one of them. Fold the durations together and either
    /// the strip goes sluggish or the split goes abrupt, depending on which
    /// number survived — the mock-up writes `.2s` at 6555 and `.16s` at 6570 and
    /// means both.
    #[test]
    fn the_pane_flip_and_the_tab_flip_share_a_curve_but_not_a_duration() {
        let now = Instant::now();
        let pane = PaneFlip::displace(
            [100.0, 0.0, 200.0, 100.0],
            [0.0, 0.0, 100.0, 100.0],
            now,
            Motion::Full,
        )
        .expect("a hundred physical pixels is a displacement");
        let mut tab = FlipTween::default();
        tab.displace(100.0, now, Motion::Full);

        // Same curve means the same fraction of the journey is left at the same
        // fraction of the span — whatever the spans happen to be.
        for tenth in 1..10 {
            let pane_left = pane.sample(now + PANE_FLIP * tenth / 10, Motion::Full).0.dx / 100.0;
            let tab_left = tab.sample(now + TAB_FLIP * tenth / 10, Motion::Full).0 / 100.0;
            assert!(
                (pane_left - tab_left).abs() < 1e-3,
                "at {tenth}/10 of its own span the pane has {pane_left} left and the \
                 tab {tab_left} — they are not running the same curve"
            );
        }
        assert_ne!(
            PANE_FLIP, TAB_FLIP,
            "a pane is half the window and a tab is a chip in a row; one number \
             cannot be both"
        );
    }

    /// PIN — P178. A pane that barely moved gets no animation at all, and each
    /// of the four channels alone is enough to earn one.
    ///
    /// `if (Math.abs(dx) < .5 && Math.abs(dy) < .5 && Math.abs(sx - 1) < .005 &&
    /// Math.abs(sy - 1) < .005) return;` (mock-up 6580). Four terms, so four
    /// assertions: delete any one of them from the condition and exactly one of
    /// these goes red, which is the only way a conjunction can be pinned.
    #[test]
    fn a_pane_that_barely_moved_gets_no_tween_and_each_channel_alone_earns_one() {
        let now = Instant::now();
        let seat = [0.0, 0.0, 128.0, 128.0];

        assert!(
            PaneFlip::displace(seat, seat, now, Motion::Full).is_none(),
            "a pane the solver did not move is not animated at all"
        );
        assert!(
            PaneFlip::displace([0.49, 0.49, 128.49, 128.49], seat, now, Motion::Full).is_none(),
            "and neither is one that moved less than half a physical pixel"
        );
        assert!(
            PaneFlip::displace([0.0, 0.0, 128.5, 128.5], seat, now, Motion::Full).is_none(),
            "nor one whose extent changed by less than half a percent \
             (128.5/128 = 1.0039)"
        );

        assert!(
            PaneFlip::displace([0.5, 0.0, 128.5, 128.0], seat, now, Motion::Full).is_some(),
            "half a physical pixel of `dx` alone earns the animation — the \
             solver snaps seat boundaries to whole pixels, so this is the \
             smallest move there is"
        );
        assert!(
            PaneFlip::displace([0.0, 0.5, 128.0, 128.5], seat, now, Motion::Full).is_some(),
            "half a physical pixel of `dy` alone earns it"
        );
        assert!(
            PaneFlip::displace([0.0, 0.0, 129.0, 128.0], seat, now, Motion::Full).is_some(),
            "`sx` alone earns it: 129/128 = 1.0078, past the half-percent, with \
             the corner untouched"
        );
        assert!(
            PaneFlip::displace([0.0, 0.0, 128.0, 129.0], seat, now, Motion::Full).is_some(),
            "`sy` alone earns it, likewise"
        );
    }

    /// PIN — reduced motion puts a displaced pane where it belongs on the first
    /// sample, and an arriving one at full opacity.
    ///
    /// **Ruling**, and the same one [`reduced_motion_puts_a_displaced_tab_straight_into_its_slot`]
    /// records: the mock-up writes these transitions from JavaScript, where no
    /// `prefers-reduced-motion` block can reach them, so its silence is its
    /// medium rather than a decision. Half the window changing shape is exactly
    /// what the preference is about.
    #[test]
    fn reduced_motion_lands_a_pane_at_once_and_gives_an_arriving_one_no_fade() {
        let now = Instant::now();
        let after = [200.0, 150.0, 600.0, 550.0];
        let flip = PaneFlip::displace([100.0, 50.0, 300.0, 250.0], after, now, Motion::Reduced)
            .expect("the threshold is about geometry, not about preference");
        assert_eq!(
            flip.sample(now, Motion::Reduced),
            (PaneTransform::IDENTITY, false),
            "there is no first frame to travel from: the pane is where it belongs"
        );

        let mut motion = PaneMotion::default();
        let before = [(SeatId(1), [0.0, 0.0, 100.0, 100.0])];
        let arriving = [
            (SeatId(1), [0.0, 0.0, 50.0, 100.0]),
            (SeatId(2), [50.0, 0.0, 100.0, 100.0]),
        ];
        motion.begin(&before, &arriving, now, Motion::Reduced);
        assert_eq!(
            motion.opacity_of(SeatId(2), now, Motion::Reduced),
            1.0,
            "the new pane is simply there"
        );
        assert!(!motion.is_animating(now, Motion::Reduced));

        let mut full = PaneMotion::default();
        full.begin(&before, &arriving, now, Motion::Full);
        assert_eq!(
            full.opacity_of(SeatId(2), now, Motion::Full),
            0.0,
            "under Full it starts from nothing"
        );
        let opening = full.opacity_of(SeatId(2), now + Duration::from_millis(90), Motion::Full);
        assert!(opening > 0.0 && opening < 1.0, "mid-fade: {opening}");
        assert_eq!(
            full.opacity_of(SeatId(2), now + PANE_FADE_IN, Motion::Full),
            1.0,
            "and it is done at its own span, not the FLIP's"
        );
        assert_eq!(
            full.transform_of(SeatId(2), now, Motion::Full),
            PaneTransform::IDENTITY,
            "a pane with no history fades *instead of* sliding (mock-up 6573 returns)"
        );
    }

    /// PIN — a pane split again mid-flight starts from where it actually is.
    ///
    /// `snapshotPanes` measures `getBoundingClientRect` (mock-up 6557-6562),
    /// which includes the transform still running. Restart from the solver's
    /// stale rect instead and the pane teleports to a box it never reached
    /// before beginning its second journey — which is [`FlipTween::displace`]'s
    /// argument, one dimension up.
    #[test]
    fn a_pane_displaced_again_mid_flight_starts_from_where_it_actually_is() {
        let now = Instant::now();
        let first = [0.0, 0.0, 100.0, 100.0];
        let mut motion = PaneMotion::default();
        motion.begin(
            &[(SeatId(1), [200.0, 0.0, 300.0, 100.0])],
            &[(SeatId(1), first)],
            now,
            Motion::Full,
        );

        let at = now + Duration::from_millis(80);
        let live = motion.snapshot(&[(SeatId(1), first)], at, Motion::Full);
        let [live_left, ..] = live[0].1;
        assert!(
            live_left > 1.0,
            "80ms into a 200ms flight the pane has not arrived ({live_left})"
        );

        let second = [0.0, 300.0, 100.0, 400.0];
        motion.begin(&live, &[(SeatId(1), second)], at, Motion::Full);
        let opened = motion
            .transform_of(SeatId(1), at, Motion::Full)
            .applied_to(second);
        for channel in 0..4 {
            assert!(
                (opened[channel] - live[0].1[channel]).abs() < 1e-3,
                "the second flight opens on the live box {:?}, not on the stale \
                 layout rect {first:?} — it got {opened:?}",
                live[0].1
            );
        }
        assert!(
            (opened[0] - first[0]).abs() > 1.0,
            "and the stale rect really is a different box, so this test can fail"
        );
    }

    /// PIN — a seat that left the layout leaves nothing behind.
    ///
    /// The mock-up gives a departing pane no exit animation: `renderWithPaneFlip`
    /// walks the panes that exist *after* the render (6564), and the closed one
    /// is already out of the DOM. Only the survivors FLIP.
    #[test]
    fn a_seat_that_left_the_layout_leaves_no_tween_behind() {
        let now = Instant::now();
        let split = [
            (SeatId(1), [0.0, 0.0, 50.0, 100.0]),
            (SeatId(2), [50.0, 0.0, 100.0, 100.0]),
        ];
        let whole = [(SeatId(1), [0.0, 0.0, 100.0, 100.0])];
        let mut motion = PaneMotion::default();
        motion.begin(&[], &split, now, Motion::Full);
        assert!(motion.panes.iter().any(|pane| pane.seat == SeatId(2)));

        motion.begin(&split, &whole, now, Motion::Full);
        assert!(
            !motion.panes.iter().any(|pane| pane.seat == SeatId(2)),
            "the departed seat is not carried"
        );
        assert_eq!(
            motion.transform_of(SeatId(2), now, Motion::Full),
            PaneTransform::IDENTITY
        );
        assert_eq!(motion.opacity_of(SeatId(2), now, Motion::Full), 1.0);
        assert!(
            motion.is_animating(now, Motion::Full),
            "the survivor is still expanding into the space"
        );
    }

    /// PIN — the pane's frame debt is paid in drawn boxes, so the flight draws
    /// every step it has and stops the moment it lands.
    ///
    /// The failure this stands against is the one [`tab_owes_frame`] was written
    /// for: "is anything moving?" is the right question for the deadline and the
    /// wrong one for whether to draw, and the two part company on exactly the
    /// frame motion stops. Ask the moving question and the pane is left stranded
    /// one eased step short of the box the solver actually gave it.
    #[test]
    fn a_pane_s_frame_debt_is_paid_in_drawn_boxes() {
        let now = Instant::now();
        let layout = [(SeatId(1), [0.0, 0.0, 500.0, 500.0])];
        let mut motion = PaneMotion::default();
        motion.begin(
            &[(SeatId(1), [400.0, 0.0, 900.0, 500.0])],
            &layout,
            now,
            Motion::Full,
        );

        assert!(
            motion.settle_frame_debt(&layout, now, Motion::Full),
            "nothing of this layout has been drawn yet"
        );
        assert!(
            !motion.settle_frame_debt(&layout, now, Motion::Full),
            "and asking twice at the same instant does not owe a second present"
        );
        assert!(
            motion.settle_frame_debt(&layout, now + Duration::from_millis(100), Motion::Full),
            "mid-flight the pane owes a frame"
        );

        let end = now + PANE_FLIP;
        assert!(
            !motion.is_animating(end, Motion::Full),
            "nothing is moving on the frame the flight ends"
        );
        assert!(
            motion.settle_frame_debt(&layout, end, Motion::Full),
            "and it still owes that frame — it is the one that puts the pane in \
             the box the solver gave it"
        );
        assert!(
            !motion.settle_frame_debt(&layout, end + STRIP_ANIMATION_FRAME, Motion::Full),
            "landed and drawn, it owes nothing"
        );

        // Finer than a whole physical pixel is finer than anything is drawn at,
        // so the long tail of `.2,0,0,1` must not owe a present per wake-up.
        let mut settled = PaneMotion::default();
        settled.begin(
            &[(SeatId(1), [400.0, 0.0, 900.0, 500.0])],
            &layout,
            now,
            Motion::Full,
        );
        let mut presents = 0_u32;
        let mut wakes = 0_u32;
        let mut at = now;
        loop {
            let moving = settled.is_animating(at, Motion::Full);
            if settled.settle_frame_debt(&layout, at, Motion::Full) {
                presents += 1;
            }
            wakes += 1;
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }
        assert!(
            wakes > presents,
            "every wake-up presented a frame ({presents} of {wakes}) — the debt is \
             measured on something finer than a pane is drawn at"
        );
        assert!(
            presents >= 5,
            "only {presents} frames of the flight were drawn — that is a jump \
             wearing an animation's clothes"
        );
    }

    /// PIN — the deadline is `None` when nothing is moving and `Some` while
    /// something is, on the same terms as [`Runtime::strip_animation_deadline`].
    ///
    /// `None` is the important half: it is what lets the loop fall back to
    /// `ControlFlow::Wait` and the process go genuinely idle once the split has
    /// settled.
    #[test]
    fn the_pane_deadline_asks_for_wake_ups_only_while_something_is_moving() {
        let now = Instant::now();
        let mut motion = PaneMotion::default();
        assert_eq!(
            motion.deadline(now, Motion::Full),
            None,
            "a tab whose panes are all at rest asks for no wake-ups at all"
        );

        let before = [(SeatId(1), [0.0, 0.0, 100.0, 100.0])];
        let after = [
            (SeatId(1), [0.0, 0.0, 50.0, 100.0]),
            (SeatId(2), [50.0, 0.0, 100.0, 100.0]),
        ];
        motion.begin(&before, &after, now, Motion::Full);
        assert_eq!(
            motion.deadline(now, Motion::Full),
            Some(now + STRIP_ANIMATION_FRAME)
        );
        assert_eq!(
            motion.deadline(now + PANE_FADE_IN, Motion::Full),
            Some(now + PANE_FADE_IN + STRIP_ANIMATION_FRAME),
            "the fade is done but the FLIP beside it is not"
        );
        assert_eq!(
            motion.deadline(now + PANE_FLIP, Motion::Full),
            None,
            "and once the longest of them lands, the loop may sleep"
        );

        motion.retire(now + PANE_FLIP, Motion::Full);
        assert!(motion.panes.iter().all(|pane| pane.tween.is_none()));

        let mut reduced = PaneMotion::default();
        reduced.begin(&before, &after, now, Motion::Reduced);
        assert_eq!(
            reduced.deadline(now, Motion::Reduced),
            None,
            "reduced motion has no frames to ask for"
        );
    }

    /// A tab of two terminal panes and the geometry that made them, at 1x in a
    /// 1600x900 window.
    ///
    /// `leading` decides which side the *arriving* pane takes, and the tests
    /// below use `true` deliberately: with the new pane on the left, the
    /// survivor's corner genuinely travels, and a FLIP that only ever changed an
    /// extent would leave two of the three clauses of the counter-scale untested.
    fn split_window(leading: bool) -> (seats::Seats, SeatLayout, SeatLayout, SeatId, SeatId) {
        let metrics = seats::seat_metrics(1_000);
        let viewport = seats::logical_viewport(1600, 900, seats::scale_ppm(1_000), 0);
        let mut seats = seats::Seats::lone_terminal();
        let survivor = seats.terminal();
        let before = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("a lone leaf solves");
        let arriving = seats
            .split_terminal(&metrics, survivor, bt_layout::Axis::Row, leading)
            .expect("a 1600x900 window divides");
        let after = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("the split solves");
        (seats, before, after, survivor, arriving)
    }

    /// Every pane's box in physical pixels, in the solver's own order — the
    /// shape [`Runtime::pane_rects`] hands [`PaneMotion`].
    fn pane_rects_of(layout: &SeatLayout) -> Vec<(SeatId, [f32; 4])> {
        layout
            .rects
            .iter()
            .filter_map(|placement| {
                let device = placement.device_rect?;
                Some((
                    placement.id,
                    [
                        device.left as f32,
                        device.top as f32,
                        device.right as f32,
                        device.bottom as f32,
                    ],
                ))
            })
            .collect()
    }

    fn pane_box_of(layout: &SeatLayout, seat: SeatId) -> [f32; 4] {
        pane_rects_of(layout)
            .into_iter()
            .find(|(id, _)| *id == seat)
            .expect("the seat was placed")
            .1
    }

    /// PIN — U8, R3. The counter-scale, stated as the three things it composes
    /// to, in one frame.
    ///
    /// The mock-up writes the animation as `scale(s)` on the pane and
    /// `scale(1/s)` on an inner wrapper (6584-6586), and it needs both because
    /// in CSS a transform is the only way to move a box that is already laid
    /// out: the outer scale is the price of the movement and the inner one buys
    /// back the text it stretched. Multiply the pair out and three separate
    /// facts fall out, which are the three clauses below —
    ///
    /// 1. the pane's **box** on the first frame is the box it left;
    /// 2. the pane's **content origin** on that frame is the corner it left;
    /// 3. the pane's **content extent** is already the one the solver just gave
    ///    it, on that same first frame.
    ///
    /// The third is the one that fails a literal transcription of the CSS. Scale
    /// this crate's viewport by `s` and clauses 1 and 2 still pass — the box and
    /// the corner are right — while the grid inside it is drawn at the *old*
    /// width and has to reflow toward the new one over 200ms, which is a resize
    /// per frame handed to ConPTY (R2) and glyphs that visibly squeeze.
    #[test]
    fn the_first_frame_of_a_split_draws_the_old_box_around_contents_already_at_their_new_size() {
        let now = Instant::now();
        let (seats, before, after, survivor, _) = split_window(true);
        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&before),
            &pane_rects_of(&after),
            now,
            Motion::Full,
        );

        let was = pane_box_of(&before, survivor);
        let is = pane_box_of(&after, survivor);
        assert!(
            (was[0] - is[0]).abs() > 1.0 && (was[2] - was[0]) > (is[2] - is[0]),
            "the survivor has to both move and narrow, or this pin proves \
             nothing: {was:?} -> {is:?}"
        );
        let transform = motion.transform_of(survivor, now, Motion::Full);

        // Clause 1 — the box.
        let box_now = transform.applied_to(is);
        for channel in 0..4 {
            assert!(
                (box_now[channel] - was[channel]).abs() < 1e-3,
                "the first frame is drawn through the box the pane left: \
                 {box_now:?} against {was:?}"
            );
        }

        let body = seats::pane_body_viewport(&seats, &after, survivor, 1.0)
            .expect("the survivor has a body");
        let (viewport, _) = animated_pane_viewports(body, is, transform);

        // Clause 2 — the content's corner.
        assert_eq!(
            viewport.x as f32, was[0],
            "the contents are drawn from the corner the pane left, not from the \
             one the solver just gave it ({} against {})",
            viewport.x, is[0]
        );

        // Clause 3 — the content's extent, and the one a scaled viewport fails.
        assert_eq!(
            (viewport.width, viewport.height),
            (body.width, body.height),
            "the contents are already at the size the solver gave them on the \
             very first frame — nothing is ever scaled"
        );
        assert!(
            f32::from(u16::try_from(viewport.width).unwrap_or(u16::MAX)) < was[2] - was[0],
            "and that size really is different from the box's, so clause 3 is \
             not restating clause 1"
        );
    }

    /// PIN — U8, R3. A pane growing into a closed sibling's space is *clipped*
    /// into it, never stretched into it.
    ///
    /// The complement of the split above and the half where the FLIP is actually
    /// visible: the survivor's contents are laid out at their final, larger size
    /// from the corner they still occupy, and the animating box opens over them
    /// like a curtain. On the first frame the box is strictly smaller than the
    /// contents — that is the clipping — and by the last both are the rectangle
    /// the solver gave.
    ///
    /// The viewport legitimately hangs off the right of the surface while this
    /// runs (`x + width` past the window), which is why only the scissor of the
    /// pair is clamped and why it is clamped where the device validates it.
    #[test]
    fn a_pane_growing_out_of_a_closed_sibling_is_clipped_into_the_space_not_stretched_into_it() {
        let now = Instant::now();
        let metrics = seats::seat_metrics(1_000);
        let viewport = seats::logical_viewport(1600, 900, seats::scale_ppm(1_000), 0);
        let (mut seats, _, split, survivor, arriving) = split_window(true);
        let before = split;
        assert!(seats.close_seat(&metrics, arriving), "the left pane closes");
        let after = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("the survivor solves");

        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&before),
            &pane_rects_of(&after),
            now,
            Motion::Full,
        );
        let pane = pane_box_of(&after, survivor);
        let body = seats::pane_body_viewport(&seats, &after, survivor, 1.0)
            .expect("the survivor has a body");

        let first =
            animated_pane_viewports(body, pane, motion.transform_of(survivor, now, Motion::Full));
        let (content, clip) = first;
        assert!(
            clip.width < content.width,
            "the box the survivor is drawn through is still the narrow one it \
             had ({} against {} of content)",
            clip.width,
            content.width
        );
        assert_eq!(
            content.width, body.width,
            "while the contents are at their final width from the first frame"
        );
        assert!(
            content.x + content.width > 1600,
            "and that puts the viewport off the right of a 1600px surface, which \
             is legal for a viewport and is why the scissor is the clamped one"
        );

        let (landed_content, landed_clip) = animated_pane_viewports(
            body,
            pane,
            motion.transform_of(survivor, now + PANE_FLIP, Motion::Full),
        );
        assert_eq!(
            landed_content, body,
            "the flight ends on the solver's answer"
        );
        assert_eq!(
            landed_clip, body,
            "and the box it is drawn through has opened all the way to it"
        );
    }

    /// PIN — U8, R5. Only a structural tree change animates.
    ///
    /// Three assertions because there are three cases and they are not variants
    /// of one: a divider drag steers a ratio, a focus change feeds W2's
    /// concession ladder, and a split adds a leaf. All three re-solve, and the
    /// first two move rectangles — which is exactly why "the layout re-solved"
    /// cannot be the gate, and why the middle assertion carries the search that
    /// proves a focus change really does move them rather than asserting it.
    ///
    /// A gate on `Edit`-ness rather than on displacement is also what makes
    /// `CenterSwap` come out right: it is counted as structural and then moves
    /// nothing, so P178 skips every pane and the swap is not animated — reached
    /// by the rule instead of by an exception carved out of it.
    #[test]
    fn a_divider_drag_and_a_focus_change_start_no_pane_tween_and_a_split_starts_one() {
        let metrics = seats::seat_metrics(1_000);
        let viewport = seats::logical_viewport(1600, 900, seats::scale_ppm(1_000), 0);
        let (mut seats, _, split, survivor, arriving) = split_window(true);

        // A split: the shape changed, so the gate fires.
        assert_eq!(
            seats.structure_revision(),
            1,
            "the split is the one edit here that added a leaf"
        );

        // A divider drag: rectangles move, the shape does not.
        let at_rest = seats.structure_revision();
        let slot = *seats
            .split_slots(&split)
            .first()
            .expect("the split has a divider");
        let usable = slot.slot.extent(slot.dir) - bt_layout::DIVIDER;
        assert_eq!(
            seats.drag_divider(
                &metrics,
                slot.id,
                bt_layout::Ratio::clamped_from_ppm(300_000),
                usable
            ),
            Ok(true),
            "the drag has to actually write a ratio, or this assertion is about \
             a refusal instead of about the gate"
        );
        let dragged = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("the drag solves");
        assert_ne!(
            pane_box_of(&dragged, survivor),
            pane_box_of(&split, survivor),
            "the drag moved the pane's rectangle"
        );
        assert_eq!(
            seats.structure_revision(),
            at_rest,
            "and moved no leaf, so nothing animates: a 200ms tail on a gesture \
             the pointer is already driving frame by frame"
        );

        // A focus change: rectangles move through the concession ladder, the
        // shape does not. The width is searched for rather than asserted,
        // because "focus moves rectangles" is a fact about W2 and about this
        // build's minimum sizes, not a number this test may invent.
        let mut narrow = seats::Seats::lone_terminal();
        let first = narrow.terminal();
        let second = narrow
            .split_terminal(&metrics, first, bt_layout::Axis::Row, false)
            .expect("a wide window divides");
        let ladder = (200..900).step_by(4).find_map(|width| {
            let viewport = seats::logical_viewport(width, 600, seats::scale_ppm(1_000), 0);
            narrow.set_focus(first);
            let with_first = narrow.solve(viewport, &metrics, SizePolicy::Lawful).ok()?;
            narrow.set_focus(second);
            let with_second = narrow.solve(viewport, &metrics, SizePolicy::Lawful).ok()?;
            (pane_rects_of(&with_first) != pane_rects_of(&with_second)).then_some(width)
        });
        let ladder = ladder.expect(
            "no window width in 200..900 lets focus change the solve — the \
             concession ladder's input has moved and this assertion is no longer \
             about what it says it is",
        );
        let revision = narrow.structure_revision();
        let ladder_viewport = seats::logical_viewport(ladder, 600, seats::scale_ppm(1_000), 0);
        narrow.set_focus(first);
        let with_first = narrow
            .solve(ladder_viewport, &metrics, SizePolicy::Lawful)
            .expect("solves");
        assert!(narrow.set_focus(second), "focus moves");
        let with_second = narrow
            .solve(ladder_viewport, &metrics, SizePolicy::Lawful)
            .expect("solves");
        assert_ne!(
            pane_rects_of(&with_first),
            pane_rects_of(&with_second),
            "at {ladder}px the ladder answers differently for each focus"
        );
        assert_eq!(
            narrow.structure_revision(),
            revision,
            "and clicking into a pane must not put a fifth of a second of glide \
             between the click and the layout settling"
        );

        // The tear-out's own commit is `close_seat`, which is structural.
        let before_close = narrow.structure_revision();
        assert!(narrow.close_seat(&metrics, second));
        assert_eq!(narrow.structure_revision(), before_close + 1);
        let _ = arriving;
    }

    /// PIN — U8, R2. A flight in progress issues **zero** ConPTY resizes.
    ///
    /// This is the pin that keeps a resize storm impossible, and it is a pin
    /// about an extent rather than about a call count: the grid is a function of
    /// the seat's width and height, `coalesce_pty_resize_on_grid_change` is the
    /// single gate every solve funnels through, and it schedules nothing when
    /// the grid it is handed equals the one in force. So the whole of R2 is
    /// "the animation never changes an extent", and that is what is asserted at
    /// every frame of the flight below.
    ///
    /// B14's counter-scale is why it can be true at all: the contents are laid
    /// out at their destination size on the animation's *first* frame, so there
    /// is nothing left to resize on the last. Transcribe the CSS literally —
    /// scale the viewport — and the extent changes on every one of the twelve
    /// frames here, each one a grid change, each one a scheduled resize behind
    /// a 200ms quiet window that the next frame immediately re-arms.
    #[test]
    fn an_in_flight_pane_animation_asks_conpty_for_no_resize_at_all() {
        let now = Instant::now();
        let metrics = seats::seat_metrics(1_000);
        let viewport = seats::logical_viewport(1600, 900, seats::scale_ppm(1_000), 0);
        let (mut seats, _, split, survivor, arriving) = split_window(true);
        assert!(seats.close_seat(&metrics, arriving));
        let after = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("the survivor solves");
        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&split),
            &pane_rects_of(&after),
            now,
            Motion::Full,
        );
        let pane = pane_box_of(&after, survivor);
        let body = seats::pane_body_viewport(&seats, &after, survivor, 1.0)
            .expect("the survivor has a body");

        // The one resize the *commit* is entitled to, on the final rectangle,
        // before a single frame of the flight is drawn.
        let rows_for = |height: u32| ((height.saturating_sub(16)) / 20).max(1) as u16;
        let settled = grid_of(100, rows_for(body.height));
        let mut pending = None;
        let mut current = grid_of(100, rows_for(1));
        assert!(
            coalesce_pty_resize_on_grid_change(
                &mut pending,
                settled,
                current,
                PhysicalSize::new(body.width, body.height),
                now,
            ),
            "the commit itself schedules one resize, on the box the pane landed in"
        );
        current = take_due_pty_resize(&mut pending, now + WINDOW_RESIZE_QUIET)
            .expect("and it is delivered")
            .grid;
        assert_eq!(current, settled);

        let mut scheduled = 0_u32;
        let mut at = now;
        loop {
            let moving = motion.is_animating(at, Motion::Full);
            let (content, _) = animated_pane_viewports(
                body,
                pane,
                motion.transform_of(survivor, at, Motion::Full),
            );
            assert_eq!(
                (content.width, content.height),
                (body.width, body.height),
                "the flight changed an extent, which is a grid change wearing an \
                 animation's clothes"
            );
            if coalesce_pty_resize_on_grid_change(
                &mut pending,
                grid_of(100, rows_for(content.height)),
                current,
                PhysicalSize::new(content.width, content.height),
                at,
            ) {
                scheduled += 1;
            }
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }
        assert_eq!(
            scheduled, 0,
            "an in-flight animation scheduled {scheduled} ConPTY resizes; the \
             contract is exactly one per structural edit, at the commit, on the \
             final rectangle"
        );
        assert!(
            take_due_pty_resize(&mut pending, at + WINDOW_RESIZE_QUIET).is_none(),
            "and nothing is left queued behind the quiet window either"
        );
    }

    /// PIN — U8. Reduced motion puts every pane on its final rectangle at once,
    /// owes no frame after the first and asks for no wake-ups.
    ///
    /// Verified rather than assumed: "there are no tweens under Reduced" is a
    /// property of [`PaneFlip::displace`] storing no `started`, and the three
    /// things that follow from it — identity transform, settled debt, no
    /// deadline — are each a separate consumer that could have read the clock
    /// for itself.
    #[test]
    fn reduced_motion_lands_every_pane_at_once_and_asks_for_no_frames() {
        let now = Instant::now();
        let (seats, before, after, survivor, arriving) = split_window(true);
        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&before),
            &pane_rects_of(&after),
            now,
            Motion::Reduced,
        );

        for seat in [survivor, arriving] {
            assert_eq!(
                motion.transform_of(seat, now, Motion::Reduced),
                PaneTransform::IDENTITY,
                "seat {seat:?} is simply where the solver put it"
            );
        }
        let pane = pane_box_of(&after, survivor);
        let body = seats::pane_body_viewport(&seats, &after, survivor, 1.0)
            .expect("the survivor has a body");
        let (content, clip) = animated_pane_viewports(
            body,
            pane,
            motion.transform_of(survivor, now, Motion::Reduced),
        );
        assert_eq!((content, clip), (body, body));

        assert!(!motion.is_animating(now, Motion::Reduced));
        assert_eq!(
            motion.deadline(now, Motion::Reduced),
            None,
            "no deadline is asked for, so the loop goes back to `ControlFlow::Wait`"
        );
        assert!(
            motion.settle_frame_debt(&pane_rects_of(&after), now, Motion::Reduced),
            "the layout it landed on has still never been drawn"
        );
        assert!(
            !motion.settle_frame_debt(
                &pane_rects_of(&after),
                now + STRIP_ANIMATION_FRAME,
                Motion::Reduced
            ),
            "and after that one frame it owes nothing at all"
        );
    }

    /// PIN — U8. The flight is drawn on every frame it has, including its last,
    /// and stops asking afterwards.
    ///
    /// The two questions kept apart: [`PaneMotion::deadline`] answers "wake me
    /// again" and [`PaneMotion::settle_frame_debt`] answers "draw this one", and
    /// they part company on exactly the frame the FLIP reaches identity — where
    /// nothing is moving any more and the pane has still not been drawn in the
    /// box the solver gave it. This walks the whole flight at the wake-up
    /// cadence the loop actually uses and checks both ends.
    #[test]
    fn a_pane_flight_requests_a_redraw_on_every_frame_it_has_and_none_after_it_lands() {
        let now = Instant::now();
        let (_, before, after, survivor, _) = split_window(true);
        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&before),
            &pane_rects_of(&after),
            now,
            Motion::Full,
        );

        let mut drawn = 0_u32;
        let mut at = now;
        loop {
            let moving = motion.is_animating(at, Motion::Full);
            let deadline = motion.deadline(at, Motion::Full);
            assert_eq!(
                deadline.is_some(),
                moving,
                "a wake-up is asked for exactly while something is moving"
            );
            if motion.settle_frame_debt(&pane_rects_of(&after), at, Motion::Full) {
                drawn += 1;
            }
            motion.retire(at, Motion::Full);
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }
        assert!(
            drawn >= 5,
            "only {drawn} frames of a 200ms flight were drawn — that is a jump \
             wearing an animation's clothes"
        );
        // The frame after motion stops is walked too, and it is the one this
        // loop exists to protect: a debt gated on "is it moving?" would have
        // returned before it, leaving the pane one eased step short of the box
        // the solver gave it — a permanent misalignment rather than a missed
        // frame of polish. What is asserted is the outcome rather than which
        // frame paid for it, because the curve's long tail legitimately settles
        // on the final *pixels* a wake-up or two before it settles on the final
        // floats, and re-presenting identical pixels is a present nobody asked
        // for.
        assert_eq!(
            motion
                .entry(survivor)
                .and_then(|pane| pane.last_drawn)
                .map(|drawn| drawn.box_px),
            Some(pane_box_of(&after, survivor).map(|edge| edge.round() as i32)),
            "the flight ends with the pane recorded as drawn in the box the \
             solver gave it"
        );
        assert_eq!(
            motion.deadline(at, Motion::Full),
            None,
            "and once it is drawn the window may go genuinely idle"
        );
        assert!(
            !motion.settle_frame_debt(
                &pane_rects_of(&after),
                at + STRIP_ANIMATION_FRAME,
                Motion::Full
            ),
            "landed and drawn, it owes nothing"
        );
        assert!(
            motion.panes.iter().all(|pane| pane.tween.is_none()),
            "and `retire` has dropped the tweens, so no rect from a layout two \
             splits ago is carried beside a seat id that may be reused"
        );
    }

    /// PIN — U8, P177. The arriving pane's veil is `--termbg` at `1 - opacity`,
    /// over the arriving pane's own rectangle and over no other.
    ///
    /// The ruling this stands on is written out at [`pane_fade_veil_layers`]: the
    /// fade is a cover in the ground colour rather than a uniform alpha on the
    /// pane's own draws, because `termbg·(1-a) + pane·a` over a `--termbg` ground
    /// *is* CSS `opacity`, and because glyphon has no per-`TextArea` alpha to
    /// carry the literal thing without rebuilding every glyph buffer per frame.
    ///
    /// Three things are pinned and each fails a different mistake: the colour
    /// (a veil in `--panel` would flash the gap colour over a pane that is not
    /// being resized), the alpha's *direction* (`opacity` instead of
    /// `1 - opacity` fades the pane out and then snaps it in), and the extent
    /// (a veil over the survivor as well would dim half the window on every
    /// split).
    #[test]
    fn an_arriving_pane_is_veiled_in_the_ground_colour_at_one_minus_its_opacity() {
        let now = Instant::now();
        let palette = bt_render::chrome_palette();
        let before = [(SeatId(1), [0.0, 0.0, 100.0, 100.0])];
        let after = [
            (SeatId(1), [0.0, 0.0, 50.0, 100.0]),
            (SeatId(2), [50.0, 0.0, 100.0, 100.0]),
        ];
        let mut motion = PaneMotion::default();
        motion.begin(&before, &after, now, Motion::Full);

        let layers = pane_fade_veil_layers(&motion, &after, now, Motion::Full, palette);
        let [layer] = layers.as_slice() else {
            panic!("one veil layer while one pane is arriving, got {layers:?}");
        };
        let [veil] = layer.quads.as_slice() else {
            panic!(
                "one fill, for the one pane that is arriving — the survivor FLIPs \
                 and the two are alternatives (mock-up 6573): {:?}",
                layer.quads
            );
        };
        assert_eq!(
            veil.color, palette.seat_body,
            "the veil is the ground the pane fades up from — `--termbg`, which is \
             what is under a pane's box"
        );
        assert_ne!(
            palette.seat_body, palette.title_bar,
            "and the two really are different colours, so the assertion above can fail"
        );
        assert_eq!(
            veil.alpha, 1.0,
            "at t=0 the arriving pane is not there at all"
        );
        assert_eq!(
            veil.rect, after[1].1,
            "over the arriving seat's own solved rectangle"
        );
        assert_ne!(
            after[1].1, after[0].1,
            "and that rectangle really is not the survivor's"
        );

        for ms in [30_u64, 90, 150] {
            let at = now + Duration::from_millis(ms);
            let layers = pane_fade_veil_layers(&motion, &after, at, Motion::Full, palette);
            let veil = layers[0].quads[0];
            let want = 1.0 - motion.opacity_of(SeatId(2), at, Motion::Full);
            assert!(
                (veil.alpha - want).abs() < 1e-6,
                "{ms}ms in the veil is {} where the fade says {want}",
                veil.alpha
            );
            assert!(
                veil.alpha > 0.0 && veil.alpha < 1.0,
                "and {ms}ms of a 180ms fade is genuinely mid-way: {}",
                veil.alpha
            );
            assert_eq!(veil.rect, after[1].1);
        }

        assert!(
            pane_fade_veil_layers(&motion, &after, now + PANE_FADE_IN, Motion::Full, palette)
                .is_empty(),
            "at 180ms the pane is simply there, and an empty layer would still cost \
             a pass through three channels to draw nothing"
        );
    }

    /// PIN — U8, P177. A pane that FLIPs wears no veil, and under reduced motion
    /// nothing wears one at all.
    ///
    /// The first half is the mock-up's early `return` (6573) read as a fact about
    /// drawing: FLIP and fade are alternatives, so a survivor that is sliding into
    /// its new box must not also be dimmed on the way. The second is the same
    /// answer [`RevealTween::retarget`] already gives — under `Reduced` the
    /// arriving pane is simply *there* — asserted at the drawing rather than
    /// inferred from the tween, because a veil is a separate consumer that could
    /// have read the clock for itself.
    #[test]
    fn a_flipping_pane_wears_no_veil_and_reduced_motion_hangs_none_at_all() {
        let now = Instant::now();
        let palette = bt_render::chrome_palette();
        let before = [(SeatId(1), [0.0, 0.0, 100.0, 100.0])];
        let after = [
            (SeatId(1), [0.0, 0.0, 50.0, 100.0]),
            (SeatId(2), [50.0, 0.0, 100.0, 100.0]),
        ];

        let mut full = PaneMotion::default();
        full.begin(&before, &after, now, Motion::Full);
        assert!(
            full.is_animating(now, Motion::Full),
            "the survivor is mid-FLIP, or this test proves nothing"
        );
        let mut at = now;
        loop {
            let moving = full.is_animating(at, Motion::Full);
            for layer in pane_fade_veil_layers(&full, &after, at, Motion::Full, palette) {
                for veil in layer.quads {
                    assert_ne!(
                        veil.rect, after[0].1,
                        "the survivor is FLIPping and a FLIP is never also a fade"
                    );
                }
            }
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }

        let mut reduced = PaneMotion::default();
        reduced.begin(&before, &after, now, Motion::Reduced);
        for step in 0..16 {
            let at = now + STRIP_ANIMATION_FRAME * step;
            assert!(
                pane_fade_veil_layers(&reduced, &after, at, Motion::Reduced, palette).is_empty(),
                "reduced motion has no fade to veil, on frame {step}"
            );
        }
    }

    /// PIN — U8, P177. The veil is the bottom-most thing the overlay carries.
    ///
    /// The dock drawing is already documented as the lowest layer in the stack
    /// ([`Runtime::dock_overlay_layers`]), so "under the dock" is "under
    /// everything": the menus, the restore prompt, the settings dialog, the
    /// layout peek, the tip and the drag ghost are all stacked after it by
    /// [`Runtime::refresh_overlay`]. What this fails is the reasonable-looking
    /// mistake of appending the veil to the stack that is already built, which
    /// would put a pane's fade over an open dialog.
    #[test]
    fn the_arriving_panes_veil_is_the_bottom_most_overlay_layer() {
        let veil = marks::OverlayLayer {
            quads: vec![bt_render::OverlayQuad {
                rect: [0.0, 0.0, 10.0, 10.0],
                color: bt_render::chrome_palette().seat_body,
                alpha: 0.5,
            }],
            ..marks::OverlayLayer::default()
        };
        let dock = vec![marks::OverlayLayer {
            quads: vec![bt_render::OverlayQuad {
                rect: [20.0, 20.0, 30.0, 30.0],
                color: bt_render::chrome_palette().title_bar,
                alpha: 1.0,
            }],
            ..marks::OverlayLayer::default()
        }];

        let stacked = ground_overlay_layers(vec![veil.clone()], dock.clone());
        assert_eq!(
            stacked.first(),
            Some(&veil),
            "the veil paints first and is therefore covered by everything after it"
        );
        assert_eq!(&stacked[1..], dock.as_slice(), "and the dock is over it");
        assert_eq!(
            ground_overlay_layers(Vec::new(), dock.clone()),
            dock,
            "with nothing arriving the stack is the one that was there before P177"
        );
    }

    /// PIN — U8, P177. A pane that only fades owes a frame on every frame of its
    /// 180ms and none after.
    ///
    /// The fade has no geometry at all — [`PaneTween::FadeIn`] reports the
    /// identity transform — so the only thing that changes across it is the
    /// opacity, and this is what pins that [`PaneDrawn`] carries it. Drop the
    /// opacity from that record and the box never moves, the debt is never owed,
    /// and the arriving pane is drawn once at nothing and never again: a pane that
    /// simply does not appear.
    #[test]
    fn an_arriving_panes_fade_owes_a_frame_while_it_runs_and_none_after_it_lands() {
        let now = Instant::now();
        let arriving = [(SeatId(2), [50.0, 0.0, 100.0, 100.0])];
        let mut motion = PaneMotion::default();
        motion.begin(&[], &arriving, now, Motion::Full);
        assert_eq!(
            motion.transform_of(SeatId(2), now, Motion::Full),
            PaneTransform::IDENTITY,
            "a fade moves no box, so every frame it owes is owed for its opacity"
        );

        let mut presents = 0_u32;
        let mut at = now;
        loop {
            let moving = motion.is_animating(at, Motion::Full);
            if motion.settle_frame_debt(&arriving, at, Motion::Full) {
                presents += 1;
            }
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }
        assert!(
            presents >= 5,
            "only {presents} frames of a 180ms fade were drawn — that is an \
             appearance wearing a fade's clothes"
        );
        assert!(
            !motion.settle_frame_debt(&arriving, at + STRIP_ANIMATION_FRAME, Motion::Full),
            "and once it is fully there it owes nothing"
        );
    }

    /// PIN — B22. The resizing cards pull in over exactly a hundred milliseconds
    /// on CSS `ease`, and draw nothing at all on the frame the grab lands.
    ///
    /// `.pane { transition: margin .1s ease, border-radius .1s ease, box-shadow
    /// .1s ease }` (mock-up 1464) serving `.slot.resizing .pane { margin: 5px;
    /// border-radius: 8px }` (1465-1470). Three halves of that declaration are
    /// load-bearing and each is pinned against the way it gets quietly lost: the
    /// **span** (borrow the pane FLIP's 200ms and the cards are still arriving
    /// after the seam has been dragged somewhere else), the **curve** (linear is
    /// a different gesture — it starts at full speed, which reads as a snap that
    /// then decelerates), and the **first frame** (both drawn numbers are floored
    /// at one physical pixel, so a card scaled by zero is a hairline of floor
    /// around a pane nobody is resizing).
    #[test]
    fn a_grabbed_dividers_cards_pull_in_over_a_hundred_milliseconds_on_ease() {
        let now = Instant::now();
        let mut cards = RevealTween::over(RESIZING_CARD_TRANSITION);
        cards.retarget(1.0, now, Motion::Full);

        assert_eq!(
            cards.sample(now, Motion::Full).0,
            0.0,
            "on the frame the button goes down the panes are still flush"
        );
        assert_eq!(
            seats::resizing_card_inset(1.0, cards.sample(now, Motion::Full).0),
            None,
            "and nothing is drawn for them — a one-pixel inset is a visible line \
             around a pane that has not moved"
        );

        for ms in [20_u64, 50, 80] {
            let at = now + Duration::from_millis(ms);
            let (inset, moving) = cards.sample(at, Motion::Full);
            assert!(moving, "{ms}ms into a 100ms transition it is still running");
            let want = cubic_bezier(ms as f32 / 100.0, EASE);
            assert!(
                (inset - want).abs() < 1e-6,
                "{ms}ms in the inset is {inset} where CSS `ease` says {want}"
            );
            let (margin, radius) =
                seats::resizing_card_inset(1.0, inset).expect("a running card is a card");
            assert!(
                margin <= bt_render::SEAT_RESIZING_CARD_MARGIN_LOGICAL_PX
                    && radius <= bt_render::SEAT_RESIZING_CARD_RADIUS_LOGICAL_PX,
                "and it never overshoots the declaration: {margin}, {radius}"
            );
        }

        // `ease` has a long flat tail, so the last frames of the transition round
        // to the very pixels it lands on — which is why the frame debt is settled
        // on the *drawn* inset. The frames that are genuinely part way in are the
        // early ones, and those are asserted rather than the tail.
        let (margin, radius) = seats::resizing_card_inset(
            1.0,
            cards
                .sample(now + Duration::from_millis(20), Motion::Full)
                .0,
        )
        .expect("a card twenty milliseconds in is a card");
        assert!(
            margin < bt_render::SEAT_RESIZING_CARD_MARGIN_LOGICAL_PX
                && radius < bt_render::SEAT_RESIZING_CARD_RADIUS_LOGICAL_PX,
            "twenty milliseconds in the card has not arrived: {margin}, {radius}"
        );

        let landed = now + RESIZING_CARD_TRANSITION;
        assert_eq!(
            cards.sample(landed, Motion::Full),
            (1.0, false),
            "a hundred milliseconds is the whole of it, and the loop may sleep"
        );
        assert_eq!(
            seats::resizing_card_inset(1.0, cards.sample(landed, Motion::Full).0),
            Some((
                bt_render::SEAT_RESIZING_CARD_MARGIN_LOGICAL_PX,
                bt_render::SEAT_RESIZING_CARD_RADIUS_LOGICAL_PX
            )),
            "landing on exactly the 5px and 8px F63 always drew"
        );
        assert_ne!(
            RESIZING_CARD_TRANSITION, PANE_FLIP,
            "a card inset answering a button press and half the window changing \
             shape cannot be one number"
        );
    }

    /// PIN — B22. A grab reversed mid-transition turns around from where the
    /// cards actually are, not from an end they never reached.
    ///
    /// The fourth user of [`RevealTween`] and the first one that is genuinely
    /// interrupted in ordinary use: a hand that grabs a divider, thinks better of
    /// it and lets go inside the hundred milliseconds. A CSS transition
    /// interrupted mid-flight restarts from the computed value, which is what
    /// `retarget` gives — restart from 1.0 instead and the cards jump *in* the
    /// rest of the way before running out, which is a flinch rather than a
    /// reversal.
    #[test]
    fn a_card_transition_reversed_mid_flight_turns_around_from_where_it_is() {
        let now = Instant::now();
        let mut cards = RevealTween::over(RESIZING_CARD_TRANSITION);
        cards.retarget(1.0, now, Motion::Full);

        let at = now + Duration::from_millis(40);
        let (reached, _) = cards.sample(at, Motion::Full);
        assert!(
            reached > 0.0 && reached < 1.0,
            "40ms of 100ms is genuinely mid-flight: {reached}"
        );

        cards.retarget(0.0, at, Motion::Full);
        assert!(
            (cards.sample(at, Motion::Full).0 - reached).abs() < 1e-6,
            "the reversal opens on the inset the cards had, {reached}, and not on \
             the 1.0 they were aimed at"
        );
        assert!(
            cards.sample(at + Duration::from_millis(10), Motion::Full).0 < reached,
            "and runs down from there"
        );
        assert_eq!(
            cards.sample(at + RESIZING_CARD_TRANSITION, Motion::Full),
            (0.0, false),
            "reaching flush a hundred milliseconds after the hand opened"
        );
    }

    /// PIN — B22 under reduced motion: the cards appear and vanish at once, and
    /// no frame is owed for either.
    ///
    /// Verified rather than assumed. "There is no transition under Reduced" is a
    /// property of [`RevealTween::retarget`] storing no `started`, and the two
    /// things that follow from it — the terminal inset on the first sample, and
    /// a `false` that lets `strip_animation_deadline` answer `None` — are each a
    /// separate consumer that could have read the clock for itself.
    #[test]
    fn reduced_motion_snaps_the_resizing_cards_in_and_out_and_asks_for_no_frames() {
        let now = Instant::now();
        let mut cards = RevealTween::over(RESIZING_CARD_TRANSITION);

        cards.retarget(1.0, now, Motion::Reduced);
        assert_eq!(
            cards.sample(now, Motion::Reduced),
            (1.0, false),
            "the cards are simply there, and nothing is asking to be woken"
        );
        assert_eq!(
            seats::resizing_card_inset(1.0, cards.sample(now, Motion::Reduced).0),
            Some((
                bt_render::SEAT_RESIZING_CARD_MARGIN_LOGICAL_PX,
                bt_render::SEAT_RESIZING_CARD_RADIUS_LOGICAL_PX
            )),
        );

        cards.retarget(0.0, now, Motion::Reduced);
        assert_eq!(
            cards.sample(now, Motion::Reduced),
            (0.0, false),
            "and simply gone"
        );
        assert_eq!(
            seats::resizing_card_inset(1.0, cards.sample(now, Motion::Reduced).0),
            None
        );
    }

    /// PIN — U8. A preview seat's picture travels with its pane instead of
    /// waiting at the destination.
    ///
    /// The defect this stands against is one commit deep and visible on screen:
    /// `refresh_preview_for_layout` runs once per commit and used to hand the
    /// renderer the *solved* body, so a preview pane's head and body glided over
    /// 200ms while the picture inside them was already at the box it was going
    /// to. The fix is the treatment seam 2 already got and no other — the same
    /// [`animated_pane_viewports`] pair, from the same sampler, applied to one
    /// more seat.
    ///
    /// The scenario is a three-pane tab losing its leftmost pane, which is what
    /// actually moves a preview: the preview's own *arrival* fades rather than
    /// FLIPs (mock-up 6573), and a fade has the identity transform, so an
    /// arriving preview could not tell the fixed code from the broken code. What
    /// moves it is any later structural edit, and closing a pane is the shortest
    /// one to write.
    ///
    /// Three clauses, and the third is the one a naive fix loses: the picture is
    /// **fitted** to the final body throughout. Fit it to the animating box
    /// instead and every frame of the flight is a new `preview_image_extent`, a
    /// new Lanczos target and a scale task per frame — R2's resize storm wearing
    /// the image pipeline's clothes.
    #[test]
    fn a_preview_seats_picture_travels_with_its_pane_rather_than_waiting_at_the_destination() {
        let now = Instant::now();
        let metrics = seats::seat_metrics(1_000);
        let viewport = seats::logical_viewport(1600, 900, seats::scale_ppm(1_000), 0);
        let mut seats = seats::Seats::lone_terminal();
        let first = seats.terminal();
        let second = seats
            .split_terminal(&metrics, first, bt_layout::Axis::Row, false)
            .expect("a 1600x900 window divides");
        seats.add_preview(&metrics).expect("the preview lands");
        let preview = seats.preview().expect("and it is in the tree");
        let before = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("three panes solve");
        assert!(
            seats.close_seat(&metrics, first),
            "the leftmost pane closes"
        );
        let after = seats
            .solve(viewport, &metrics, SizePolicy::Lawful)
            .expect("two panes solve");

        let was = pane_box_of(&before, preview);
        let is = pane_box_of(&after, preview);
        assert!(
            (was[0] - is[0]).abs() > 1.0,
            "the preview's own corner has to travel, or this pin proves nothing: \
             {was:?} -> {is:?}"
        );

        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&before),
            &pane_rects_of(&after),
            now,
            Motion::Full,
        );

        // The terminal beside it is still in the box it had, which is the frame
        // the picture has to be found in.
        let survivor = motion
            .transform_of(second, now, Motion::Full)
            .applied_to(pane_box_of(&after, second));
        for channel in 0..4 {
            assert!(
                (survivor[channel] - pane_box_of(&before, second)[channel]).abs() < 1e-3,
                "on the first frame the terminal is still where it was: {survivor:?} \
                 against {:?}",
                pane_box_of(&before, second)
            );
        }

        let opening = preview_image_placement(
            &seats,
            &after,
            preview,
            1.0,
            motion.transform_of(preview, now, Motion::Full),
        )
        .expect("the preview has a body");
        assert_ne!(
            opening.seat, opening.body,
            "the picture is not at the corner the solver just gave it"
        );
        assert_eq!(
            opening.seat.x as f32, was[0],
            "it is at the corner its own tween gives it, which is the one its head \
             is drawn at this frame"
        );
        assert_eq!(
            (opening.seat.width, opening.seat.height),
            (opening.body.width, opening.body.height),
            "and it is fitted to the final body from the very first frame — one \
             resample per commit, never one per frame"
        );
        assert!(
            opening.clip.width < opening.seat.width || opening.clip.x > opening.seat.x,
            "while the box it may appear in is still the narrow one it had: {:?} \
             against {:?}",
            opening.clip,
            opening.seat
        );

        let landed = preview_image_placement(
            &seats,
            &after,
            preview,
            1.0,
            motion.transform_of(preview, now + PANE_FLIP, Motion::Full),
        )
        .expect("the preview has a body");
        assert_eq!(
            (landed.seat, landed.clip),
            (landed.body, landed.body),
            "and both converge on the solver's answer"
        );
    }

    /// PIN — U8. A window resized mid-flight owes exactly the frames it draws.
    ///
    /// The debt is settled against the **live** solve, passed in, and never
    /// against a copy taken when the tween started. Nothing *drawn* depends on
    /// this — both seams apply the running transform to whatever rectangle the
    /// solver gave this frame, which is CSS's own rule that a transform is
    /// relative to the box the element is currently laid out in — so the whole
    /// cost of getting it wrong is a present that draws nothing new. That is
    /// exactly what this counts.
    ///
    /// The stale rectangle is not simulated by a mutation: it is the same call
    /// with the pre-resize layout handed in, which is precisely what a stored
    /// copy would have been. So the second half is the red gate, and it fails if
    /// the two ever stop being distinguishable.
    #[test]
    fn a_window_resized_mid_flight_owes_exactly_the_frames_it_draws() {
        let now = Instant::now();
        let seat = SeatId(1);
        let before = [(seat, [0.0, 0.0, 700.0, 700.0])];
        let solved = [(seat, [0.0, 0.0, 500.0, 500.0])];
        // The same pane after the window was dragged much narrower, mid-flight:
        // every rectangle is re-solved and the tween decays onto the new one.
        // A pure shrink is deliberate — with no translation left, the *only*
        // thing deciding which frames draw something new is the extent the scale
        // multiplies, which is exactly the term a stored rectangle gets wrong.
        let resized = [0.0, 0.0, 150.0, 120.0];
        let live = [(seat, resized)];

        // The frames on which the seams actually put something new on screen:
        // the running transform over the rectangle the window *now* has.
        let mut reference = PaneMotion::default();
        reference.begin(&before, &solved, now, Motion::Full);
        let mut redraws = Vec::new();
        let mut last: Option<[i32; 4]> = None;
        let mut at = now;
        loop {
            let moving = reference.is_animating(at, Motion::Full);
            let showing = reference
                .transform_of(seat, at, Motion::Full)
                .applied_to(resized)
                .map(|edge| edge.round() as i32);
            redraws.push(last != Some(showing));
            last = Some(showing);
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }
        assert!(
            redraws.iter().filter(|drew| **drew).count() > 3,
            "the flight has to draw several distinct boxes, or this counts nothing"
        );

        let walk = |layout: &[(SeatId, [f32; 4])]| {
            let mut motion = PaneMotion::default();
            motion.begin(&before, &solved, now, Motion::Full);
            let mut owed = Vec::new();
            let mut at = now;
            loop {
                let moving = motion.is_animating(at, Motion::Full);
                owed.push(motion.settle_frame_debt(layout, at, Motion::Full));
                if !moving {
                    break;
                }
                at += STRIP_ANIMATION_FRAME;
            }
            (owed, motion)
        };

        let (owed, settled) = walk(&live);
        assert_eq!(
            owed, redraws,
            "a present is owed on exactly the frames something new is drawn — no \
             frame of the flight is skipped, and none of them pays twice"
        );
        assert_eq!(
            settled
                .entry(seat)
                .and_then(|pane| pane.last_drawn)
                .map(|drawn| drawn.box_px),
            Some(resized.map(|edge| edge.round() as i32)),
            "and it ends recorded as drawn in the rectangle the window actually \
             has, rather than in the one it had when the split happened"
        );

        // The red gate, and it is not a simulation: handing in the pre-resize
        // layout *is* what a rectangle stored at `begin` would have been.
        let (stale, stale_motion) = walk(&before);
        assert_ne!(
            stale, redraws,
            "the pre-resize rectangle really does owe a different set of frames, \
             so this pin can fail"
        );
        assert_ne!(
            stale_motion
                .entry(seat)
                .and_then(|pane| pane.last_drawn)
                .map(|drawn| drawn.box_px),
            Some(resized.map(|edge| edge.round() as i32)),
            "and it really would end up recording a box nobody drew"
        );
    }

    /// PIN — U8. Switching tabs clears the motion: you do not glide a layout you
    /// were not looking at.
    ///
    /// The two lines `activate_tab` runs, and both of them matter. Dropping the
    /// tweens is the obvious half; adopting the arriving tab's own revision is
    /// the half that is easy to forget, and the red gate at the foot is what
    /// this pin exists for — leave the revision behind and the first commit in
    /// the tab you switched to animates a change that happened in a *different*
    /// tab, from rectangles nobody has ever seen.
    ///
    /// (Stated against the state `activate_tab` writes rather than against a
    /// `Runtime`, which needs a window and a GPU device to exist.)
    #[test]
    fn switching_tabs_drops_the_flight_and_adopts_the_arriving_tabs_own_revision() {
        let now = Instant::now();
        let (leaving, before, after, survivor, _) = split_window(true);
        let mut motion = PaneMotion::default();
        motion.begin(
            &pane_rects_of(&before),
            &pane_rects_of(&after),
            now,
            Motion::Full,
        );
        assert!(
            motion.is_animating(now, Motion::Full),
            "the tab being left is mid-flight"
        );
        // The arriving tab, which was split twice while nobody was looking.
        let metrics = seats::seat_metrics(1_000);
        let mut arriving_tab = seats::Seats::lone_terminal();
        let root = arriving_tab.terminal();
        let second = arriving_tab
            .split_terminal(&metrics, root, bt_layout::Axis::Row, false)
            .expect("it divides");
        arriving_tab
            .split_terminal(&metrics, second, bt_layout::Axis::Col, false)
            .expect("and divides again");

        // Exactly what `activate_tab` writes.
        motion = PaneMotion::default();
        let revision = arriving_tab.structure_revision();

        assert!(!motion.is_animating(now, Motion::Full));
        assert_eq!(motion.deadline(now, Motion::Full), None);
        assert_eq!(
            motion.transform_of(survivor, now, Motion::Full),
            PaneTransform::IDENTITY,
            "nothing of the tab you left is still moving"
        );
        assert_eq!(
            revision,
            arriving_tab.structure_revision(),
            "the gate is closed on arrival: the next commit in this tab compares \
             equal and leaves the motion alone"
        );
        assert_ne!(
            leaving.structure_revision(),
            arriving_tab.structure_revision(),
            "and the two counters really are different, so carrying the old one \
             across would have opened the gate on the very next commit"
        );
    }

    /// PIN — the profile picker's arrow turns over across 140ms on
    /// `cubic-bezier(.2,0,0,1)`, and it is the turn that is drawn rather than
    /// its two ends.
    ///
    /// `.chevbtn svg { transition: transform 140ms cubic-bezier(.2,0,0,1) }`
    /// (mock-up 415-418). Both halves of that declaration are load-bearing and
    /// both are pinned here against the ways they get quietly deleted: cut the
    /// duration to nothing and the arrow arrives before the first sample, so
    /// there is no midpoint left to read; swap the curve for `linear` and the
    /// midpoint lands at half a turn instead of where this curve actually puts
    /// it, which — because `.2,0,0,1` front-loads almost everything and then
    /// crawls — is nearly nine tenths of the way over.
    #[test]
    fn the_profile_chevron_turns_over_across_a_hundred_and_forty_milliseconds() {
        assert_eq!(
            CHEVRON_TURN,
            Duration::from_millis(140),
            "`transition: transform 140ms` (mock-up 417)"
        );
        assert_eq!(
            GRAB_EASE,
            [0.2, 0.0, 0.0, 1.0],
            "`cubic-bezier(.2,0,0,1)` (mock-up 417)"
        );

        let now = Instant::now();
        let mut turn = ChevronTurn::default();
        assert_eq!(
            turn.sample(now, Motion::Full),
            (0.0, false),
            "an untouched picker's arrow points down and is not moving"
        );

        turn.retarget(true, now, Motion::Full);
        assert_eq!(turn.sample(now, Motion::Full), (0.0, true));

        // The middle of the transition is a real place, and it is where this
        // curve puts it rather than where a straight line would.
        let (halfway, moving) = turn.sample(now + Duration::from_millis(70), Motion::Full);
        assert!(moving);
        assert!(
            halfway > 0.0 && halfway < 1.0,
            "70ms into a 140ms turn the arrow is partway over, saw {halfway}"
        );
        let eased = cubic_bezier(0.5, GRAB_EASE);
        assert!(
            (halfway - eased).abs() < 1e-3,
            "the turn is drawn on its own curve: expected {eased}, saw {halfway}"
        );
        assert!(
            (halfway - 0.5).abs() > 0.2,
            "halfway in time is not halfway over on this curve — saw {halfway}, \
             which is what `linear` would have given"
        );

        // It only ever goes forwards, and it stops.
        let mut last = 0.0;
        for step in 0..=14 {
            let (at, _) = turn.sample(now + Duration::from_millis(step * 10), Motion::Full);
            assert!(at >= last, "the arrow does not turn back on its way over");
            last = at;
        }
        assert!(
            turn.sample(now + Duration::from_millis(139), Motion::Full)
                .1
        );
        assert_eq!(
            turn.sample(now + Duration::from_millis(140), Motion::Full),
            (1.0, false),
            "at 140ms the arrow has arrived and owes no more frames"
        );
        assert_eq!(
            turn.sample(now + Duration::from_secs(9), Motion::Full),
            (1.0, false)
        );
    }

    /// PIN — a turn reversed mid-flight carries on from the angle the arrow is
    /// actually at.
    ///
    /// This is what a CSS transition does to a property whose target changes
    /// while it is running, and it is the whole difference between a control
    /// that turns and one that flickers: clicking the picker twice quickly must
    /// not snap the arrow to an end it never reached and then run back from
    /// there. Red gate: the sample taken at the instant of the reversal is the
    /// same number on both sides of it.
    #[test]
    fn the_chevron_reverses_from_where_the_arrow_actually_is() {
        let now = Instant::now();
        let mut turn = ChevronTurn::default();
        turn.retarget(true, now, Motion::Full);

        let reversed_at = now + Duration::from_millis(40);
        let (mid, _) = turn.sample(reversed_at, Motion::Full);
        assert!(mid > 0.0 && mid < 1.0, "caught mid-turn, saw {mid}");

        turn.retarget(false, reversed_at, Motion::Full);
        let (restarted, moving) = turn.sample(reversed_at, Motion::Full);
        assert!(moving);
        assert!(
            (restarted - mid).abs() < 1e-6,
            "the arrow jumped from {mid} to {restarted} when it was told to come back"
        );

        // And from there it goes the other way, all the way home.
        let mut last = restarted;
        for step in 1..=14 {
            let (at, _) = turn.sample(reversed_at + Duration::from_millis(step * 10), Motion::Full);
            assert!(
                at <= last,
                "the reversed turn went further over instead of coming back"
            );
            last = at;
        }
        assert_eq!(
            turn.sample(reversed_at + CHEVRON_TURN, Motion::Full),
            (0.0, false)
        );

        // Told again what it is already doing, it does not restart: a caller
        // that re-reports the same state must not stretch the transition.
        let mut steady = ChevronTurn::default();
        steady.retarget(true, now, Motion::Full);
        let at = now + Duration::from_millis(100);
        let (before, _) = steady.sample(at, Motion::Full);
        steady.retarget(true, at, Motion::Full);
        assert_eq!(steady.sample(at, Motion::Full).0, before);
        assert_eq!(
            steady.sample(now + CHEVRON_TURN, Motion::Full),
            (1.0, false)
        );
    }

    /// PIN — `@media (prefers-reduced-motion: reduce) { .chevbtn svg {
    /// transition: none } }` (mock-up 420).
    ///
    /// `none` is not a faster transition: there are no intermediate frames at
    /// all, the arrow is simply already over, and — the half that actually
    /// costs something — nothing asks to be woken up to draw the frames that do
    /// not exist.
    #[test]
    fn reduced_motion_turns_the_chevron_over_with_no_frames_in_between() {
        let now = Instant::now();
        let mut turn = ChevronTurn::default();
        turn.retarget(true, now, Motion::Reduced);
        assert_eq!(
            turn.sample(now, Motion::Reduced),
            (1.0, false),
            "under reduced motion the arrow is over the instant the list is up"
        );
        for step in 0..=14 {
            assert_eq!(
                turn.sample(now + Duration::from_millis(step * 10), Motion::Reduced),
                (1.0, false),
                "and there is never a frame of it on the way"
            );
        }
        turn.retarget(false, now + Duration::from_millis(50), Motion::Reduced);
        assert_eq!(
            turn.sample(now + Duration::from_millis(50), Motion::Reduced),
            (0.0, false)
        );
    }

    /// PIN — the turn pays the strip's frame debt in the mark's own quantized
    /// angles, so it draws every step it has and stops the moment it lands.
    ///
    /// Two failures this stands against, and they pull opposite ways. Compare
    /// the raw fraction and every wake-up of the 140ms owes a present, including
    /// the long tail where `.2,0,0,1` is crawling through less than a degree and
    /// the rasterized arrow is byte-identical. Compare nothing at all and the
    /// arrow strands on whatever frame the last present happened to catch —
    /// which is the failure `tab_owes_frame` was written for, in its original
    /// half-faded-icon form.
    #[test]
    fn the_chevron_s_frame_debt_is_paid_in_drawn_angles() {
        let now = Instant::now();
        let mut turn = ChevronTurn::default();
        turn.retarget(true, now, Motion::Full);

        // The strip wakes on its own beat; what it draws each time is the mark.
        let mut last_drawn: Option<marks::ChromeMark> = None;
        let mut presents = 0_u32;
        let mut wakes = 0_u32;
        let mut drawn = Vec::new();
        let mut at = now;
        loop {
            let (fraction, moving) = turn.sample(at, Motion::Full);
            let showing = marks::ChromeMark::chevron(fraction);
            if tab_owes_frame(last_drawn, showing) {
                last_drawn = Some(showing);
                presents += 1;
                drawn.push(showing);
            }
            wakes += 1;
            if !moving {
                break;
            }
            at += STRIP_ANIMATION_FRAME;
        }

        assert!(
            wakes > presents,
            "every single wake-up presented a frame ({presents} of {wakes}) — the debt \
             is being measured on something finer than the arrow is drawn at"
        );
        assert!(
            presents >= 5,
            "only {presents} frames of the turn were ever drawn — that is a swap \
             wearing an animation's clothes"
        );
        assert!(
            presents <= u32::from(marks::CHEVRON_TURN_STEPS),
            "a single turn asked for {presents} rasters, more than the quantum allows"
        );
        assert_eq!(
            drawn.first().copied(),
            Some(marks::ChromeMark::chevron(0.0)),
            "the turn is drawn from the arrow's resting angle"
        );
        assert_eq!(
            drawn.last().copied(),
            Some(marks::ChromeMark::chevron(1.0)),
            "and the frame it settles on is the terminal one — an arrow left at 175° is \
             the stranded-mid-breath bug wearing a different mark"
        );
        for pair in drawn.windows(2) {
            assert_ne!(pair[0], pair[1], "a present that redrew the same angle");
        }
    }

    #[test]
    fn reduced_motion_skips_the_landing_animation_outright() {
        // Mock-up 968 says so in as many words, and an animation with only a
        // `from` has nothing to hold: off means the tab, unwashed.
        let now = Instant::now();
        let mut landing = LandTween::default();
        landing.start(now, Motion::Reduced);
        assert_eq!(landing.sample(now, Motion::Reduced), (0.0, false));
    }

    #[test]
    fn a_cancelled_drag_puts_the_tab_back_without_crossing_the_pinned_seam() {
        // F57, applied to the one move geometry did not choose (K128's restore).
        let pinned = [true, true, false, false];
        assert_eq!(
            partition_clamped(&pinned, 3, 2),
            2,
            "inside its own partition the restore reaches its slot"
        );
        assert_eq!(
            partition_clamped(&pinned, 3, 0),
            2,
            "and stops at the seam rather than landing among the pinned tabs"
        );
        assert_eq!(partition_clamped(&pinned, 0, 3), 1);
        assert_eq!(partition_clamped(&pinned, 2, 2), 2, "a move to nowhere");
        assert_eq!(
            partition_clamped(&[false, false, false], 2, 0),
            0,
            "with no seam there is nothing to stop at"
        );
    }

    #[test]
    fn the_pointer_keeps_one_shape_for_the_whole_drag() {
        // K113. "The cursor changing shape mid-drag would say something happened
        // when nothing did" (mock-up 1710-1711).
        use winit::window::CursorIcon;
        assert_eq!(
            pointer_cursor(false, None, None, false, false, None),
            CursorIcon::Default
        );
        assert_eq!(
            pointer_cursor(false, None, Some(bt_layout::Axis::Row), false, false, None),
            CursorIcon::EwResize
        );
        assert_eq!(
            pointer_cursor(false, None, Some(bt_layout::Axis::Col), false, false, None),
            CursorIcon::NsResize
        );
        for axis in [None, Some(bt_layout::Axis::Row), Some(bt_layout::Axis::Col)] {
            for grasp in [
                None,
                Some(FloatGrasp::Grip),
                Some(FloatGrasp::Head),
                Some(FloatGrasp::Carrying),
            ] {
                for over_link in [false, true] {
                    assert_eq!(
                        pointer_cursor(true, grasp, axis, over_link, false, None),
                        CursorIcon::Default,
                        "a tab drag crossing a divider, a float or a link must \
                         not flicker into another shape"
                    );
                }
            }
        }
    }

    /// A markdown link says it answers a press the way every reader on the desk
    /// says it (user ruling, 2026-08-13) — and gives way to a window standing
    /// over it, because what a float covers is not what you are aiming at.
    #[test]
    fn a_markdown_link_wears_the_pointing_finger() {
        use winit::window::CursorIcon;
        assert_eq!(
            pointer_cursor(false, None, None, true, false, None),
            CursorIcon::Pointer
        );
        assert_eq!(
            pointer_cursor(false, None, Some(bt_layout::Axis::Row), true, false, None),
            CursorIcon::Pointer,
            "and over a divider it is still the link the pointer is on"
        );
        assert_eq!(
            pointer_cursor(false, Some(FloatGrasp::Head), None, true, false, None),
            CursorIcon::Grab,
            "but a window over the document takes the pointer with it"
        );
    }

    /// The two shapes a pinned float names for itself: `nwse-resize` on
    /// `.fly-resize` (mock-up 1708) and `grab`/`grabbing` on the header
    /// (704-705). The grip is the only resize target there is — the mock-up
    /// gives the float no single-axis edges, and neither does `FloatPart`.
    #[test]
    fn a_pinned_float_wears_the_diagonal_arrow_on_its_grip() {
        use winit::window::CursorIcon;
        assert_eq!(
            pointer_cursor(false, Some(FloatGrasp::Grip), None, false, false, None),
            CursorIcon::NwseResize
        );
        assert_eq!(
            pointer_cursor(false, Some(FloatGrasp::Head), None, false, false, None),
            CursorIcon::Grab
        );
        assert_eq!(
            pointer_cursor(false, Some(FloatGrasp::Carrying), None, false, false, None),
            CursorIcon::Grabbing
        );
        for axis in [Some(bt_layout::Axis::Row), Some(bt_layout::Axis::Col)] {
            assert_eq!(
                pointer_cursor(false, Some(FloatGrasp::Grip), axis, false, false, None),
                CursorIcon::NwseResize,
                "the window is drawn over the divider, so the divider is not what you are aiming at"
            );
        }
    }

    /// Which of them the float is asking for — hover, and the gesture that
    /// outlives it.
    #[test]
    fn the_grip_keeps_its_arrow_for_the_whole_pull() {
        use float::FloatPart;
        assert_eq!(
            float_grasp(None, Some(FloatPart::Grip), true),
            Some(FloatGrasp::Grip),
            "hovering the grip is the whole bug: an arrow was showing where a resize lives"
        );
        assert_eq!(
            float_grasp(None, Some(FloatPart::Head), true),
            Some(FloatGrasp::Head)
        );
        for part in [
            FloatPart::Body,
            FloatPart::Foot,
            FloatPart::Dock,
            FloatPart::Close,
            FloatPart::Row(0),
        ] {
            assert_eq!(
                float_grasp(None, Some(part), true),
                None,
                "the rest of the window is an ordinary arrow"
            );
        }
        // The pull survives the pointer leaving the grip it began on — the
        // corner stops at the 200×150 floor while the hand keeps going.
        assert_eq!(
            float_grasp(Some(FloatDragKind::Resize), Some(FloatPart::Body), true),
            Some(FloatGrasp::Grip)
        );
        assert_eq!(
            float_grasp(Some(FloatDragKind::Move { grab: [0.0, 0.0] }), None, true),
            Some(FloatGrasp::Carrying)
        );
        // A peek is not a window you were told you had: its header is not a
        // handle, and it is drawn without a grip at all.
        assert_eq!(float_grasp(None, Some(FloatPart::Head), false), None);
        assert_eq!(float_grasp(None, Some(FloatPart::Grip), false), None);
        // **But the carry a peek's header turns into wears the closed fist**
        // (rule ③, 2026-08-12). The gesture is asked before the hover and before
        // `pinned`, which is what makes this true without a special case: by the
        // time the drag exists the window has been promoted anyway, and even a
        // frame where the two disagreed would be answered by the drag.
        assert_eq!(
            float_grasp(
                Some(FloatDragKind::Move { grab: [60.0, 12.0] }),
                Some(FloatPart::Head),
                false
            ),
            Some(FloatGrasp::Carrying),
            "a peek being carried off is a hand that has closed on something"
        );
    }

    /// User ruling 2026-08-12, which overturns `M2-tiny-window-priority.md`
    /// §3.3: a float may stand on the rail and on the pane heads — the overlay
    /// order already draws it over them — and may never stand on the caption,
    /// whose buttons and drag band have to be reachable at every moment.
    #[test]
    fn a_float_may_stand_anywhere_in_the_window_except_the_title_bar() {
        let caption = |scale: f32| (bt_render::WINDOW_TITLE_BAR_LOGICAL_PX * scale).round();
        let rect = float_viewport_rect(2200, 1400, 2.0);
        assert_eq!(
            rect,
            [0.0, caption(2.0), 2200.0, 1400.0],
            "the rail's own column, the pane heads and every edge of the client \
             area are ground a float may cover; only the caption is removed"
        );
        assert_eq!(
            float_viewport_rect(800, 600, 1.0),
            [0.0, 40.0, 800.0, 600.0],
            "and the strip is the title bar's own 40 logical px, not a number of \
             this function's own"
        );
        // The floor under the tiny-window ladder: a client area shorter than its
        // own caption still answers with a rectangle that is the right way up,
        // because every clamp downstream subtracts from these two edges.
        let tiny = float_viewport_rect(120, 20, 2.0);
        assert!(
            tiny[1] < tiny[3],
            "a viewport must never come back inverted: {tiny:?}"
        );
    }

    #[test]
    fn a_drag_that_never_starts_leaves_the_press_exactly_as_t4_left_it() {
        // The seam between T4 and T5, from T5's side: the 6px and the identity
        // are the press's, and the move it names as the drag's first is the
        // only thing this slice reads.
        let now = Instant::now();
        let mut press = TabPress::armed(TabId(1), PhysicalPosition::new(100.0, 20.0), now);
        assert!(!press.travelled(PhysicalPosition::new(105.0, 20.0), 1.0));
        assert_eq!(press.promise, TabPressPromise::Pending);
        assert!(press.travelled(PhysicalPosition::new(106.0, 20.0), 1.0));
        assert_eq!(press.promise, TabPressPromise::Slipped);
        assert!(
            !press.travelled(PhysicalPosition::new(300.0, 20.0), 1.0),
            "the drag starts once — every later move is the gesture, not its start"
        );
    }

    // ── U4: the engine tabs and panes share (J111-J122) ──

    /// A drag carrying `source`, with `landing` last surveyed. The carry is a
    /// tab's when the source is a tab, because that pairing is the engine's
    /// invariant rather than a choice any caller makes.
    fn drag_of(source: DragSource, landing: Option<DropLanding>) -> Drag {
        Drag {
            carry: match source {
                DragSource::Tab(tab) => DragCarry::Tab(TabCarry {
                    grab: 0.0,
                    origin: 0,
                    offset: 0.0,
                    moved: false,
                    home: tab,
                }),
                DragSource::Pane(_) | DragSource::Row(_) => DragCarry::Pane,
            },
            source,
            pointer: PhysicalPosition::new(0.0, 0.0),
            landing,
            home: None,
        }
    }

    /// J113 — one threshold, and it belongs to the latch rather than to either
    /// press that owns one.
    ///
    /// The tab's half of this is already pinned by
    /// `travelling_past_six_pixels_abandons_the_delayed_switch`; what is new is
    /// that a pane head crosses the *same* six pixels, measured the same way, at
    /// every scale.
    ///
    /// Red gate: give the pane its own constant — any other number — and the
    /// middle assertion of each pass fails, because 6.0 is the only radius that
    /// is short of at 5px and past at 7px.
    #[test]
    fn a_pane_head_and_a_tab_cross_the_same_six_pixels() {
        for scale in [1.0_f64, 1.5, 2.0] {
            let origin = PhysicalPosition::new(100.0, 200.0);
            let mut pane = DragLatch::new(origin);
            let mut tab = TabPress::armed(TabId(1), origin, Instant::now());
            let short = PhysicalPosition::new(100.0 + 5.0 * scale, 200.0);
            let far = PhysicalPosition::new(100.0 + 7.0 * scale, 200.0);
            assert!(
                !pane.travelled(short, scale),
                "5 logical px is still a press"
            );
            assert!(!tab.travelled(short, scale), "and the tab agrees");
            assert!(pane.travelled(far, scale), "7 logical px is a drag");
            assert!(tab.travelled(far, scale), "and the tab agrees");
            assert!(
                !pane.travelled(PhysicalPosition::new(900.0, 900.0), scale),
                "the drag starts once, for a pane exactly as for a tab"
            );
        }
        // Euclidean, not per-axis: a diagonal hand travels as far as a straight
        // one. 4/4 is 5.66 and short; 5/5 is 7.07 and past.
        let mut latch = DragLatch::new(PhysicalPosition::new(0.0, 0.0));
        assert!(!latch.travelled(PhysicalPosition::new(4.0, 4.0), 1.0));
        assert!(latch.travelled(PhysicalPosition::new(5.0, 5.0), 1.0));
    }

    /// J120 — a release that landed nowhere goes home, and it is not the same
    /// answer as a release that landed.
    ///
    /// Red gate: the mock-up's own behaviour is `DragRelease::Commit` for both
    /// arms — `!d.target` falls in beside `d.target.reordered` and returns
    /// without undoing the live reorder (7202-7208). Return `Commit` for `None`
    /// here and this is the assertion that says the ruling was dropped.
    #[test]
    fn a_release_that_landed_nowhere_sends_the_gesture_home_rather_than_committing() {
        assert_eq!(release_verdict(None), DragRelease::Home);
        assert_eq!(
            release_verdict(Some(DropLanding::StripReorder { slot: 3 })),
            DragRelease::Commit,
            "the strip already applied it — committing is letting it stand"
        );
    }

    /// J116/K124 — the ghost stands down when the landing is already showing the
    /// user what it means.
    ///
    /// "The tab itself is the feedback" (mock-up 6837). A tab reordering in the
    /// strip is holding the slot it would take, so a second label saying the same
    /// name under the pointer is the drag telling you twice — and the one in the
    /// strip is the one telling you *where*. A pane has no such stand-in: nothing
    /// on screen moves for it, so the ghost is the entire report.
    ///
    /// Red gate: make `shows_itself` answer `false` and the first assertion
    /// fails; drop the `!` from `ghost_is_shown` and the second does.
    #[test]
    fn the_ghost_yields_to_a_landing_that_is_already_showing_itself() {
        let tab = drag_of(
            DragSource::Tab(TabId(1)),
            Some(DropLanding::StripReorder { slot: 0 }),
        );
        assert!(
            !tab.ghost_is_shown(),
            "the reordering tab is its own feedback"
        );
        let pane = drag_of(DragSource::Pane(bt_layout::SeatId(1)), None);
        assert!(
            pane.ghost_is_shown(),
            "nothing else on screen has moved for a pane, so the ghost is all there is"
        );
        assert!(
            drag_of(DragSource::Tab(TabId(1)), None).ghost_is_shown(),
            "a tab with nowhere to land is carried by the ghost like anything else"
        );
    }

    /// J111/J118 — one drag, two things it can be carrying, and a pane carries
    /// nothing that would let it be sent home.
    ///
    /// This is the guard `settle_home` reads, stated where it can be seen: a
    /// pane's J120 is a no-op *because* there is no carry to unwind, and there is
    /// no carry because the tree was never touched. The two are the same fact.
    ///
    /// Red gate: fold `TabCarry`'s four fields onto every drag — one struct, four
    /// `Option`s or four zeros — and `tab_carry()` answers `Some` for a pane.
    /// `settle_home` then reads `origin: 0` off it and walks whichever tab
    /// happens to be in slot 0 across the strip, on a gesture that was carrying a
    /// pane and never named a tab at all.
    #[test]
    fn a_pane_drag_carries_no_slot_and_no_offset_so_it_has_no_way_home() {
        let pane = drag_of(DragSource::Pane(bt_layout::SeatId(7)), None);
        assert_eq!(pane.tab(), None);
        assert!(
            pane.tab_carry().is_none(),
            "nothing moved, so nothing has to move back"
        );
        let tab = drag_of(DragSource::Tab(TabId(4)), None);
        assert_eq!(tab.tab(), Some(TabId(4)));
        assert!(tab.tab_carry().is_some());
    }

    // ── U5: what the pointer has found (K123-K135) ──

    /// **K135 — never onto yourself, in any zone.**
    ///
    /// Splitting a pane against itself and swapping it with itself are both the
    /// identity, so the honest report of a gesture that would do nothing is that
    /// there is nothing under the pointer. Note it is the *whole* pane that goes
    /// dead and not only its middle: `drag.leafId === leafId` is tested after the
    /// zone is computed and ignores it (7101).
    ///
    /// Red gate: drop the identity test and a pane held over its own left third
    /// answers `SeatEdge`, which U7 would turn into a split of a seat against
    /// itself.
    #[test]
    fn a_pane_has_no_landing_anywhere_on_itself() {
        let mine = bt_layout::SeatId(3);
        let other = bt_layout::SeatId(4);
        let held = DragSource::Pane(mine);
        for aim in [
            seats::LayoutAim::SeatEdge(mine, seats::DropEdge::Left),
            seats::LayoutAim::SeatEdge(mine, seats::DropEdge::Bottom),
            seats::LayoutAim::SeatCentre(mine),
        ] {
            assert_eq!(
                landing_for_aim(&held, aim),
                None,
                "a pane held over its own rectangle has no landing: {aim:?}"
            );
        }
        assert_eq!(
            landing_for_aim(&held, seats::LayoutAim::SeatCentre(other)),
            Some(DropLanding::SeatCentre { target: other }),
            "a neighbour is a target like any other"
        );
        assert_eq!(
            landing_for_aim(
                &DragSource::Tab(TabId(1)),
                seats::LayoutAim::SeatCentre(mine)
            ),
            Some(DropLanding::SeatCentre { target: mine }),
            "a tab is not any pane, so no pane is its own"
        );
    }

    /// **K130/G83 — the rim belongs to no seat, so it can never be your own.**
    ///
    /// Dragging your own pane out to the rim is precisely how you ask for it to
    /// sit beside everything else, which is the gesture G82 exists to give and
    /// the one the root split had no edge to offer before.
    ///
    /// Red gate: run the identity test before the match instead of inside its two
    /// seat arms and the rim goes dead for pane drags — the only source that has
    /// any use for it.
    #[test]
    fn the_rim_is_no_ones_pane() {
        for edge in seats::DropEdge::NEAREST_FIRST {
            assert_eq!(
                landing_for_aim(
                    &DragSource::Pane(bt_layout::SeatId(1)),
                    seats::LayoutAim::Rim(edge)
                ),
                Some(DropLanding::RootRim { edge })
            );
        }
    }

    /// **The two strip landings yield the ghost; the three layout ones do not.**
    ///
    /// The mock-up sets `drag.ghost.style.opacity = "0"` inside the strip and
    /// says why beside the *pane* case: "the preview in the strip is the ghost
    /// now" (6792). Out over the layout the preview is a box drawn somewhere
    /// else, saying something the ghost does not, so both are on screen at once.
    ///
    /// Red gate: give `StripExtract` the layout's answer and a pane torn towards
    /// the strip is labelled twice, once under the pointer and once in the slot;
    /// give a rim the strip's answer and the hand goes empty over the layout.
    #[test]
    fn only_the_strip_takes_the_ghosts_place() {
        assert!(DropLanding::StripReorder { slot: 0 }.shows_itself());
        assert!(DropLanding::StripExtract { slot: 2 }.shows_itself());
        assert!(
            !DropLanding::RootRim {
                edge: seats::DropEdge::Left
            }
            .shows_itself()
        );
        assert!(
            !DropLanding::SeatEdge {
                target: bt_layout::SeatId(1),
                edge: seats::DropEdge::Top
            }
            .shows_itself()
        );
        assert!(
            !DropLanding::SeatCentre {
                target: bt_layout::SeatId(1)
            }
            .shows_itself()
        );
    }

    /// **U5 commits nothing it did not already commit.**
    ///
    /// **U7 — the commit table, all five landings** (mock-up 7202-7231).
    ///
    /// Four answers, and each one is a different relationship to work: the strip
    /// reorder is *kept* (it happened live, slot by slot), the three landings in
    /// the layout are *performed* now against the tree the plan built (the tree
    /// was untouched all gesture), the tear-out is performed now against the
    /// *strip*, and only an empty hand goes home having decided nothing.
    ///
    /// `StripExtract` used to sit with the empty hand, on the argument that a
    /// torn-out pane needs a tab to arrive in and a tab was a tree *and a shell*.
    /// Panes own sessions now: the pane arrives carrying the one it was already
    /// running (N157/K123), so the landing carries its slot into the verdict and
    /// the release performs it.
    ///
    /// Red gate: send `StripExtract` back to `Home` and the tear-out is silently
    /// abandoned behind a caret the strip drew; send any of the three layout
    /// landings to `Home` and the drop goes missing behind a preview that
    /// promised it.
    #[test]
    fn the_release_table_keeps_the_strip_performs_the_layout_and_sends_the_rest_home() {
        assert_eq!(
            release_verdict(Some(DropLanding::StripReorder { slot: 3 })),
            DragRelease::Commit,
            "the strip already did it"
        );
        for landing in [
            DropLanding::RootRim {
                edge: seats::DropEdge::Bottom,
            },
            DropLanding::SeatEdge {
                target: bt_layout::SeatId(2),
                edge: seats::DropEdge::Right,
            },
            DropLanding::SeatCentre {
                target: bt_layout::SeatId(2),
            },
        ] {
            assert_eq!(
                release_verdict(Some(landing)),
                DragRelease::Land,
                "{landing:?} is a drop, and letting go performs it"
            );
        }
        assert_eq!(
            release_verdict(Some(DropLanding::StripExtract { slot: 1 })),
            DragRelease::Extract { slot: 1 },
            "N157: the pane arrives in the strip carrying its own shell, at the slot \
             the survey drew the caret in"
        );
        assert_eq!(release_verdict(None), DragRelease::Home);
    }

    /// **I106 — a strip entry needs a shell, so only a Terminal pane may become
    /// one.**
    ///
    /// The predicate that replaced `tab_can_host`, and it is narrower in exactly
    /// the way U12 stage C is about: the old guard asked whether a *tree* held
    /// one terminal leaf and therefore forbade the two-shell tab that N159 and
    /// N161 exist to create. What is actually forbidden is a *files* or
    /// *preview* pane arriving in the strip, because a `TabState` requires a
    /// non-empty `sessions` and a `focused_leaf` naming one of them — a files tab
    /// keeps no shell at all and this build has no such thing.
    ///
    /// All four kinds are asked, including `Placeholder`, which is a leaf whose
    /// kind this build did not recognise when it read the session file: it has no
    /// shell either, and turning one into a terminal tab would be the silent
    /// promotion §1.1 forbids.
    ///
    /// Red gate: answer `true` for Files and a files column torn into the strip
    /// becomes a tab with nothing running in it — I106's crash by its own name.
    /// Answer `false` for Terminal and the tear-out is never offered at all and
    /// N157 is unreachable again.
    ///
    /// **Still `false` for Files after the files state landed, and the reason is
    /// worth writing down** — the slice that gave a files column a home, a root
    /// and a place on disk was also the slice that expected to overturn this,
    /// and could not. A files *tab* is not one more `true` here; it is a tab with
    /// an empty `sessions` map, and three separate layers currently rule that
    /// out:
    ///
    /// 1. `Runtime` derefs to `TabState` derefs to `LeafSession`, a chain that
    ///    resolves roughly a hundred `self.session` / `self.grid` /
    ///    `self.projection` accesses to *the focused shell*. Each is a path that
    ///    assumes a terminal, and each needs an answer for a tab that has none —
    ///    which is a ruling per call site, not a mechanical edit. This is
    ///    precisely the bomb family `UI-UX.md` §10 principle 20 describes.
    /// 2. `seats::Seats` carries a mandatory `terminal: SeatId`, `lone_seat`
    ///    debug-asserts the arriving seat is a Terminal, and `from_persisted`
    ///    answers `None` for a tree with no Term leaf at all.
    /// 3. The strip's identity paths — `tabLabel`'s three-level fallback,
    ///    `tabIcon`'s folder mark, `tabTip`, `tabKey`, and `paintStrip`'s guard
    ///    against a tab with no `.ticon`/`.unreaddot` (I118-I123) — are all
    ///    unbuilt, and they are what a files tab would be *made of*.
    ///
    /// So the honest answer here is unchanged, and the file's own note above
    /// still stands: the day files tabs land, this function deletes itself.
    #[test]
    fn only_a_terminal_pane_can_become_a_tab_of_its_own() {
        assert!(
            pane_can_become_a_tab(bt_layout::SeatKind::Terminal),
            "a terminal pane brings the shell a strip entry needs"
        );
        assert!(
            !pane_can_become_a_tab(bt_layout::SeatKind::Files),
            "I106: a files column must become a files tab, which does not exist yet"
        );
        assert!(
            !pane_can_become_a_tab(bt_layout::SeatKind::Preview),
            "a preview holds an image, not a session"
        );
        assert!(
            !pane_can_become_a_tab(bt_layout::SeatKind::Placeholder),
            "an unrecognised leaf must not be promoted into a terminal"
        );
    }

    /// A tab holding one files column and one terminal, with the column rooted.
    fn tab_with_a_files_column(id: u64, root: &str) -> TabState {
        let (seats, _, _, files, _preview) =
            revive_plan(&saved_files_and_terminal(bt_persist::FilesLeafV1 {
                view: bt_persist::FilesViewV1::Files,
                root: root.to_owned(),
                open: Vec::new(),
                sel: None,
                width: 240,
                remotes_open: false,
            }));
        let terminals = seats.terminals();
        let focused = terminals[0];
        let sessions: BTreeMap<SeatId, LeafSession> = terminals
            .iter()
            .map(|s| (*s, leaf_saying("SHELL")))
            .collect();
        let (layout, overflow) = cross_solve(&seats);
        assemble_tab_state(
            TabId(id),
            sessions,
            files,
            preview::PreviewPool::default(),
            PreviewPanes::default(),
            BTreeMap::new(),
            focused,
            TabSeed::default(),
            seats,
            layout,
            overflow,
        )
    }

    // ── C36-C38 / L157-L167: the tree's state, lazily fed ──────────────────

    fn dir_entry(name: &str, is_dir: bool) -> files::DirEntry {
        files::DirEntry {
            name: name.to_owned(),
            is_dir,
            is_symlink: false,
        }
    }

    fn listed(entries: Vec<files::DirEntry>) -> files::DirOutcome {
        files::DirOutcome::Listed(files::DirListing {
            entries,
            omitted: 0,
            canonical: None,
        })
    }

    /// A tab holding one files column, and that column's seat.
    fn files_column(root: &str) -> (TabState, SeatId) {
        let tab = tab_with_a_files_column(1, root);
        let seat = tab.seats.files()[0];
        (tab, seat)
    }

    /// PIN — L157/C38. A column asks for its root and for nothing else.
    ///
    /// The whole of laziness is here: an unopened folder is not "not loaded
    /// yet", it is a folder nobody asked about, and a walk that put it on the
    /// list would read the disk to draw rows that are not on screen.
    #[test]
    fn a_column_asks_for_its_root_and_then_only_for_what_is_opened() {
        let (mut tab, seat) = files_column("D:\\work");
        let wanted = |tab: &TabState| tab.files_tree_walk()[&seat].1.clone();
        assert_eq!(
            wanted(&tab),
            vec![String::new()],
            "an unread column asks for its root"
        );

        let cache = tab.file_trees.entry(seat).or_default();
        cache.mark_pending("");
        assert!(
            wanted(&tab).is_empty(),
            "and does not ask a second time while the first is outstanding"
        );

        tab.file_trees
            .get_mut(&seat)
            .expect("the cache exists")
            .accept(
                "",
                listed(vec![dir_entry("src", true), dir_entry("a.txt", false)]),
            );
        assert!(
            wanted(&tab).is_empty(),
            "a folded folder is not a folder anybody is waiting for"
        );
        assert_eq!(
            tab.files_tree_walk()[&seat]
                .0
                .rows
                .iter()
                .map(|row| row.key.as_str())
                .collect::<Vec<_>>(),
            vec!["/src", "/a.txt"]
        );

        tab.files
            .get_mut(&seat)
            .expect("the column has state")
            .open
            .insert("/src".to_owned());
        assert_eq!(
            wanted(&tab),
            vec!["/src".to_owned()],
            "opening it is what makes it a question"
        );
    }

    /// PIN — C155/C36. A press writes the durable state, and the right half of
    /// it: a directory opens and a file only selects.
    #[test]
    fn a_press_selects_and_only_a_directory_also_opens() {
        let mut state = seats::FilesLeafState {
            root: "D:\\work".to_owned(),
            ..seats::FilesLeafState::default()
        };

        assert!(press_files_node(
            &mut state,
            "/src",
            files::RowKind::Directory { open: false }
        ));
        assert_eq!(state.sel.as_deref(), Some("/src"));
        assert!(state.open.contains("/src"));

        assert!(!press_files_node(
            &mut state,
            "/src",
            files::RowKind::Directory { open: true }
        ));
        assert!(!state.open.contains("/src"), "the second press folds it");
        assert_eq!(state.sel.as_deref(), Some("/src"), "and it stays selected");

        assert!(!press_files_node(
            &mut state,
            "/a.txt",
            files::RowKind::File
        ));
        assert_eq!(state.sel.as_deref(), Some("/a.txt"));
        assert!(
            state.open.is_empty(),
            "a file has nothing to open, and opening the tree at its path would \
             be a folder that does not exist"
        );

        assert!(!press_files_node(
            &mut state,
            "/link",
            files::RowKind::Cycle
        ));
        assert_eq!(state.sel.as_deref(), Some("/link"));
        assert!(
            state.open.is_empty(),
            "a folder that is its own ancestor refuses to open"
        );
    }

    // ── slice 2: the read-only view family ──────────────────────────────

    /// PIN — P108, at the rectangle. **Only additions and deletions are
    /// tinted, and every tint is the width of the body.**
    ///
    /// The mock-up's own comment names the double bug this pins: half-width
    /// tints, from a band derived out of the text, and a mid-pane scrollbar. A
    /// diff read at a horizontal scroll is where both show, so the assertion is
    /// made at one.
    ///
    /// Mutation: tint `Context` as well, or build the band from `row_rect`
    /// instead of `band_rect`.
    #[test]
    fn only_the_changed_lines_of_a_diff_are_tinted_and_the_tints_are_full_width() {
        let palette = bt_render::chrome_palette();
        let body = [40.0, 100.0, 440.0, 400.0];
        let metrics = seats::preview_diff_metrics(1.0);
        let source = "diff --git a/x b/x\n--- a/x\n+++ b/x\n@@ -1,2 +1,2 @@\n-was\n+now\n keep\n";
        let mut top = 0.0_f32;
        let rows: Vec<DiffRow> = source
            .lines()
            .map(|line| {
                let kind = preview::diff_line_kind(line);
                if kind == preview::DiffLineKind::Hunk {
                    top += 8.0;
                }
                let row = DiffRow {
                    text: line.to_owned(),
                    kind,
                    top,
                };
                top += metrics.line_height;
                row
            })
            .collect();
        let geometry = seats::preview_mono_geometry(body, metrics, top, 400, 8.0, [260.0, 0.0]);
        let built = build_preview_diff_body(&geometry, &rows, &palette);

        assert_eq!(built.quads.len(), 2, "one deletion and one addition");
        for quad in &built.quads {
            assert_eq!(
                [quad.rect[0], quad.rect[2]],
                [body[0], body[2]],
                "a tint is the body's width even at 260px of horizontal scroll"
            );
        }
        assert_eq!(built.quads[0].color, palette.preview_diff_del);
        assert_eq!(built.quads[1].color, palette.preview_diff_add);

        // And the inks: the header is quiet, the hunk marker is the accent, the
        // rest is body text.
        let ink = |index: usize| built.paragraphs[index].runs[0].color;
        assert_eq!(ink(0), palette.files_row_muted, "diff --git");
        assert_eq!(ink(1), palette.files_row_muted, "---");
        assert_eq!(ink(2), palette.files_row_muted, "+++");
        assert_eq!(ink(3), palette.preview_diff_hunk, "@@");
        assert_eq!(ink(4), palette.preview_body_text, "-was");
        assert_eq!(ink(6), palette.preview_body_text, " keep");
        // `.dhunk { margin-top: 8px }` pushes the hunk and everything under it.
        assert_eq!(
            built.paragraphs[3].rect[1] - built.paragraphs[2].rect[1],
            metrics.line_height + 8.0
        );
    }

    /// PIN — the grid's first row is its heading, in ink and in ground.
    ///
    /// Mutation: fill every row rather than the first, or give the data rows
    /// the heading's ink.
    #[test]
    fn a_tables_heading_row_stands_on_its_own_fill() {
        let palette = bt_render::chrome_palette();
        let body = [0.0, 0.0, 600.0, 400.0];
        let rows = preview::csv_rows("case,cols\ncjk,2\nemoji,2\n");
        let geometry =
            seats::preview_table_geometry(body, &[5, 4], rows.len(), 8.0, 1.0, [0.0, 0.0]);
        let built = build_preview_table_body(&geometry, &rows, &palette);

        let fills: Vec<_> = built
            .quads
            .iter()
            .filter(|quad| quad.color == palette.files_row_hover)
            .collect();
        assert_eq!(fills.len(), 1, "one heading fill, not one per row");
        assert_eq!(fills[0].rect, geometry.row_rect(0));
        assert!(
            built
                .quads
                .iter()
                .any(|quad| quad.color == palette.preview_grid_line),
            "and the hairlines are drawn"
        );

        let head: Vec<_> = built
            .paragraphs
            .iter()
            .filter(|p| p.runs[0].color == palette.preview_table_head_text)
            .collect();
        assert_eq!(head.len(), 2, "two heading cells");
        assert!(head.iter().all(|p| p.runs[0].bold && p.runs[0].mono));
        let data: Vec<_> = built
            .paragraphs
            .iter()
            .filter(|p| p.runs[0].color == palette.files_row_text)
            .collect();
        assert_eq!(data.len(), 4, "two data rows of two cells");
        assert!(data.iter().all(|p| !p.runs[0].bold));
    }

    /// PIN (user report, 2026-08-13: "整屏空白") — **a block paints every pixel
    /// it reserved, and the rows it paints are the rows it was measured for.**
    ///
    /// The reported hole. A list was measured with the shaper — each item asked
    /// how many lines it took when *wrapped* into the pane — and then drawn on
    /// the assumption that every item took exactly one. In `docs/DESIGN.md`, read
    /// in a pane narrow enough that its long items wrap three and four ways, the
    /// two answers differ by most of a screen, and the difference came out as
    /// blank: the block reserved what the measurement asked for, painted a third
    /// of it, and the next heading began below the reservation. Its quieter twin
    /// was that every wrapped item's second line was clipped by the same
    /// one-line box, which is text going missing rather than space appearing.
    ///
    /// Stated as the property and not as the document: **the n-th row starts
    /// where the first n-1 rows ended, and the last one ends where the block
    /// does.** That is true of a list, a quote and a table alike, which is why
    /// all three are asserted here through the one painter.
    ///
    /// MUTATION: give the list arm of `build_preview_markdown_body` back its
    /// `let item_height = metrics.line_height;` and the second item's box is a
    /// line tall in a three-line hole — every assertion below the first goes red.
    #[test]
    fn a_wrapped_row_is_painted_in_the_box_it_was_measured_for() {
        let palette = bt_render::chrome_palette();
        let body = [0.0, 0.0, 600.0, 4000.0];
        let metrics = seats::preview_markdown_metrics(1.0);
        let line = metrics.line_height;
        let origin = body[1] + metrics.padding_y;

        // Three items that wrap to one, three and two lines. Uneven on purpose:
        // equal rows would let the buggy painter answer right by accident.
        //
        // **The rows carry `li + li { margin-top: .25em }` since 2026-08-16**
        // (§7.1.3i): the gap lives in the *top* of every row after the first,
        // exactly as `measure_markdown_block` now reserves it, so the property
        // being asserted is unchanged — the box is what the measurement asked
        // for — and the text inside it starts below its own margin.
        let blocks = preview::parse_markdown("- one\n- two\n- three\n");
        let gap = metrics.list_item_gap;
        let heights = vec![line, gap + line * 3.0, gap + line * 2.0];
        let layout = vec![MarkdownBlockLayout::rows(heights.clone(), 0.0)];
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (&blocks, &layout),
            &palette,
        );
        let items: Vec<_> = built
            .paragraphs
            .iter()
            .filter(|p| {
                p.runs
                    .first()
                    .is_some_and(|run| run.text.starts_with('\u{2022}'))
            })
            .collect();
        assert_eq!(items.len(), 3, "one paragraph per item");
        let mut expected_top = origin;
        for (index, item) in items.iter().enumerate() {
            let margin = if index == 0 { 0.0 } else { gap };
            assert_eq!(
                item.rect[1],
                expected_top + margin,
                "item {index} starts where the items above it ended, plus its own \
                 `li + li` margin"
            );
            assert_eq!(
                item.rect[3] - expected_top,
                heights[index],
                "item {index} is given the box its own wrap was measured into"
            );
            expected_top = item.rect[3];
        }
        assert_eq!(
            expected_top,
            origin + layout[0].height,
            "and the last row ends exactly where the block does — no hole under it"
        );

        // The same property for a quote, whose rows sit inside the block's own
        // padding, and whose accent bar spans the whole of it rather than one
        // bar per line.
        // A bare `>` between them, because two *source* lines of a quote are one
        // quoted paragraph since the CommonMark ruling of 2026-08-13 — what this
        // assertion is about is a quote with two entries, and that is how one is
        // now written.
        let quoted = preview::parse_markdown("> a\n>\n> b\n");
        let quote_rows = vec![line * 2.0, line];
        let quote_layout = vec![MarkdownBlockLayout::rows(
            quote_rows.clone(),
            metrics.quote_padding_y * 2.0,
        )];
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (&quoted, &quote_layout),
            &palette,
        );
        let bars: Vec<_> = built
            .quads
            .iter()
            .filter(|quad| quad.color == palette.accent)
            .collect();
        assert_eq!(bars.len(), 1, "one bar for the quote, not one per line");
        assert_eq!(
            bars[0].rect[3] - bars[0].rect[1],
            quote_layout[0].height,
            "and it is as tall as the block it marks"
        );
        assert_eq!(bars[0].rect[2] - bars[0].rect[0], metrics.quote_bar);
        let lines: Vec<_> = built
            .paragraphs
            .iter()
            .filter(|p| p.rect[0] > bars[0].rect[2])
            .collect();
        assert_eq!(lines.len(), 2);
        assert_eq!(lines[0].rect[1], origin + metrics.quote_padding_y);
        assert_eq!(
            lines[1].rect[1],
            lines[0].rect[1] + quote_rows[0],
            "the second quoted line clears the first one's own wrap"
        );
    }

    /// PIN — `docs/DESIGN.md`, the file the report was made against, parses into
    /// blocks that reserve nothing they cannot paint.
    ///
    /// The fixture is the real file rather than a sample of it, because two of
    /// the three hypotheses for the hole were about the *document* and not about
    /// the painter: a fence left open by an indented closer would swallow the
    /// rest of the file into one enormous `Code` block, and a pipe row measured
    /// as prose would be a paragraph the width of a table. Both are refuted here
    /// by construction, and stay refuted if someone edits the document.
    ///
    /// PIN — **the glance card's document is the preview pane's document**, kind
    /// for kind and shape for shape (user ruling, 2026-08-13).
    ///
    /// The card asks [`preview::preview_view`] which body a file is, exactly as a
    /// pane does, and then goes down the same builders. So the claim to pin is
    /// that those two steps, run at the card's own width, produce the pane's own
    /// shapes: a csv is a *table* — cells with a heading band and a grid — and a
    /// patch is three inks with bands under two of them. Neither is a list of
    /// lines, which is what the card drew before the ruling and what a regression
    /// would silently go back to.
    ///
    /// The height each one comes out at is asserted beside it, because that is
    /// the number the card is sized by: a two-row table must be a shorter card
    /// than a twenty-row one, or "the card shrink-wraps its body" has stopped
    /// being true the moment the body stopped being lines.
    ///
    /// MUTATION: give the card a `PreviewView::Text` document for every file (the
    /// plain-text body this replaced) — the table assertions lose their grid and
    /// their heading band, and the diff's two tints collapse to none.
    #[test]
    fn the_glance_cards_document_is_the_panes_own_table_and_its_own_three_inks() {
        let scale = 1.0_f32;
        let palette = bt_render::chrome_palette();
        let advance = 7.0_f32;
        let body = [
            0.0,
            0.0,
            file_peek::body_width(scale),
            file_peek::body_max_height(scale),
        ];

        // ① A csv is a table on both surfaces, because one predicate answers for
        //    both.
        assert_eq!(
            preview::preview_view("rows.csv", preview::preview_ftype("rows.csv"), false),
            preview::PreviewView::Table
        );
        let csv = "name,size\nalpha,10\nbeta,20\n";
        let rows = preview::csv_rows(csv);
        let columns = rows.iter().map(Vec::len).max().unwrap_or(0);
        let column_cells: Vec<usize> = (0..columns)
            .map(|column| {
                rows.iter()
                    .filter_map(|row| row.get(column))
                    .map(|cell| bt_unicode::text_width(cell))
                    .max()
                    .unwrap_or(0)
            })
            .collect();
        let table = PreviewDocument::Table {
            rows: rows.clone(),
            column_cells: column_cells.clone(),
        };
        let geometry = seats::preview_table_geometry(
            body,
            &column_cells,
            rows.len(),
            advance,
            scale,
            [0.0, 0.0],
        );
        let drawn = build_preview_table_body(&geometry, &rows, &palette);
        assert_eq!(
            drawn.paragraphs.len(),
            rows.len() * columns,
            "one paragraph per cell — a table, not three lines of commas"
        );
        assert!(
            drawn
                .paragraphs
                .iter()
                .any(|cell| cell.runs.iter().any(|run| run.text == "alpha")),
            "and the cells hold the file's own words"
        );
        assert!(
            drawn.quads.len() > rows.len(),
            "with a grid under them, not one band per row"
        );

        // ② A patch is three inks, and two of them stand on bands.
        assert_eq!(
            preview::preview_view("fix.diff", preview::preview_ftype("fix.diff"), false),
            preview::PreviewView::Diff
        );
        let patch = "--- a/x\n+++ b/x\n@@ -1,2 +1,2 @@\n context\n-gone\n+here\n";
        let metrics = seats::preview_diff_metrics(scale);
        let margin = (seats::PREVIEW_DIFF_HUNK_MARGIN_LOGICAL_PX * scale).round();
        let mut top = 0.0_f32;
        let diff_rows: Vec<DiffRow> = patch
            .lines()
            .map(|line| {
                let kind = preview::diff_line_kind(line);
                if kind == preview::DiffLineKind::Hunk {
                    top += margin;
                }
                let row = DiffRow {
                    text: preview::expand_tabs(line),
                    kind,
                    top,
                };
                top += metrics.line_height;
                row
            })
            .collect();
        let diff = PreviewDocument::Diff(diff_rows.clone());
        let rows_height = diff_rows
            .last()
            .map_or(0.0, |row| row.top + metrics.line_height);
        let drawn = build_preview_diff_body(
            &seats::preview_mono_geometry(body, metrics, rows_height, 40, advance, [0.0, 0.0]),
            &diff_rows,
            &palette,
        );
        let inks: std::collections::BTreeSet<[u8; 3]> = drawn
            .paragraphs
            .iter()
            .flat_map(|line| line.runs.iter().map(|run| run.color))
            .collect();
        assert!(
            inks.len() >= 3,
            "an added line, a removed one and the context around them are three \
             different inks, saw {inks:?}"
        );
        assert_eq!(
            drawn.quads.len(),
            2,
            "and exactly the added and the removed lines stand on a band"
        );

        // ③ Both are sized by the same question the card asks, and the answer
        //    grows with the file.
        let height = |document: &PreviewDocument, rows_height| {
            preview_document_height(document, body, scale, advance, rows_height, 40)
        };
        let table_height = height(&table, 0.0);
        let diff_height = height(&diff, rows_height);
        assert!(
            table_height > 0.0 && diff_height > 0.0,
            "a document with content is a body with height"
        );
        let taller = PreviewDocument::Table {
            rows: rows.iter().cycle().take(rows.len() * 4).cloned().collect(),
            column_cells,
        };
        assert!(
            height(&taller, 0.0) > table_height,
            "and a longer table is a taller card"
        );
        assert_eq!(
            preview_document_height(&PreviewDocument::Empty, body, scale, advance, 0.0, 0),
            0.0,
            "a file whose head has not landed yet asks for no room at all"
        );
    }

    /// PIN — **the card's bar promises exactly as far as the card's clamp
    /// allows** (user ruling, 2026-08-14: the glance scrolls).
    ///
    /// The wheel over the card goes down `scroll_preview_body`, so the offset it
    /// writes is clamped by `preview_document_max_scroll` — the one authority
    /// every write of a preview offset already goes through. The *bar* is drawn
    /// from `preview_document_height` instead, because a box that sizes itself
    /// to its content asks the other question. Two numbers, two geometries, and
    /// they have to be the same last pixel: a bar that promised further than the
    /// clamp allows is a thumb that stops short of its own track, and one that
    /// promised less is a document with a tail nothing can reach.
    ///
    /// Asked of the three documents whose two answers are computed apart — the
    /// mono body, the patch and the table, each out of its own geometry.
    /// Markdown's pair is the same expression written twice in
    /// `preview_document_height` and `preview_document_max_scroll`, which is
    /// this same guarantee said in a way that cannot drift.
    ///
    /// MUTATIONS that must turn it red:
    /// ① drop the outer padding from `PreviewTableGeometry::document_height`
    ///    (`self.content_height` alone) — the csv's bar is two paddings short of
    ///    its clamp;
    /// ② drop the `padding_y * 2.0` from `preview_mono_geometry`'s
    ///    `content_height` — text and diff both lose their air;
    /// ③ have `file_peek::scroll_bar` measure the overflow against the card's
    ///    *frame* rather than its body — every case goes red by the head and the
    ///    foot together.
    #[test]
    fn the_glance_cards_bar_promises_exactly_as_far_as_its_clamp_allows() {
        let scale = 1.0_f32;
        let advance = 7.0_f32;
        let row = [40.0, 300.0, 240.0, 320.0];
        let window = (1200.0, 800.0);
        let probe = [
            0.0,
            0.0,
            file_peek::body_width(scale),
            file_peek::body_max_height(scale),
        ];

        let agree = |what: &str, document: &PreviewDocument, rows_height: f32, columns: usize| {
            let height =
                preview_document_height(document, probe, scale, advance, rows_height, columns);
            let card = file_peek::PeekContent {
                name: "sample".to_owned(),
                ftype: "text".to_owned(),
                dirty: false,
                body: file_peek::PeekBody::Document(height),
            };
            let layout = file_peek::layout(&card, row, window, 60.0, 24.0, scale);
            let clamp = preview_document_max_scroll(
                document,
                layout.body,
                scale,
                advance,
                rows_height,
                columns,
            )[1];
            match preview_body_bar(
                layout.body,
                preview::ScrollAxis::Vertical,
                [0.0, 0.0],
                height,
                scale,
            ) {
                Some(bar) => {
                    assert!(
                        clamp > 0.0,
                        "{what}: a bar was drawn over a document with nowhere to go"
                    );
                    assert!(
                        (bar.overflow - clamp).abs() < 0.5,
                        "{what}: the bar offers {} and the clamp allows {clamp}",
                        bar.overflow
                    );
                }
                None => assert_eq!(
                    clamp, 0.0,
                    "{what}: no bar drawn, so there had better be nowhere to go"
                ),
            }
        };

        // ① Plain text — the mono body, forty lines in a card that holds a dozen.
        let lines: Vec<String> = (0..40).map(|n| format!("line {n}")).collect();
        let text_metrics = seats::preview_text_metrics(scale);
        agree(
            "text",
            &PreviewDocument::Text {
                wrap: preview_edit::WrapLayout::unwrapped(&lines),
                lines: lines.clone(),
                highlight: highlight::Highlighting::default(),
            },
            text_metrics.line_height * 40.0,
            0,
        );

        // ② A patch — the same mono geometry with the hunk margins in it.
        let patch = "--- a/x\n+++ b/x\n@@ -1,2 +1,2 @@\n context\n-gone\n+here\n".repeat(8);
        let diff_metrics = seats::preview_diff_metrics(scale);
        let margin = (seats::PREVIEW_DIFF_HUNK_MARGIN_LOGICAL_PX * scale).round();
        let mut top = 0.0_f32;
        let diff_rows: Vec<DiffRow> = patch
            .lines()
            .map(|line| {
                let kind = preview::diff_line_kind(line);
                if kind == preview::DiffLineKind::Hunk {
                    top += margin;
                }
                let row = DiffRow {
                    text: preview::expand_tabs(line),
                    kind,
                    top,
                };
                top += diff_metrics.line_height;
                row
            })
            .collect();
        let diff_height = diff_rows
            .last()
            .map_or(0.0, |row| row.top + diff_metrics.line_height);
        agree("diff", &PreviewDocument::Diff(diff_rows), diff_height, 40);

        // ③ A csv — the table geometry, whose padding lives somewhere else
        //    entirely and is the one this most easily drifts on.
        let csv = "name,size\n".to_owned() + &"alpha,10\n".repeat(40);
        let rows = preview::csv_rows(&csv);
        let columns = rows.iter().map(Vec::len).max().unwrap_or(0);
        let column_cells: Vec<usize> = (0..columns)
            .map(|column| {
                rows.iter()
                    .filter_map(|row| row.get(column))
                    .map(|cell| bt_unicode::text_width(cell))
                    .max()
                    .unwrap_or(0)
            })
            .collect();
        agree(
            "table",
            &PreviewDocument::Table { rows, column_cells },
            0.0,
            0,
        );

        // ④ And a short file, which wears no bar and has nowhere to go — the
        //    other half of the same agreement.
        agree(
            "short text",
            &PreviewDocument::Text {
                wrap: preview_edit::WrapLayout::unwrapped(&lines[..2]),
                lines: lines[..2].to_vec(),
                highlight: highlight::Highlighting::default(),
            },
            text_metrics.line_height * 2.0,
            0,
        );
    }

    /// PIN (user ruling, 2026-08-14) — **the pane wears the card's own bar**.
    ///
    /// The glance card got a scroll bar first, because it was the surface people
    /// were visibly trying to read further into. That left the window upside
    /// down: a 300-pixel hover card said how much of its file it was showing,
    /// and the docked pane it opens into — the same document, four times the
    /// size, scrolling under the same wheel — said nothing at all. A page you
    /// can scroll and cannot see the extent of is a page you have to scroll to
    /// find the end of.
    ///
    /// So the three faces are asked the same four questions here, in one loop,
    /// against one function. That is what "同原语" has to mean to be worth
    /// anything: not three implementations that agree today, but one arithmetic
    /// none of them can drift from — the lesson the block's bar already paid for
    /// when its picture and its hit test disagreed.
    ///
    /// MUTATIONS that must turn it red:
    /// ① have `preview_body_bar` answer `None` for a box taller than it is wide
    ///    — which is exactly "a docked pane draws no bar": both pane shapes go
    ///    red and the 300×246 card stays green, which is the upside-down window
    ///    this ruling overturned;
    /// ② hand `preview::scroll_bar` `ScrollAxis::Horizontal` — the rule lands
    ///    along the bottom edge and ① goes red for all three;
    /// ③ read the offset from `scroll[0]` — ③ goes red, the thumb having stopped
    ///    following the wheel.
    #[test]
    fn a_docked_pane_and_a_float_wear_the_same_bar_the_glance_card_does() {
        const SCALE: f32 = 2.0;
        // A tall docked pane, a squat float, and the card — the three surfaces
        // the ruling names, in the three shapes they actually come in.
        let faces = [
            ("seat", [0.0, 80.0, 420.0, 900.0]),
            ("float", [300.0, 120.0, 760.0, 420.0]),
            (
                "card",
                [
                    40.0,
                    300.0,
                    40.0 + file_peek::body_width(SCALE),
                    300.0 + file_peek::body_max_height(SCALE),
                ],
            ),
        ];
        for (what, body) in faces {
            let page = body[3] - body[1];
            let content = page * 4.0;

            // ① Down the right edge of the body, never across it, and never past
            //    the bottom of the box the document is drawn in — the truncation
            //    bar and the foot stand below `body` and are not scrolled over.
            let bar = preview_body_bar(
                body,
                preview::ScrollAxis::Vertical,
                [0.0, 0.0],
                content,
                SCALE,
            )
            .unwrap_or_else(|| panic!("{what}: a document four pages long wears a bar"));
            assert_eq!(bar.axis, preview::ScrollAxis::Vertical, "{what}");
            assert_eq!([bar.track[1], bar.track[3]], [body[1], body[3]], "{what}");
            assert_eq!(bar.track[2], body[2], "{what}: the bar hugs the far edge");
            assert!(
                bar.track[0] > body[0] + (body[2] - body[0]) / 2.0,
                "{what}: a rule down the edge, not a curtain across the body"
            );

            // ② The overflow it offers is the overflow the clamp allows, so the
            //    end of the track and the end of the wheel are one place.
            assert_eq!(bar.overflow, content - page, "{what}");
            assert!(
                bar.thumb[3] - bar.thumb[1] >= preview::BLOCK_SCROLL_MIN_THUMB_LOGICAL_PX * SCALE,
                "{what}: a thumb no hand can see is a thumb no hand can take"
            );

            // ③ The thumb is a picture of the offset: at rest at the head of the
            //    track, at the end of the document at the end of it.
            assert_eq!(bar.thumb[1], body[1], "{what}: at rest, at the top");
            let end = preview_body_bar(
                body,
                preview::ScrollAxis::Vertical,
                [0.0, bar.overflow],
                content,
                SCALE,
            )
            .expect("still overflowing");
            assert!(
                (end.thumb[3] - body[3]).abs() < 0.5,
                "{what}: at the end of the file, at the end of the track"
            );

            // ④ And dragging reads that picture backwards, stopping where the
            //    wheel stops at both ends.
            let held = 5.0_f32;
            let dragged = |y: f32| preview::scroll_dragged_to(&bar, bar.along([body[2], y]), held);
            assert_eq!(dragged(bar.thumb[1] + held), 0.0, "{what}");
            assert_eq!(
                dragged(bar.thumb[1] + held + bar.travel * 9.0),
                bar.overflow,
                "{what}: past the end of the track is the end of the document"
            );

            // ⑤ **The hand's target reaches inward and stops at the edge**
            //    (real-machine finding, 2026-08-14). The two pixels of rule sit
            //    on the surface's own far edge, and everything past that edge
            //    has an owner that is asked first: a divider's seam band, or the
            //    window's resize border, which is answered in `WM_NCHITTEST`
            //    before this window sees a pointer at all. A bar that only
            //    reached five pixels each way was a bar drawn inside somebody
            //    else's band — visible, wheel-accurate, and impossible to take.
            assert!(
                bar.grab[0] <= bar.thumb[0] - preview::BODY_SCROLL_INWARD_HIT_LOGICAL_PX * SCALE,
                "{what}: the target has to clear the divider band and the resize border"
            );
            assert_eq!(
                bar.grab[2], body[2],
                "{what}: and it stops at the edge — the far side belongs to somebody else"
            );

            // ⑥ A document that fits wears nothing at all: a track with no thumb
            //    is a promise of somewhere to go in a pane that has nowhere.
            assert!(
                preview_body_bar(body, preview::ScrollAxis::Vertical, [0.0, 0.0], page, SCALE)
                    .is_none(),
                "{what}: a file that fits its pane draws no bar"
            );
        }
    }

    /// MUTATION: make the fence scanner require a *bare* ```` ``` ```` to close
    /// (`lines[index] == "```"`) and the largest-block assertion goes red, which
    /// is the swallowing hypothesis in its real form.
    #[test]
    fn the_design_document_parses_into_blocks_that_reserve_nothing_extra() {
        let source = include_str!("../../../docs/DESIGN.md");
        let blocks = preview::parse_markdown(source);
        let source_lines = source.lines().count();
        assert!(
            source_lines > 100,
            "the fixture is the real document, not a stub"
        );

        // ① No fence swallows the file. The largest one in this document is a
        //    short shell transcript; a tenth of the file is a generous bound
        //    that a runaway fence blows through by an order of magnitude.
        let biggest_fence = blocks
            .iter()
            .filter_map(|block| match block {
                preview::MarkdownBlock::Code { text, .. } => Some(text.lines().count()),
                _ => None,
            })
            .max()
            .unwrap_or(0);
        assert!(
            biggest_fence * 10 < source_lines,
            "a fence holding {biggest_fence} of {source_lines} lines is a fence \
             that never closed"
        );

        // ② The document really does exercise the blocks the prototype could not
        //    draw, or this fixture proves nothing about them.
        let count = |kind: fn(&preview::MarkdownBlock) -> bool| {
            blocks.iter().filter(|block| kind(block)).count()
        };
        assert!(
            count(|b| matches!(b, preview::MarkdownBlock::Table { .. })) > 0,
            "DESIGN.md has tables, and they must arrive as tables"
        );
        assert!(
            count(|b| matches!(b, preview::MarkdownBlock::Quote(_))) > 0,
            "and quotes"
        );
        assert!(
            count(|b| matches!(
                b,
                preview::MarkdownBlock::List {
                    ordered: Some(_),
                    ..
                }
            )) > 0,
            "and numbered lists"
        );

        // ③ Every table has a heading row and at least one body row — a table
        //    of one row is a separator that was read as content.
        for block in &blocks {
            if let preview::MarkdownBlock::Table { rows } = block {
                assert!(
                    rows.len() >= 2,
                    "a table needs its heading and something under it: {rows:?}"
                );
                assert!(
                    rows.iter().all(|row| !row.is_empty()),
                    "and no row of no cells"
                );
            }
        }
    }

    /// PIN (user rulings, 2026-08-13) — **which markdown blocks insist on a
    /// width, and which have no opinion.**
    ///
    /// Three rulings, one arithmetic, and the arithmetic is the whole of the
    /// horizontal scroll a rendered document gets:
    ///
    /// ① a **code fence does not reflow** — code that wraps lies about its own
    ///    indentation, the same argument that keeps a `.diff` unwrapped — so it
    ///    answers its longest line and the pane scrolls to it;
    /// ② a **table is as wide as its own columns**, and the pane scrolls to it
    ///    rather than compressing them: the first draft divided the pane's width
    ///    among the columns and wrapped inside the cells, and that policy was
    ///    overruled before it shipped;
    /// ③ a **paragraph never insists**, however long the token inside it. A
    ///    180-character unbreakable run is broken mid-token by the shaper rather
    ///    than allowed to push a horizontal axis onto a page of prose — which is
    ///    what "soft wrap with an anywhere break" means and the reason a wall of
    ///    text still reads in a narrow pane.
    ///
    /// Asserted on `stress.md`, the fixture built to carry all three at once.
    ///
    /// MUTATION ①: answer `0.0` for the fence's width and the fence assertion
    /// goes red — the long line is drawn and can never be reached.
    /// MUTATION ②: go back to `width`-proportional columns and the table's own
    /// width stops exceeding the pane, so the table assertion goes red.
    /// MUTATION ③: give `Paragraph` a `width` and the prose assertion goes red,
    /// which is a page of text growing a horizontal scrollbar.
    #[test]
    fn only_the_blocks_that_refuse_to_reflow_ask_for_a_horizontal_scroll() {
        let source = include_str!("../../../test-assets/preview-samples/stress.md");
        let blocks = preview::parse_markdown(source);
        let fences = blocks
            .iter()
            .filter(|block| matches!(block, preview::MarkdownBlock::Code { .. }))
            .count();
        let tables: Vec<&preview::MarkdownBlock> = blocks
            .iter()
            .filter(|block| matches!(block, preview::MarkdownBlock::Table { .. }))
            .collect();
        assert!(fences >= 1, "the fixture carries a fence");
        assert_eq!(tables.len(), 2, "and a wide table and a narrow one");
        if let preview::MarkdownBlock::Table { rows } = tables[0] {
            assert!(
                rows[0].len() >= 8,
                "the wide table is at least eight across"
            );
        }
        // The 180-character token really is one token, or ③ proves nothing.
        assert!(
            source
                .split_whitespace()
                .any(|token| token.chars().count() >= 180),
            "the fixture carries an unbreakable run long enough to matter"
        );

        // **The two insisting blocks, measured through the real arithmetic with
        // a stand-in shaper**: eight pixels a character, which is a monospace
        // grid and exactly what the assertions below can therefore predict.
        let metrics_at_1 = seats::preview_markdown_metrics(1.0);
        let cell_px = 8.0_f32;
        let fence_text = blocks
            .iter()
            .find_map(|block| match block {
                preview::MarkdownBlock::Code { text, .. } => Some(text.clone()),
                _ => None,
            })
            .expect("the fixture carries a fence");
        let longest = fence_text
            .lines()
            .map(|line| line.chars().count())
            .max()
            .unwrap_or(0);
        assert!(longest >= 250, "the fence's longest line is a stress case");
        let fence_width = markdown_fence_width(&fence_text, metrics_at_1, |runs| {
            runs.iter()
                .map(|run| run.text.chars().count())
                .sum::<usize>() as f32
                * cell_px
        });
        assert_eq!(
            fence_width,
            longest as f32 * cell_px
                + (metrics_at_1.code_border + metrics_at_1.code_padding_x) * 2.0,
            "① the fence asks for its longest line and its own chrome"
        );

        let preview::MarkdownBlock::Table { rows } = tables[0] else {
            unreachable!("filtered above")
        };
        let columns = markdown_table_columns(rows, metrics_at_1, |cell, _| {
            cell.iter()
                .map(|span| span.text.chars().count())
                .sum::<usize>() as f32
                * cell_px
        });
        assert_eq!(columns.len(), rows[0].len(), "one width per column");
        let chrome = metrics_at_1.table_border + metrics_at_1.table_padding_x * 2.0;
        for (index, width) in columns.iter().enumerate() {
            let widest = rows
                .iter()
                .filter_map(|row| row.get(index))
                .map(|cell| cell.iter().map(|s| s.text.chars().count()).sum::<usize>())
                .max()
                .unwrap_or(0) as f32
                * cell_px;
            assert_eq!(
                *width,
                chrome + widest.max(metrics_at_1.table_min_column),
                "② column {index} is its own widest cell, never a share of the pane"
            );
        }
        assert!(
            columns.iter().sum::<f32>() > 900.0,
            "and the table is genuinely wider than a pane, or this proves nothing"
        );

        // A layout is what the runtime would have measured, with the ruling's
        // shape and no renderer: the fence and the table insist, prose does not.
        let metrics = seats::preview_markdown_metrics(1.0);
        let pane = [0.0, 0.0, 300.0, 200.0];
        let prose_only = vec![
            MarkdownBlockLayout::solid(metrics.line_height * 12.0),
            MarkdownBlockLayout::solid(metrics.line_height * 3.0),
        ];
        let document = PreviewDocument::Markdown {
            intrinsic: Vec::new(),
            blocks: Vec::new(),
            layout: prose_only,
        };
        let max = preview_document_max_scroll(&document, pane, 1.0, 8.0, 0.0, 0);
        assert_eq!(
            max[0], 0.0,
            "③ a page of prose has no horizontal axis, whatever it is made of"
        );

        // **And neither does a page holding a block that refuses to reflow**
        // (user ruling, 2026-08-13, overturning the same day's earlier reading).
        // The fence and the table still insist on their widths — the two
        // assertions above are about exactly that — but the width is spent
        // *inside the block*, not by sliding the whole page under the pane. The
        // page's own axis is zero either way, and this is the assertion that
        // says the ruling changed rather than the measurement.
        let wide = 900.0_f32;
        let with_a_fence = PreviewDocument::Markdown {
            intrinsic: Vec::new(),
            blocks: Vec::new(),
            layout: vec![
                MarkdownBlockLayout::solid(metrics.line_height),
                MarkdownBlockLayout {
                    width: wide,
                    ..MarkdownBlockLayout::solid(metrics.line_height * 4.0)
                },
            ],
        };
        let max = preview_document_max_scroll(&with_a_fence, pane, 1.0, 8.0, 0.0, 0);
        assert_eq!(
            max[0], 0.0,
            "①/② a wide block scrolls inside itself; the page it stands on does not move"
        );
    }

    /// PIN (user ruling, 2026-08-13) — **a wide block is its own scrolling
    /// region: it clamps at both ends, it takes the offset, and the prose beside
    /// it does not move.**
    ///
    /// The third assertion is the one the ruling is really about. The reported
    /// symptom was two defects wearing one shape: a table that could not be
    /// scrolled at all (the page's axis had been clamped to zero while the
    /// table's width was still in the extent), and — before that — prose sliding
    /// out of the pane to reach it.
    ///
    /// MUTATIONS:
    /// ① drop the `clamp(0.0, overflow)` in `build_preview_markdown_body` — the
    ///    first assertion goes red and a table can be pushed past its own end;
    /// ② apply the offset to `left` for every block rather than the wide one —
    ///    the third assertion goes red, which is exactly the page-slide the
    ///    ruling overturned;
    /// ③ stop pushing the block into `blocks` — the second assertion goes red and
    ///    the table prints over the paragraph beside it, unclipped.
    #[test]
    fn a_wide_markdown_block_scrolls_inside_itself_and_the_prose_stays_put() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let body = [0.0, 0.0, 300.0, 400.0];
        let page = body[2] - body[0] - metrics.padding_x * 2.0;
        let wide = page + 400.0;
        let blocks = vec![
            preview::MarkdownBlock::Paragraph(vec![preview::Span::plain("prose")]),
            preview::MarkdownBlock::Code {
                lang: None,
                text: "a very long line".to_owned(),
            },
        ];
        let layout = vec![
            MarkdownBlockLayout::solid(metrics.line_height),
            MarkdownBlockLayout {
                width: wide,
                top: metrics.line_height + metrics.paragraph_gap,
                ..MarkdownBlockLayout::solid(metrics.line_height * 3.0)
            },
        ];
        let overflow = wide - page;
        let prose_left = |offsets: &[f32]| {
            let built = markdown_body(
                body,
                metrics,
                [0.0, 0.0],
                rested_bars(offsets),
                (&blocks, &layout),
                &palette,
            );
            built
                .paragraphs
                .iter()
                .find(|paragraph| paragraph.runs.iter().any(|run| run.text == "prose"))
                .expect("the prose is drawn on the page itself")
                .rect[0]
        };
        let fence_left = |offsets: &[f32]| {
            let built = markdown_body(
                body,
                metrics,
                [0.0, 0.0],
                rested_bars(offsets),
                (&blocks, &layout),
                &palette,
            );
            let block = built
                .blocks
                .first()
                .expect("a block wider than its page scrolls inside itself")
                .clone();
            // The fence's own ground, which is the second quad it draws.
            (block.quads[0].rect[0], block.clip)
        };

        // ① Clamped at both ends, in the block's own units.
        let (at_rest, clip) = fence_left(&[0.0, 0.0]);
        let (at_end, _) = fence_left(&[0.0, overflow]);
        let (past_end, _) = fence_left(&[0.0, overflow * 10.0]);
        let (before_start, _) = fence_left(&[0.0, -50.0]);
        assert_eq!(at_rest - at_end, overflow, "the block travels its overflow");
        assert_eq!(past_end, at_end, "and stops at its own end");
        assert_eq!(before_start, at_rest, "and at its own start");

        // ② The region is cropped to the block's rectangle, so what it scrolls
        //    cannot print over the page.
        assert_eq!(clip[0], body[0] + metrics.padding_x);
        assert_eq!(clip[2], clip[0] + page);

        // ②(b) **The indicator belongs to the block it was pushed with.** A page
        //    scrolled past its first wide block still has one region and one
        //    indicator, and the pair must be the same pair — the version that
        //    re-derived the list and zipped it drew every indicator one block out
        //    as soon as anything above had scrolled off the top.
        let tall = vec![
            MarkdownBlockLayout::solid(1000.0),
            MarkdownBlockLayout {
                width: wide,
                top: 1000.0,
                ..MarkdownBlockLayout::solid(metrics.line_height * 3.0)
            },
        ];
        let built = markdown_body(
            body,
            metrics,
            [0.0, 1000.0],
            rested_bars(&[0.0, overflow]),
            (&blocks, &tall),
            &palette,
        );
        let block = built.blocks.first().expect("the wide block is on screen");
        let thumb = block.quads.last().expect("an indicator has a thumb");
        assert!(
            thumb.rect[0] > block.clip[0],
            "the thumb of a block scrolled to its end sits away from the left edge"
        );

        // ③ **The prose does not move**, at any offset the block can hold.
        assert_eq!(prose_left(&[0.0, 0.0]), prose_left(&[0.0, overflow]));
    }

    /// PIN (user report, 2026-08-12) — **what looks like a scrollbar is one**.
    ///
    /// The report is that the bar under a wide table could not be dragged. It
    /// was an *indicator*: a proportional thumb on a track, drawn in exactly the
    /// shape every application on the desk uses for a control, and wired to
    /// nothing. This asks the three questions a scrollbar has to answer — can a
    /// hand find it, does dragging it move the content in proportion, and does
    /// it stop where the wheel stops — and it asks the first of them against the
    /// rectangle the *painter* produced, because a thumb hit-tested anywhere
    /// other than where it was drawn is the same defect wearing a fix.
    ///
    /// MUTATIONS that must turn it red:
    /// ① have `scroll_dragged_to` return the offset it was given instead
    ///    of reading the pointer — the drag writes nothing, which is the bug;
    /// ② drop the `grab` widening in `scroll_bar` — the second question
    ///    goes red and two drawn pixels are the whole target again;
    /// ③ paint the thumb from any arithmetic other than `scroll_bar` —
    ///    the first assertion goes red.
    #[test]
    fn the_bar_under_a_wide_block_is_a_thumb_a_hand_can_take_and_drag() {
        const SCALE: f32 = 1.0;
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(SCALE);
        let body = [0.0, 0.0, 300.0, 400.0];
        let page = body[2] - body[0] - metrics.padding_x * 2.0;
        let wide = page + 400.0;
        let blocks = [
            preview::MarkdownBlock::Paragraph(vec![preview::Span::plain("prose")]),
            preview::MarkdownBlock::Code {
                lang: None,
                text: "a very long line".to_owned(),
            },
        ];
        let layout = [
            MarkdownBlockLayout::solid(metrics.line_height),
            MarkdownBlockLayout {
                width: wide,
                top: metrics.line_height + metrics.paragraph_gap,
                ..MarkdownBlockLayout::solid(metrics.line_height * 3.0)
            },
        ];
        let overflow = wide - page;
        let offsets = [0.0, 0.0];
        let document = (&blocks[..], &layout[..]);
        let bar_at = |at: [f32; 2]| {
            preview_block_bar_at(body, metrics, [0.0, 0.0], &offsets, document, SCALE, at)
        };

        // ① The thumb a hand finds is the thumb the painter drew.
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&offsets),
            document,
            &palette,
        );
        let drawn = built
            .blocks
            .first()
            .expect("a block wider than its page scrolls inside itself")
            .quads
            .last()
            .expect("and wears a thumb")
            .rect;
        let on_thumb = [drawn[0] + 2.0, (drawn[1] + drawn[3]) / 2.0];
        let (index, bar) = bar_at(on_thumb).expect("the pointer on the drawn thumb finds one");
        assert_eq!(index, 1, "and it belongs to the wide block");
        assert_eq!(bar.thumb, drawn, "hit and paint are one geometry");

        // ② The band is wider than the rule — two drawn pixels are not a target.
        let above = [on_thumb[0], bar.thumb[1] - 2.0];
        assert!(
            bar.thumb[1] - 2.0 < bar.thumb[1] && bar_at(above).is_some(),
            "a hand landing just above the rule still has it"
        );
        assert!(
            bar_at([on_thumb[0], bar.grab[1] - 4.0]).is_none(),
            "and the tolerance is a tolerance, not the whole block"
        );

        // ③ Dragging maps the track onto the overflow, linearly, and stops
        //    where the wheel stops.
        let grab = on_thumb[0] - bar.thumb[0];
        let dragged_to = |x: f32| preview::scroll_dragged_to(&bar, x, grab);
        assert_eq!(dragged_to(on_thumb[0]), 0.0, "at rest it has not moved");
        assert!(
            (dragged_to(on_thumb[0] + bar.travel / 2.0) - overflow / 2.0).abs() < 0.5,
            "half the track is half the overflow"
        );
        assert!(
            (dragged_to(on_thumb[0] + bar.travel) - overflow).abs() < 0.5,
            "the whole track is the whole overflow"
        );
        assert_eq!(
            dragged_to(on_thumb[0] + bar.travel * 4.0),
            overflow,
            "and it stops at the block's own end"
        );
        assert_eq!(
            dragged_to(on_thumb[0] - 400.0),
            0.0,
            "and at its own start — the wheel's two clamps, exactly"
        );
    }

    /// The document hands out every link it drew, addressed by the run it drew
    /// it as (user ruling, 2026-08-13).
    ///
    /// The address is the whole of this: a link is a *run inside a paragraph*,
    /// and where that run landed is a question only the shaper answers
    /// ([`bt_render::Renderer::measure_preview_run_boxes`]). What the painter
    /// owes is the subscript, and the one that is easy to get wrong is a list
    /// item's — its bullet rides in front of the text as a run of its own, so
    /// the first span of an item is the paragraph's *second* run. Off by one
    /// there and the pointer underlines the bullet and opens nothing.
    ///
    /// MUTATIONS: pass `0` as a list item's first run and the second assertion
    /// goes red; note the sites after pushing the paragraph rather than before,
    /// and every subscript is one too far.
    #[test]
    fn a_document_hands_out_every_link_it_drew_with_the_run_that_drew_it() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let body = [0.0, 0.0, 400.0, 400.0];
        let blocks = [
            preview::MarkdownBlock::Paragraph(vec![
                preview::Span::plain("see "),
                preview::Span::link("the design", "../../docs/DESIGN.md"),
                preview::Span::plain(" first"),
            ]),
            preview::MarkdownBlock::List {
                ordered: None,
                items: vec![vec![preview::Span::link("a note", "notes.md")]],
            },
        ];
        let layout = [
            MarkdownBlockLayout::solid(metrics.line_height),
            MarkdownBlockLayout {
                top: metrics.line_height + metrics.paragraph_gap,
                ..MarkdownBlockLayout::rows(vec![metrics.line_height], 0.0)
            },
        ];
        let rendered = build_preview_markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (&blocks, &[], &layout),
            &palette,
        );
        let sites: Vec<_> = rendered
            .links
            .iter()
            .map(|site| (site.block, site.paragraph, site.run, site.target.as_str()))
            .collect();
        assert_eq!(
            sites,
            vec![
                (None, 0, 1, "../../docs/DESIGN.md"),
                (None, 1, 1, "notes.md"),
            ],
            "the prose link is its paragraph's second run, and the item's link \
             is the item's second run because the bullet is its first"
        );
        // And the subscripts address the runs that were actually built.
        for (block, paragraph, run, target) in sites {
            assert!(block.is_none());
            let drawn = &rendered.body.paragraphs[paragraph].runs[run];
            assert_eq!(drawn.color, palette.accent, "a link is set in the accent");
            assert!(
                !drawn.text.contains(target),
                "and never prints where it points"
            );
        }
    }

    /// PIN (user report, 2026-08-13) — **a block is built at its own full width
    /// and cropped when it is drawn.**
    ///
    /// The report: drag a code fence's thumb to the right and the fence goes
    /// blank but for a sliver of glyphs against its left edge. The cause was
    /// that a scrolling block's inner frame was **one page wide and slid left**
    /// (`right - offset`), so every rectangle inside it was laid out in a
    /// window that walked off its own clip. A fence is one paragraph spanning
    /// the whole line, so its single box left the clip bodily and
    /// `shape_preview_body`'s `crop_to` — correctly — drew nothing of it. A
    /// table survived the same offset only because [`push_markdown_table`] lays
    /// its cells out from the block's *origin* and never reads the frame's
    /// right edge at all: a reprieve its structure happened to grant, not a
    /// rule, which is why both are asserted here.
    ///
    /// The frame is now the content's width placed at the offset, and the
    /// cropping is where cropping belongs — at the draw, in `crop_to`, which
    /// stays exactly as it is. That gate is for inverted and `NaN` boxes; a
    /// block scrolled to its own end is neither, and it was never the thing
    /// `crop_to` was put there to stop.
    ///
    /// MUTATION: put the crop back at build time — restore `right - offset` as
    /// the frame's right edge — and ① and ② both go red.
    #[test]
    fn a_scrolled_block_keeps_its_whole_width_and_is_cropped_only_when_drawn() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let body = [0.0, 0.0, 300.0, 400.0];
        let page = body[2] - body[0] - metrics.padding_x * 2.0;
        let wide = page + 400.0;
        let overflow = wide - page;
        let line = "a fence line far wider than the page it is standing on";
        let cells = |text: &str| {
            vec![
                vec![preview::Span::plain("head")],
                vec![preview::Span::plain(text)],
            ]
        };
        let blocks = [
            preview::MarkdownBlock::Code {
                lang: None,
                text: line.to_owned(),
            },
            preview::MarkdownBlock::Table {
                rows: vec![cells("first"), cells("last")],
            },
        ];
        let fence_height =
            metrics.code_border * 2.0 + metrics.code_padding_y * 2.0 + metrics.line_height;
        let layout = [
            MarkdownBlockLayout {
                width: wide,
                ..MarkdownBlockLayout::solid(fence_height)
            },
            MarkdownBlockLayout {
                width: wide,
                top: fence_height + metrics.paragraph_gap,
                columns: vec![80.0, wide - 80.0],
                ..MarkdownBlockLayout::rows(
                    vec![metrics.line_height, metrics.line_height],
                    metrics.table_border,
                )
            },
        ];
        let render = |offsets: &[f32]| {
            markdown_body(
                body,
                metrics,
                [0.0, 0.0],
                rested_bars(offsets),
                (&blocks, &layout),
                &palette,
            )
        };
        let fence_line = |built: &bt_render::PreviewBody| {
            built.blocks[0]
                .paragraphs
                .iter()
                .find(|paragraph| {
                    paragraph
                        .runs
                        .iter()
                        .any(|run| run.text.contains("fence line"))
                })
                .expect("a fence draws its line")
                .clone()
        };
        // Both blocks driven to the far end of their own travel — the gesture
        // the report is about — against the same document at rest.
        let at_rest = render(&[0.0, 0.0]);
        let built = render(&[overflow, overflow]);
        let region = |index: usize| {
            built
                .blocks
                .get(index)
                .unwrap_or_else(|| panic!("block {index} is wide and scrolls inside itself"))
        };

        // ① The fence's line is still there, whole, and covering the window.
        let fence = region(0);
        let drawn = fence_line(&built);
        assert_eq!(
            drawn
                .runs
                .iter()
                .map(|run| run.text.as_str())
                .collect::<String>(),
            line,
            "and it is the whole line — the text is never cut to what fits"
        );
        let visible = bt_render::crop_to(drawn.rect, fence.clip)
            .expect("its box still meets the block's own rectangle");
        assert_eq!(
            [visible[0], visible[2]],
            [fence.clip[0], fence.clip[2]],
            "covering the window edge to edge, rather than surviving as a sliver"
        );
        // And what stands at the window's left edge is the far end of the line:
        // the box has travelled its whole overflow, and only translated —
        // nothing about it narrowed on the way.
        let resting = fence_line(&at_rest);
        assert_eq!(
            resting.rect[0] - drawn.rect[0],
            overflow,
            "the line has travelled its whole overflow"
        );
        assert_eq!(
            drawn.rect[2] - drawn.rect[0],
            resting.rect[2] - resting.rect[0],
            "and it is the same box that set out — a translation, not a squeeze"
        );
        assert!(
            drawn.rect[0] < fence.clip[0] && drawn.rect[2] >= fence.clip[2],
            "so the window is looking into the middle of it, with the tail \
             still reaching the far edge"
        );

        // ② The table, at the same offset, by the same rule — it looked right
        //    before only by the accident of being made of small boxes.
        let table = region(1);
        let last = table
            .paragraphs
            .iter()
            .find(|paragraph| paragraph.runs.iter().any(|run| run.text == "last"))
            .expect("the last row's wide cell is still drawn");
        assert!(
            bt_render::crop_to(last.rect, table.clip).is_some(),
            "and it stands inside the window a scroll to the end opened on it"
        );

        // ③ At rest, nothing has been glued open: the window starts at the
        //    line's own beginning.
        assert!(
            resting.rect[0] >= at_rest.blocks[0].clip[0],
            "an unscrolled fence begins inside its own window"
        );
    }

    /// PIN (user report, 2026-08-13 — **the escape**) — nothing a preview body
    /// produces may be drawn outside the preview's own rectangle.
    ///
    /// The report: opening a document holding a 250-character fence line and a
    /// table of very long cells put grey bands and stray words *across the whole
    /// window* — over the file tree, over the terminal. A preview that draws on
    /// its neighbours is a different class of defect from a preview that draws
    /// its own content badly, and it has exactly two causes, both asserted here:
    ///
    /// ① a rectangle that the renderer's crop does not actually bound —
    ///    `PreviewBody::clip` is the one gate, and every quad and every
    ///    paragraph has to go through it;
    /// ② a rectangle that is **inverted or non-finite**, which no crop can save:
    ///    the pass runs in whole-surface coordinates with no scissor, so
    ///    `right < left` is a box the rasteriser fills across the surface and a
    ///    `NaN` is a box with no edges. `bt_render::crop_to` is the gate for
    ///    that one, and this test's job is to prove the layout never asks it to
    ///    fire — a rectangle silently dropped is content silently missing.
    ///
    /// Run against `stress.md`, the document the report was made with, at a pane
    /// deliberately far narrower than its widest block, and at every horizontal
    /// scroll offset the body can reach — because the offset is precisely what
    /// moves a wide block's rectangle to a negative x.
    ///
    /// MUTATION: drop the `.max(body.clip[..])` crop in
    /// `bt_render::shape_preview_body`, or return the rect unclipped from
    /// `crop_to`, and the containment assertion goes red — which is the reported
    /// screenshot, in one number.
    #[test]
    fn nothing_a_preview_body_produces_is_drawn_outside_the_preview() {
        let palette = bt_render::chrome_palette();
        let source = include_str!("../../../test-assets/preview-samples/stress.md");
        let blocks = preview::parse_markdown(source);
        // A narrow pane, so every wide block overruns it and the crop is the only
        // thing standing between the document and the panes beside it.
        let body = [480.0, 120.0, 800.0, 620.0];
        let metrics = seats::preview_markdown_metrics(1.0);

        // A stand-in measurer, eight pixels a character — the same monospace
        // grid the ruling test uses, so the widths here are predictable and the
        // wide blocks are genuinely wider than the pane.
        let cell = 8.0_f32;
        let mut layout = Vec::with_capacity(blocks.len());
        let mut top = 0.0_f32;
        let mut previous_bottom = 0.0_f32;
        let mut previous_block: Option<&preview::MarkdownBlock> = None;
        for block in &blocks {
            let mut measured = match block {
                preview::MarkdownBlock::Code { text, .. } => MarkdownBlockLayout {
                    width: markdown_fence_width(text, metrics, |runs| {
                        runs.iter()
                            .map(|run| run.text.chars().count())
                            .sum::<usize>() as f32
                            * cell
                    }),
                    ..MarkdownBlockLayout::solid(
                        metrics.code_border * 2.0
                            + metrics.code_padding_y * 2.0
                            + metrics.line_height * text.lines().count().max(1) as f32,
                    )
                },
                preview::MarkdownBlock::Table { rows } => {
                    let columns = markdown_table_columns(rows, metrics, |cell_spans, _| {
                        cell_spans
                            .iter()
                            .map(|span| span.text.chars().count())
                            .sum::<usize>() as f32
                            * cell
                    });
                    let width = columns.iter().sum::<f32>() + metrics.table_border;
                    let heights = vec![
                        metrics.line_height
                            + metrics.table_border
                            + metrics.table_padding_y * 2.0;
                        rows.len()
                    ];
                    MarkdownBlockLayout {
                        columns,
                        width,
                        ..MarkdownBlockLayout::rows(heights, metrics.table_border)
                    }
                }
                preview::MarkdownBlock::List { items, .. } => {
                    MarkdownBlockLayout::rows(vec![metrics.line_height; items.len()], 0.0)
                }
                preview::MarkdownBlock::Quote(lines) => MarkdownBlockLayout::rows(
                    vec![metrics.line_height; lines.len()],
                    metrics.quote_padding_y * 2.0,
                ),
                preview::MarkdownBlock::Rule => MarkdownBlockLayout::solid(metrics.rule_thickness),
                _ => MarkdownBlockLayout::solid(metrics.line_height * 2.0),
            };
            // Updated 2026-08-16 with the metrics: margins are a top and a
            // bottom now, and the block before this one is what answers the two
            // `:first-child` rules. See `preview::markdown_block_margins`.
            let (margin_top, margin_bottom) =
                preview::markdown_block_margins(block, previous_block, metrics);
            top += previous_bottom.max(margin_top);
            measured.top = top;
            top += measured.height;
            previous_bottom = margin_bottom;
            previous_block = Some(block);
            layout.push(measured);
        }
        let widest = layout.iter().map(|b| b.width).fold(0.0_f32, f32::max);
        assert!(
            widest > (body[2] - body[0]) * 2.0,
            "the fixture must overrun the pane by a wide margin, or this proves \
             nothing: {widest} against {}",
            body[2] - body[0]
        );

        let document = PreviewDocument::Markdown {
            intrinsic: Vec::new(),
            blocks: blocks.clone(),
            layout: layout.clone(),
        };
        let max = preview_document_max_scroll(&document, body, 1.0, cell, 0.0, 0);
        assert_eq!(max[0], 0.0, "the page has no horizontal axis of its own");
        assert!(max[1] > 0.0, "and it certainly overruns downwards");
        // The horizontal offset that could push a rectangle negative now belongs
        // to the *block*, so it is the axis this sweeps — every block gets the
        // page's own width as an offset, which is far past any of their ends and
        // is exactly the arithmetic the crop has to survive.
        let overrun = widest;
        for x in [0.0, overrun / 2.0, overrun] {
            let offsets = vec![x; layout.len()];
            for y in [0.0, max[1] / 2.0, max[1]] {
                let built = markdown_body(
                    body,
                    metrics,
                    [0.0, y],
                    rested_bars(&offsets),
                    (&blocks, &layout),
                    &palette,
                );
                assert_eq!(built.clip, body, "the body's one gate is the pane's box");
                let finite = |rect: [f32; 4]| rect.iter().all(|value| value.is_finite());
                for quad in &built.quads {
                    assert!(
                        finite(quad.rect),
                        "a non-finite fill at scroll {x},{y}: {:?}",
                        quad.rect
                    );
                    assert!(
                        quad.rect[2] >= quad.rect[0] && quad.rect[3] >= quad.rect[1],
                        "an inverted fill at scroll {x},{y}: {:?} — the rasteriser \
                         fills one of these across the whole surface",
                        quad.rect
                    );
                    assert!(
                        bt_render::crop_to(quad.rect, built.clip)
                            .is_none_or(|drawn| inside(drawn, built.clip)),
                        "a fill that survives the crop outside the pane: {:?}",
                        quad.rect
                    );
                }
                for paragraph in &built.paragraphs {
                    assert!(
                        finite(paragraph.rect),
                        "a non-finite paragraph at scroll {x},{y}: {:?}",
                        paragraph.rect
                    );
                    assert!(
                        paragraph.rect[2] >= paragraph.rect[0]
                            && paragraph.rect[3] >= paragraph.rect[1],
                        "an inverted paragraph at scroll {x},{y}: {:?}",
                        paragraph.rect
                    );
                    assert!(
                        bt_render::crop_to(paragraph.rect, built.clip)
                            .is_none_or(|drawn| inside(drawn, built.clip)),
                        "a paragraph that survives the crop outside the pane: {:?}",
                        paragraph.rect
                    );
                }
                // And the same three questions of every scrolling block, whose
                // rectangles are the ones the offset actually moves. Their gate
                // is the block's clip intersected with the body's, which is what
                // `bt_render` crops them to.
                for block in &built.blocks {
                    assert!(finite(block.clip));
                    assert!(block.clip[2] >= block.clip[0] && block.clip[3] >= block.clip[1]);
                    let window = bt_render::crop_to(block.clip, built.clip);
                    for quad in &block.quads {
                        assert!(
                            finite(quad.rect)
                                && quad.rect[2] >= quad.rect[0]
                                && quad.rect[3] >= quad.rect[1],
                            "a block fill at offset {x}: {:?}",
                            quad.rect
                        );
                        assert!(
                            window
                                .and_then(|window| bt_render::crop_to(quad.rect, window))
                                .is_none_or(|drawn| inside(drawn, built.clip)),
                            "a block fill that survives the crop outside the pane: {:?}",
                            quad.rect
                        );
                    }
                    for paragraph in &block.paragraphs {
                        assert!(
                            finite(paragraph.rect)
                                && paragraph.rect[2] >= paragraph.rect[0]
                                && paragraph.rect[3] >= paragraph.rect[1],
                            "a block paragraph at offset {x}: {:?}",
                            paragraph.rect
                        );
                        assert!(
                            window
                                .and_then(|window| bt_render::crop_to(paragraph.rect, window))
                                .is_none_or(|drawn| inside(drawn, built.clip)),
                            "a block paragraph that survives the crop outside the pane: {:?}",
                            paragraph.rect
                        );
                    }
                }
            }
        }
    }

    /// PIN (user report, 2026-08-13: "拖窗口边时 md 预览明显卡") — **a resize
    /// re-flows and does not re-measure.**
    ///
    /// Asserted by counting the shaper's calls, which is the honest unit: the
    /// measurement *is* the cost, and a wall clock would be measuring this
    /// machine. Against `docs/UI-UX.md` — the document the report was made with —
    /// at every width a drag passes through.
    ///
    /// The two halves the fix rests on:
    ///
    /// ① the parse key does not contain the width, so a resize does not re-parse
    ///    the file at all;
    /// ② the width-independent measurements — a table's columns, a fence's
    ///    longest line — are not asked again, so the per-width pass touches only
    ///    the blocks that genuinely reflow. On this document that is the
    ///    difference between thousands of shaping calls per pixel of drag and
    ///    hundreds.
    ///
    /// MUTATIONS:
    /// ① put `body_width_px` back into `PreviewParseKey` — the first assertion
    ///    goes red, and the whole pipeline runs per pixel again;
    /// ② have the `Table`/`Code` arms of `measure_markdown_block` re-derive their
    ///    widths instead of reading the intrinsic — the second assertion goes
    ///    red, and it is the one that dominates the profile.
    #[test]
    fn a_resize_reflows_the_markdown_without_re_measuring_it() {
        let source = include_str!("../../../docs/UI-UX.md");
        let blocks = preview::parse_markdown(source);
        let metrics = seats::preview_markdown_metrics(1.0);
        let cell = 8.0_f32;

        // ① The parse survives every width; only the layout key moves.
        let mut buffer = preview::PreviewBuffer::new(
            preview::PreviewSource::file(r"C:\w\UI-UX.md"),
            "UI-UX.md".to_owned(),
        );
        buffer.accept(preview::HeadOutcome::Read {
            text: source.to_owned(),
            truncated: false,
            mtime: None,
        });
        let wide = preview_document_key(&buffer, false, 1200.0, 1.0);
        let narrow = preview_document_key(&buffer, false, 400.0, 1.0);
        assert_ne!(wide, narrow, "a width change is still a layout change");
        assert_eq!(
            wide.parse, narrow.parse,
            "① but not a parse change: the width is not in the parse key"
        );
        // And an edit is, so the cache cannot go stale.
        buffer.edit_content(|content| {
            content.insert(0, 'x');
            true
        });
        assert_ne!(
            preview_document_key(&buffer, false, 1200.0, 1.0).parse,
            wide.parse,
            "an edit re-parses"
        );

        // ② The intrinsics are measured once; the per-width pass never asks about
        //    a table cell or a fence line again.
        let intrinsic_calls = std::cell::Cell::new(0usize);
        let intrinsic: Vec<MarkdownBlockIntrinsic> = blocks
            .iter()
            .map(|block| match block {
                preview::MarkdownBlock::Table { rows } => {
                    let columns = markdown_table_columns(rows, metrics, |cell_spans, _| {
                        intrinsic_calls.set(intrinsic_calls.get() + 1);
                        cell_spans
                            .iter()
                            .map(|span| span.text.chars().count())
                            .sum::<usize>() as f32
                            * cell
                    });
                    MarkdownBlockIntrinsic {
                        width: columns.iter().sum::<f32>() + metrics.table_border,
                        columns,
                        rows: rows.len(),
                        ..MarkdownBlockIntrinsic::default()
                    }
                }
                preview::MarkdownBlock::Code { text, .. } => MarkdownBlockIntrinsic {
                    width: markdown_fence_width(text, metrics, |runs| {
                        intrinsic_calls.set(intrinsic_calls.get() + 1);
                        runs.iter()
                            .map(|run| run.text.chars().count())
                            .sum::<usize>() as f32
                            * cell
                    }),
                    rows: text.lines().count().max(1),
                    ..MarkdownBlockIntrinsic::default()
                },
                _ => MarkdownBlockIntrinsic::default(),
            })
            .collect();
        assert!(
            intrinsic_calls.get() > 100,
            "the fixture's tables and fences really are a measurable share              ({} shaping calls), or this proves nothing",
            intrinsic_calls.get()
        );

        let reflow_calls = std::cell::Cell::new(0usize);
        let mut measure = |runs: &[bt_render::PreviewRun], width: f32, _: f32, line: f32| {
            reflow_calls.set(reflow_calls.get() + 1);
            let columns = runs
                .iter()
                .map(|run| run.text.chars().count())
                .sum::<usize>() as f32
                * cell;
            (columns / width.max(1.0)).ceil().max(1.0) * line
        };

        // **The sharp statement**: a document made of nothing but the two blocks
        // whose geometry is intrinsic re-flows without asking the shaper a single
        // question. That is the whole of what a drag stops paying for.
        let heavy: Vec<preview::MarkdownBlock> = blocks
            .iter()
            .filter(|block| {
                matches!(
                    block,
                    preview::MarkdownBlock::Table { .. } | preview::MarkdownBlock::Code { .. }
                )
            })
            .cloned()
            .collect();
        let heavy_intrinsic: Vec<MarkdownBlockIntrinsic> = blocks
            .iter()
            .zip(&intrinsic)
            .filter(|(block, _)| {
                matches!(
                    block,
                    preview::MarkdownBlock::Table { .. } | preview::MarkdownBlock::Code { .. }
                )
            })
            .map(|(_, intrinsic)| intrinsic.clone())
            .collect();
        assert!(
            heavy.len() > 5,
            "the fixture carries enough of them to matter"
        );
        let before = reflow_calls.get();
        let heavy_layout = lay_markdown_out(&heavy, &heavy_intrinsic, 400.0, metrics, &mut measure);
        assert_eq!(
            reflow_calls.get(),
            before,
            "② a table and a fence are laid out from what was already measured"
        );
        assert!(
            heavy_layout.iter().all(|block| block.height > 0.0),
            "and they are laid out, not skipped"
        );

        // And the pass that remains is a real re-flow: a narrower pane is a
        // taller page, at a cost that does not grow with the document's tables.
        let mut heights = Vec::new();
        for width in [1200.0, 900.0, 700.0, 500.0, 380.0] {
            let layout = lay_markdown_out(&blocks, &intrinsic, width, metrics, &mut measure);
            heights.push(layout.last().map_or(0.0, |last| last.top + last.height));
        }
        for pair in heights.windows(2) {
            assert!(
                pair[1] > pair[0],
                "a narrower pane wraps to more lines: {pair:?}"
            );
        }
    }

    /// PIN (user report + ruling, 2026-08-13) — **the caret blinks exactly when
    /// typing would land in it.**
    ///
    /// The report: click a files tree or a preview and the terminal's caret goes
    /// on blinking behind you. `bt_render::seat_caret` already had the right
    /// *shape* for it — a caret that is not the keyboard's is steady and faded,
    /// which is what an unfocused pane's has always been — and the wrong
    /// *question*: it was handed "is this the focused pane" rather than "is this
    /// where the next keystroke goes".
    ///
    /// MUTATIONS, one per owner:
    /// ① drop the `files_tree` clause — clicking a tree leaves the shell blinking,
    ///    which is the report verbatim;
    /// ② drop the `preview` clause — the same, one leaf along, and it also covers
    ///    read-only browsing, where the arrows scroll the document;
    /// ③ drop `menu_or_dialog` — a menu that swallows every character key stands
    ///    over a caret still claiming them.
    #[test]
    fn only_a_shell_with_the_keyboard_gets_a_blinking_caret() {
        assert!(
            keyboard_owner_is_a_shell(KeyboardOwner::default()),
            "with nothing else holding it, the shell has the keyboard"
        );
        for owner in [
            KeyboardOwner {
                files_tree: true,
                ..KeyboardOwner::default()
            },
            KeyboardOwner {
                preview: true,
                ..KeyboardOwner::default()
            },
            KeyboardOwner {
                menu_or_dialog: true,
                ..KeyboardOwner::default()
            },
        ] {
            assert!(
                !keyboard_owner_is_a_shell(owner),
                "{owner:?} owns the keyboard, so no caret may claim it"
            );
        }
        // And the moment the owner hands it back, it is the shell's again — the
        // predicate is read per frame, so there is no state to un-set.
        assert!(keyboard_owner_is_a_shell(KeyboardOwner {
            rename: false,
            files_tree: false,
            graph_search: false,
            git_prompt: false,
            search: false,
            preview: false,
            menu_or_dialog: false,
        }));
    }

    /// PIN (user report, 2026-08-12) — **a composition goes where the keyboard
    /// is, and only the shell has a PTY.**
    ///
    /// The report, with a screenshot: click into the preview's edit surface,
    /// type Chinese, and the candidate list floats over the document while
    /// `ni'hao` arrives at the shell prompt underneath. `keyboard_input` had a
    /// twelve-rung ladder deciding who owns a keystroke; `ime_input` had two
    /// rungs and then wrote every commit to the PTY, so composed text was the
    /// one kind of typing that ignored `InputOwner` entirely.
    ///
    /// The last loop is the load-bearing one. "Zero PTY writes when the preview
    /// or the tree owns the keyboard" cannot be asserted without a window, but
    /// it has an exact structural twin that can: the owner that gets the
    /// composition must be the same owner whose caret is allowed to blink,
    /// because a blink *means* "typing lands here" (2026-08-13's ruling). One
    /// predicate, both questions — so the two can never drift into a window
    /// where a caret blinks in a shell that is not receiving the characters.
    ///
    /// MUTATIONS that must turn it red:
    /// ① answer `Shell` for `preview` — the reported bug, exactly;
    /// ② answer `Shell` for `files_tree` — the same bug one surface over;
    /// ③ put `preview` above `files_tree` — the ladder stops being
    ///    `keyboard_input`'s and the two disagree about a focused tree in a
    ///    preview's tab.
    #[test]
    fn a_composition_goes_where_the_keyboard_is_and_only_the_shell_has_a_pty() {
        assert_eq!(ime_owner(KeyboardOwner::default()), ImeOwner::Shell);
        assert_eq!(
            ime_owner(KeyboardOwner {
                preview: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::Preview,
            "the edit surface takes what is typed into it"
        );
        assert_eq!(
            ime_owner(KeyboardOwner {
                files_tree: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::FilesTree,
            "a column has nothing to type into — and nothing to type through"
        );
        assert_eq!(
            ime_owner(KeyboardOwner {
                menu_or_dialog: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::Modal
        );
        assert_eq!(
            ime_owner(KeyboardOwner {
                rename: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::Rename
        );

        // The order is `keyboard_input`'s order, rung for rung.
        assert_eq!(
            ime_owner(KeyboardOwner {
                files_tree: true,
                preview: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::FilesTree,
            "the tree's rung stands above the preview's, as it does for keys"
        );
        // T4 (v2 (3)) — the graph's search field stands between them: it lives on
        // a preview seat, so a composition routed by `preview` alone would land
        // in that seat's own edit surface while the caret was in the toolbar.
        assert_eq!(
            ime_owner(KeyboardOwner {
                graph_search: true,
                preview: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::GraphSearch,
        );
        assert_eq!(
            ime_owner(KeyboardOwner {
                rename: true,
                menu_or_dialog: true,
                files_tree: true,
                graph_search: true,
                git_prompt: true,
                search: true,
                preview: true,
            }),
            ImeOwner::Rename,
            "and the editor is the topmost of all of them"
        );
        // v2 (4) — the branch prompt stands **above** the popup rung, and that
        // is the whole reason it is a rung of its own: a popup swallows every
        // character key, which is right for a menu of verbs and wrong for a menu
        // you are typing a branch name into.
        assert_eq!(
            ime_owner(KeyboardOwner {
                git_prompt: true,
                menu_or_dialog: true,
                files_tree: true,
                graph_search: true,
                preview: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::GitPrompt,
            "the prompt inside a popup takes what is composed into it"
        );
        // §7.1.5d — **the capsule's field is under every one of them and over
        // the shell**, which is the only place it can be: it can only ever be
        // open on a terminal seat, so it can never be up at the same time as any
        // rung above it, and the rung below is the shell it stands on. That last
        // half is the one the rung exists for: without it a query composed in
        // Chinese would arrive at somebody's prompt.
        assert_eq!(
            ime_owner(KeyboardOwner {
                search: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::Search,
        );
        assert_eq!(
            ime_owner(KeyboardOwner {
                search: true,
                menu_or_dialog: true,
                ..KeyboardOwner::default()
            }),
            ImeOwner::Modal,
            "a dialog over the capsule takes everything, as it does over every surface"
        );
        // And a capsule that is up with the hands back on the terminal (B81)
        // owns nothing at all: the bit is only set while the caret is in it.
        assert_eq!(
            ime_owner(KeyboardOwner::default()),
            ImeOwner::Shell,
            "an unfocused capsule is not an owner"
        );

        // **The whole of "zero PTY writes", stated as a property.**
        //
        // Seven bits since the search capsule joined the ladder (§7.1.5d): the
        // sweep is over every combination there is, so a rung added without a
        // matching arm in `keyboard_owner_is_a_shell` fails here rather than in
        // a screenshot of a query appearing at somebody's prompt.
        for bits in 0..128u8 {
            let owner = KeyboardOwner {
                rename: bits & 1 != 0,
                menu_or_dialog: bits & 2 != 0,
                files_tree: bits & 4 != 0,
                preview: bits & 8 != 0,
                graph_search: bits & 16 != 0,
                git_prompt: bits & 32 != 0,
                search: bits & 64 != 0,
            };
            assert_eq!(
                matches!(ime_owner(owner), ImeOwner::Shell),
                keyboard_owner_is_a_shell(owner),
                "{owner:?}: a composition reaches the PTY exactly when a caret \
                 may blink, and never on any other terms"
            );
        }
    }

    /// PIN — a composition **opens a space in the line** rather than being
    /// painted over it, and the IME's caret stands inside it.
    ///
    /// The terminal's machine writes preedit into grid cells; this surface has
    /// none, so the form is copied and the mechanism cannot be. This used to
    /// copy it by drawing the row whole and laying the letters on top over an
    /// opaque patch of the *pane's* ground — which real-machine capture
    /// (2026-08-13) showed fails twice over: the patch hides only the cells the
    /// composition itself covers, so every character after the caret stays where
    /// it was and the composition and the rest of the word share cells neither
    /// can be read in; and on a float, whose body stands on the window's face
    /// rather than a pane's, the patch is the wrong colour as well. Splitting the
    /// row cures both, because there is then nothing left to hide.
    ///
    /// Asserted at **two geometries** — a docked pane's body and a float's, which
    /// is the surface the colour half of the bug only showed on — because a body
    /// that is a pure function of its rectangle must not have learned which kind
    /// of container it is in.
    ///
    /// MUTATIONS: draw the row unsplit (one run over `from..to`) and the tail's
    /// offset assertion goes red; put the ground quad back and the "no pane ink"
    /// assertion does; leave the caret at the document's column and the last one
    /// does.
    #[test]
    fn a_composition_in_the_preview_opens_a_space_in_the_line_it_lands_in() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_text_metrics(1.0);
        let lines = vec!["one".to_owned(), "paragraph".to_owned()];
        let advance = 8.0;
        let wrap = preview_edit::WrapLayout::unwrapped(&lines);
        // Mid-word, which is the case that was unreadable: four characters of
        // "paragraph" stand before the caret and five after it.
        let paint = PreviewEditPaint {
            bands: Vec::new(),
            caret: Some((1, 4)),
            caret_width: 1.0,
            preedit: Some(PreviewPreedit {
                row: 1,
                column: 4,
                text: "ni".to_owned(),
                columns: 2,
                caret_columns: 1,
            }),
        };
        // A pane's body and a float's — the same builder, two containers.
        for (surface, body) in [
            ("a docked pane", [0.0, 0.0, 400.0, 200.0]),
            ("a preview float", [1866.0, 145.0, 2266.0, 345.0]),
        ] {
            let geometry = seats::preview_mono_geometry(
                body,
                metrics,
                metrics.line_height * 2.0,
                12,
                advance,
                [0.0, 0.0],
            );
            let built = build_preview_text_body(
                &geometry,
                &lines,
                &wrap,
                &highlight::Highlighting::default(),
                advance,
                Some(&paint),
                &palette,
            );
            let row = geometry.line_rect(1);
            let at = |columns: f32| row[0] + advance * columns;
            let run_at = |text: &str| {
                built
                    .paragraphs
                    .iter()
                    .find(|paragraph| paragraph.runs.iter().any(|run| run.text == text))
                    .unwrap_or_else(|| panic!("{surface}: no run drawing {text:?}"))
                    .rect[0]
            };

            // The line is two runs with the composition's own width between them.
            assert_eq!(run_at("para"), at(0.0), "{surface}: the head stays put");
            assert_eq!(
                run_at("graph"),
                at(6.0),
                "{surface}: and the tail is pushed right by the whole composition \
                 — four columns of head plus its own two"
            );
            let letters = run_at("ni");
            assert_eq!(
                letters,
                at(4.0),
                "{surface}: the letters land at the caret, in the space just opened"
            );
            assert!(
                letters + advance * 2.0 <= run_at("graph") + 0.001,
                "{surface}: and stop before the tail begins — nothing overlaps"
            );

            // Nothing is masked, so no pane-only ink is painted at all: that is
            // the half of the bug a float showed and a pane hid.
            assert!(
                !built
                    .quads
                    .iter()
                    .any(|quad| quad.color == palette.seat_body),
                "{surface}: a split line needs no ground under the composition"
            );
            let rule = built
                .quads
                .iter()
                .find(|quad| quad.color == palette.preview_body_text)
                .unwrap_or_else(|| panic!("{surface}: underlined, as a preedit is"));
            assert_eq!(
                rule.rect[3], row[3],
                "{surface}: along the bottom of its line"
            );
            let caret = built
                .quads
                .iter()
                .find(|quad| quad.color == palette.preview_caret)
                .unwrap_or_else(|| panic!("{surface}: the caret is drawn"));
            assert_eq!(
                caret.rect[0],
                at(5.0),
                "{surface}: inside the composition, where the IME says it is"
            );
        }
    }

    /// PIN (P123) — **gate ① is about the LAST preview pane and nothing else.**
    ///
    /// "The pool outlives any ONE pane; only the LAST preview pane's close would
    /// strand it." A window that asked every time a pane closed would be asking
    /// about buffers still on screen, and a question you can answer by looking is
    /// a question that trains you to dismiss the ones you cannot.
    ///
    /// Mutation: drop the `previews_in_tab == 1` clause and the second assertion
    /// goes red — every closed pane raises the gate; drop `closing_a_preview` and
    /// the third does, and closing a *terminal* asks about a preview.
    #[test]
    fn only_the_last_preview_pane_strands_the_pool() {
        assert!(closing_this_pane_strands_the_pool(true, 1));
        assert!(
            !closing_this_pane_strands_the_pool(true, 2),
            "one of two previews leaves the pool on screen"
        );
        assert!(
            !closing_this_pane_strands_the_pool(false, 1),
            "a terminal closing beside a preview strands nothing"
        );
        assert!(!closing_this_pane_strands_the_pool(false, 0));
    }

    /// Just the pixels a document renders to, for the tests that are about
    /// pixels. The links beside them are measured by the shaper and asked for
    /// where a `Renderer` is, which is not here.
    fn markdown_body(
        body: [f32; 4],
        metrics: seats::PreviewMarkdownMetrics,
        scroll: [f32; 2],
        bars: BlockScrollPaint<'_>,
        document: (&[preview::MarkdownBlock], &[MarkdownBlockLayout]),
        palette: &bt_render::ChromePalette,
    ) -> bt_render::PreviewBody {
        // The intrinsics are the fences' highlighting and nothing else here, so
        // a test about pixels can pass none and get the ink it always got.
        let document = (document.0, [].as_slice(), document.1);
        build_preview_markdown_body(body, metrics, scroll, bars, document, palette).body
    }

    /// The bars at rest: the offsets under test, nothing lit, one device pixel
    /// to the logical one.
    fn rested_bars(offsets: &[f32]) -> BlockScrollPaint<'_> {
        BlockScrollPaint {
            offsets,
            lit: None,
            scale: 1.0,
        }
    }

    /// Whether one rectangle is wholly inside another.
    fn inside(rect: [f32; 4], outer: [f32; 4]) -> bool {
        rect[0] >= outer[0] && rect[1] >= outer[1] && rect[2] <= outer[2] && rect[3] <= outer[3]
    }

    /// PIN — **the painter puts the document in the measure's column**, centred
    /// when the pane can afford it and flush to the pane when it cannot
    /// (§7.1.3i; user report 2026-08-16).
    ///
    /// The geometry itself is `preview::markdown_measure_box`'s and is pinned
    /// beside it; what is asserted here is that the *painter* asks — a body that
    /// went on computing `body[0] + padding_x` for itself would draw the prose
    /// across a maximised window while the layout pass wrapped it at 702, which
    /// is a paragraph that reserves four rows and paints two.
    ///
    /// MUTATION: put `let left = body[0] + metrics.padding_x` back at the top of
    /// `build_preview_markdown_body` and the wide case goes red.
    #[test]
    fn a_pane_wider_than_the_measure_is_painted_into_a_centred_column() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let blocks = preview::parse_markdown("Prose enough to have an edge.\n");
        let layout = vec![MarkdownBlockLayout::solid(metrics.line_height)];
        let column = |body: [f32; 4]| {
            let built = markdown_body(
                body,
                metrics,
                [0.0, 0.0],
                rested_bars(&[]),
                (&blocks, &layout),
                &palette,
            );
            let rect = built.paragraphs[0].rect;
            (rect[0], rect[2])
        };

        let narrow = [0.0, 0.0, 500.0, 600.0];
        assert_eq!(
            column(narrow),
            (metrics.padding_x, 500.0 - metrics.padding_x),
            "a pane under the measure keeps the pane, exactly as before"
        );

        let wide = [0.0, 0.0, 1600.0, 600.0];
        let (left, right) = column(wide);
        assert_eq!(right - left, metrics.measure, "the column stops growing");
        assert_eq!(
            left - wide[0],
            wide[2] - right,
            "and it is centred in the pane"
        );
    }

    /// PIN — **`h1` and `h2` are painted with a hairline under them, and no
    /// other level is** (`h1, h2 { border-bottom: 1px solid }`, §7.1.3i).
    ///
    /// The rule is a quad in `--border`, drawn at the very bottom of the block's
    /// own box, and the heading's text box stops short of it by exactly the
    /// extent the measuring pass reserved — a rule painted into space nobody
    /// reserved is a rule printed over the first line of the next paragraph.
    ///
    /// MUTATION: drop the `- rule` from the heading's text rectangle and the
    /// last assertion goes red, which is a title sitting on its own underline.
    #[test]
    fn the_first_two_heading_levels_are_painted_with_a_rule_under_them() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let body = [0.0, 0.0, 600.0, 900.0];
        let blocks = preview::parse_markdown("# One\n\n## Two\n\n### Three\n");
        assert_eq!(blocks.len(), 3, "three headings and nothing else");
        let mut layout = Vec::new();
        let mut top = 0.0_f32;
        for level in 1..=3u8 {
            let height = metrics.heading_line_height(level) + metrics.heading_rule_extent(level);
            layout.push(MarkdownBlockLayout {
                top,
                ..MarkdownBlockLayout::solid(height)
            });
            top += height + metrics.heading_margin_bottom;
        }
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (&blocks, &layout),
            &palette,
        );
        let (left, right) = preview::markdown_measure_box(body, metrics);
        let origin = body[1] + metrics.padding_y;

        let rules: Vec<&bt_render::PreviewQuad> = built
            .quads
            .iter()
            .filter(|quad| quad.color == palette.preview_grid_line)
            .collect();
        assert_eq!(
            rules.len(),
            2,
            "one under the h1, one under the h2, and no more"
        );
        for (index, rule) in rules.iter().enumerate() {
            let placed = &layout[index];
            let bottom = origin + placed.top + placed.height;
            assert_eq!(
                rule.rect,
                [left, bottom - metrics.heading_rule_thickness, right, bottom],
                "the rule for level {} runs the column's own width at the foot of \
                 its block",
                index + 1
            );
        }
        for (index, paragraph) in built.paragraphs.iter().enumerate() {
            let level = index as u8 + 1;
            let placed = &layout[index];
            assert_eq!(
                paragraph.rect[3],
                origin + placed.top + placed.height - metrics.heading_rule_extent(level),
                "level {level}'s text stops above its own rule, not on it"
            );
            assert_eq!(paragraph.font_size_px, metrics.heading_font(level));
            assert_eq!(paragraph.line_height_px, metrics.heading_line_height(level));
        }
    }

    /// PIN — **a quoted line steps back to the muted ink; its bar keeps the
    /// accent, and the styles that carry their own ink keep theirs**
    /// (`blockquote { color: muted }`, §7.1.3i).
    ///
    /// The ink is decided from the *span's style*, not from the colour already on
    /// the run, which is what lets a code span inside a quote stay the fence's
    /// own ink and a link stay the accent — a blanket recolour of the paragraph
    /// would swallow both.
    ///
    /// MUTATION: recolour every run and the code span's assertion goes red;
    /// recolour none and the first two go red, which is the report's "quotes read
    /// like body text with a stripe beside them".
    #[test]
    fn a_quoted_line_steps_back_to_the_muted_ink_and_keeps_its_accent_bar() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let body = [0.0, 0.0, 600.0, 600.0];
        let blocks = preview::parse_markdown("> quoted **strongly** with `code` in it\n");
        let layout = vec![MarkdownBlockLayout::rows(
            vec![metrics.line_height],
            metrics.quote_padding_y * 2.0,
        )];
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (&blocks, &layout),
            &palette,
        );
        let (left, _) = preview::markdown_measure_box(body, metrics);

        let bar = built.quads.first().expect("a quote draws its bar first");
        assert_eq!(bar.color, palette.accent, "the bar keeps the accent");
        assert_eq!(bar.rect[2] - bar.rect[0], metrics.quote_bar);
        assert_eq!(bar.rect[0], left);

        let line = &built.paragraphs[0];
        assert_eq!(
            line.rect[0],
            left + metrics.quote_indent,
            "the text starts beside the bar, `padding: 0 15px` away from it"
        );
        let plain: Vec<[u8; 3]> = line
            .runs
            .iter()
            .filter(|run| !run.mono)
            .map(|run| run.color)
            .collect();
        assert!(
            plain.iter().all(|color| *color == palette.files_row_muted),
            "prose and emphasis alike step back: {plain:?}"
        );
        let code = line
            .runs
            .iter()
            .find(|run| run.mono)
            .expect("the fixture quotes a code span");
        assert_eq!(
            code.color, palette.preview_code_text,
            "and code keeps its own"
        );
        assert_eq!(code.font_scale, preview::PREVIEW_MD_CODE_FONT_RATIO);
    }

    /// PIN — **a fence is set at 85% of the body on its own 1.45 leading**
    /// (`pre { font-size: 85%; line-height: 1.45; padding: 16px }`, §7.1.3i).
    ///
    /// The height the layout pass reserved is `code_line_height` a row, so a
    /// painter still stepping by the body's `line_height` would draw the last
    /// line of a long fence outside its own ground.
    ///
    /// MUTATION: put `metrics.line_height` back on either the paragraph or the
    /// step and the rows stop landing on the reservation.
    #[test]
    fn a_fence_is_set_at_its_own_size_and_stepped_at_its_own_leading() {
        let palette = bt_render::chrome_palette();
        let metrics = seats::preview_markdown_metrics(1.0);
        let body = [0.0, 0.0, 600.0, 600.0];
        let blocks = preview::parse_markdown("```\nfn a() {}\nfn b() {}\n```\n");
        let rows = 2.0;
        let layout = vec![MarkdownBlockLayout::solid(
            metrics.code_border * 2.0
                + metrics.code_padding_y * 2.0
                + metrics.code_line_height * rows,
        )];
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (&blocks, &layout),
            &palette,
        );
        assert_eq!(built.paragraphs.len(), 2, "one paragraph per fenced line");
        assert!(metrics.code_font < metrics.font_size, "85%, not 100%");
        for paragraph in &built.paragraphs {
            assert_eq!(paragraph.font_size_px, metrics.code_font);
            assert_eq!(paragraph.line_height_px, metrics.code_line_height);
            assert!(!paragraph.wrap, "and it still refuses to reflow");
        }
        assert_eq!(
            built.paragraphs[1].rect[1] - built.paragraphs[0].rect[1],
            metrics.code_line_height,
            "the rows are stepped at the fence's own leading"
        );
        let ground = built.paragraphs[0].rect[1];
        assert_eq!(
            ground,
            body[1] + metrics.padding_y + metrics.code_border + metrics.code_padding_y,
            "and the first one starts inside a 1em pad"
        );
    }

    /// PIN — a code fence is a box with a ground, and its language rides the
    /// top-right corner of that box (mock-up 1202-1211).
    ///
    /// Mutation: drop the `align_right` on the language tag, which parks it over
    /// the first line of the code.
    #[test]
    fn a_code_fence_is_a_box_and_its_language_sits_in_the_corner() {
        let palette = bt_render::chrome_palette();
        let body = [0.0, 0.0, 600.0, 400.0];
        let metrics = seats::preview_markdown_metrics(1.0);
        let blocks = preview::parse_markdown("```rust\nlet x = 1;\n```\n");
        let height = metrics.code_border * 2.0 + metrics.code_padding_y * 2.0 + metrics.line_height;
        let built = markdown_body(
            body,
            metrics,
            [0.0, 0.0],
            rested_bars(&[]),
            (
                &blocks,
                &[MarkdownBlockLayout {
                    top: 0.0,
                    height,
                    ..MarkdownBlockLayout::default()
                }],
            ),
            &palette,
        );
        let border = built
            .quads
            .iter()
            .find(|quad| quad.color == palette.preview_code_border)
            .expect("the fence has a border");
        let ground = built
            .quads
            .iter()
            .find(|quad| quad.color == palette.preview_code_ground)
            .expect("and a ground inside it");
        assert!(
            ground.rect[0] > border.rect[0] && ground.rect[2] < border.rect[2],
            "the ground is inset by the border"
        );
        let lang = built
            .paragraphs
            .iter()
            .find(|p| p.runs[0].color == palette.preview_code_lang)
            .expect("the language tag is drawn");
        assert_eq!(lang.runs[0].text, "RUST", "and it is upper-cased");
        assert!(lang.align_right, "in the corner, not over the code");
        assert_eq!(lang.letter_spacing_em, seats::PREVIEW_MD_LANG_TRACKING_EM);
        assert_eq!(lang.rect[2], border.rect[2] - metrics.lang_inset_right);
        assert!(
            built.paragraphs.iter().any(|p| {
                p.runs
                    .iter()
                    .map(|run| run.text.as_str())
                    .collect::<String>()
                    == "let x = 1;"
                    && p.runs.iter().all(|run| run.mono)
            }),
            "the code itself is monospace"
        );
    }

    /// A measurer for the foot tests: every glyph half the point size wide,
    /// which is about what Segoe UI averages and is exact enough to do
    /// arithmetic with.
    ///
    /// Deliberately not the real shaper. What these tests are about is the
    /// *division* of a strip between two runs, and a fixture whose widths a
    /// reader cannot compute in their head would be measuring the font instead
    /// of the rule.
    fn ruler(text: &str, size: f32) -> f32 {
        text.chars().count() as f32 * size / 2.0
    }

    /// PIN (user ruling, 2026-08-15) — **the read-only fact hangs on the path
    /// foot's right hand, and the document gets back the bar it used to lose.**
    ///
    /// The report was about the picture: on `huge.txt` the pane ended in two
    /// 28px strips stacked on each other, the read-only bar sitting on the path
    /// bar, and two horizontal rules of identical height at the bottom of one
    /// pane read as a mistake however each one was justified on its own.
    ///
    /// So the upper strip retired and the fact it carried moved into the lower
    /// one's right hand. Three things had to become true and all three are here:
    ///
    /// ① the wording is a **phrase** and not a sentence, because it now shares
    ///    28 pixels with a path — and it still says the size, which is the half
    ///    of the old sentence that was information;
    /// ② the phrase stands flush against the strip's right edge with the path
    ///    stopping a gap short of it, so the two are two runs and not one;
    /// ③ the body the document is laid out in is the pane's body **whole** — the
    ///    28 pixels the bar used to reserve are the document's again.
    ///
    /// MUTATION for ①: give the constant back its old sentence and the size
    /// assertion goes red on a phrase that no longer names 64 KB.
    /// MUTATION for ②: hand `foot_notice_split` the run unchanged (return
    /// `(run, run)`) and the disjointness assertion goes red — the path prints
    /// through the phrase, which is the collision the split exists to prevent.
    /// MUTATION for ③ is a **compile error**, and that is the point:
    /// `bt_render::PreviewBody` no longer has a slot for furniture at all, so
    /// the reservation cannot be reintroduced by an edit to one branch. The
    /// height it used to take is pinned one layer down, by
    /// `seats::a_preview_pane_reserves_its_path_strip_out_of_its_body`, which
    /// asserts the pane gives up exactly one strip.
    #[test]
    fn the_read_only_fact_hangs_on_the_path_foots_right_hand() {
        // ① The phrase, and the size it names.
        assert_eq!(
            preview::preview_truncated_notice(),
            format!(
                "Read-only · {}",
                preview::format_byte_size(preview::PREVIEW_HEAD_BYTES as u64)
            ),
            "the phrase names the head read's real size, not a number typed twice"
        );

        // ② The division of the strip.
        let run = [100.0, 400.0, 500.0, 428.0];
        let gap = 12.0;
        let words = seats::dress_foot(
            seats::FootDress {
                run,
                lead: r"C:\w\huge.txt",
                flash: None,
                notice: preview::preview_truncated_notice(),
                cut_left: true,
                font_px: 10.0,
                gap_px: gap,
            },
            &mut ruler,
        );
        assert_eq!(words.notice, preview::preview_truncated_notice());
        assert_eq!(
            words.notice_box[2], run[2],
            "flush with the strip's right edge"
        );
        assert_eq!(
            words.notice_box[2] - words.notice_box[0],
            ruler(preview::preview_truncated_notice(), 10.0),
            "and no wider than its own words"
        );
        assert_eq!(
            words.lead_box[2],
            words.notice_box[0] - gap,
            "the path stops a gap short of the phrase"
        );
        assert!(
            words.lead_box[2] < words.notice_box[0],
            "two runs, not one: nothing of the path is inside the phrase's box"
        );
        assert!(!words.flashing, "nothing is being confirmed");
    }

    /// PIN (user ruling, 2026-08-15) — **when the path and the phrase meet, the
    /// path is what gives way.**
    ///
    /// The path was always going to be cut: P35 gives it a left ellipsis
    /// precisely because a full path rarely fits a pane's foot, and one that has
    /// already lost its drive letter loses nothing new by losing three more
    /// characters. The phrase has no such slack — "Read-only · 64" is not an
    /// abbreviation of anything, it is a broken fact — so it is never cut, and a
    /// rule that cut the shorter run to save the longer one would have had it
    /// exactly backwards.
    ///
    /// MUTATION ①: ellipsize the lead against the whole `run` instead of
    /// `lead_box` and the first assertion goes red — the path is cut to a width
    /// it does not have and prints straight through the phrase.
    /// MUTATION ②: pass the notice through `ellipsized` as well and the
    /// second goes red on a truncated truncation notice.
    #[test]
    fn a_long_path_is_cut_and_the_phrase_beside_it_is_not() {
        let run = [0.0, 0.0, 300.0, 28.0];
        let gap = 12.0;
        let long = r"C:\Users\somebody\Developer\BetterTerminal\crates\bt-app\src\main.rs";
        let words = seats::dress_foot(
            seats::FootDress {
                run,
                lead: long,
                flash: None,
                notice: preview::preview_truncated_notice(),
                cut_left: true,
                font_px: 10.0,
                gap_px: gap,
            },
            &mut ruler,
        );
        assert!(
            ruler(&words.lead, 10.0) <= words.lead_box[2] - words.lead_box[0],
            "the path was cut to the room the phrase left it, not to the whole strip"
        );
        assert!(
            words.lead.starts_with('…') && words.lead.ends_with("main.rs"),
            "cut from the front, so the file name survives (P35): {}",
            words.lead
        );
        assert_eq!(
            words.notice,
            preview::preview_truncated_notice(),
            "and the phrase is whole"
        );

        // The same strip with nothing hung on it gives the path all of it, which
        // is what makes the loss above the phrase's doing and not the run's.
        let alone = seats::dress_foot(
            seats::FootDress {
                run,
                lead: long,
                flash: None,
                notice: "",
                cut_left: true,
                font_px: 10.0,
                gap_px: gap,
            },
            &mut ruler,
        );
        assert_eq!(alone.lead_box, run, "no phrase, no toll");
        assert!(
            alone.lead.chars().count() > words.lead.chars().count(),
            "and more of the path survives"
        );
    }

    /// PIN (user ruling, 2026-08-15) — **while the foot is flashing, its right
    /// hand is empty.**
    ///
    /// "Revealed in File Explorer" and "Saved" are answers to something the user
    /// just did, and they stand for 1300ms before the path comes back. A
    /// standing fact printed beside a confirmation turns one unambiguous word
    /// into two things to read at the one moment the strip has to be read at a
    /// glance — so the phrase steps aside for as long as the word stands, and
    /// comes back on its own when the word expires.
    ///
    /// The pairing is real rather than hypothetical: a truncated buffer is
    /// read-only and can never flash "Saved", but its foot is still a button,
    /// and pressing it flashes "Revealed" over a file whose read-only phrase is
    /// standing right there.
    ///
    /// MUTATION: drop the `flashing` guard in `dress_foot` and both the empty
    /// assertion and the full-width assertion go red at once — the confirmation
    /// shares its strip with a warning.
    #[test]
    fn a_flashing_foot_gives_the_whole_strip_to_the_word_it_is_flashing() {
        let run = [0.0, 0.0, 300.0, 28.0];
        for flash in [foot_revealed_label(), preview::preview_saved_notice()] {
            let words = seats::dress_foot(
                seats::FootDress {
                    run,
                    lead: r"C:\w\huge.txt",
                    flash: Some(flash),
                    notice: preview::preview_truncated_notice(),
                    cut_left: true,
                    font_px: 10.0,
                    gap_px: 12.0,
                },
                &mut ruler,
            );
            assert!(words.flashing, "{flash}: the strip is confirming");
            assert_eq!(
                words.lead, flash,
                "{flash}: and says so instead of the path"
            );
            assert_eq!(words.notice, "", "{flash}: the phrase steps aside");
            assert_eq!(words.notice_width, 0.0);
            assert_eq!(
                words.lead_box, run,
                "{flash}: and pays no toll for a phrase that is not there"
            );
        }
    }

    // ── slice 3: quick edit ─────────────────────────────────────────────────

    /// A buffer with a body, for the document tests below.
    fn text_buffer(name: &str, body: &str) -> preview::PreviewBuffer {
        let mut buffer = preview::PreviewBuffer::new(
            preview::PreviewSource::file(format!(r"C:\w\{name}")),
            name.to_owned(),
        );
        buffer.accept(preview::HeadOutcome::Read {
            text: body.to_owned(),
            truncated: false,
            mtime: None,
        });
        buffer
    }

    /// **The flip is the view's, not the buffer's** (ruling 2026-08-13).
    ///
    /// Two surfaces on one markdown file: turning one over leaves the other
    /// showing what it was showing, and the *buffer* — its body, its dirty bit,
    /// its revision — stays shared across both, because the ruling moved the
    /// view mode and nothing else.
    ///
    /// Real-machine capture is the reason it exists: `md_source` lived on the
    /// shared `PreviewBuffer`, so a float torn off to read a rendered page turned
    /// into raw markdown the moment a pane behind it was flipped to source.
    ///
    /// Mutation: read the face off the buffer again — give `PreviewBuffer` back
    /// its `md_source` and have both panes consult it — and the second assertion
    /// goes red, which is the reported bleed exactly.
    #[test]
    fn two_surfaces_on_one_markdown_buffer_flip_independently() {
        let mut panes = PreviewPanes::default();
        let source = preview::PreviewSource::file(r"C:\w\notes.md");
        let pane = PreviewSurface::Seat(SeatId(1));
        let float = PreviewSurface::Float(7);
        for surface in [pane, float] {
            panes.entry(surface).buffer = Some(source.clone());
        }
        let mut pool = preview::PreviewPool::default();
        pool.insert(text_buffer("notes.md", "# Title\n\nbody\n"));

        // Both start on the render, which is what never having been flipped is.
        assert!(!panes.entry(pane).md_source);
        assert!(!panes.entry(float).md_source);

        // The pane is turned over. The float is not.
        panes.entry(pane).md_source = true;
        assert!(panes.entry(pane).md_source, "the surface that was flipped");
        assert!(
            !panes.entry(float).md_source,
            "and only that one — a float reading the page keeps reading the page"
        );

        // Which is what every reader downstream of the flag now answers with.
        let buffer = pool.get(&source).expect("the one buffer");
        assert_eq!(
            (
                buffer.view(panes.entry(pane).md_source),
                buffer.view(panes.entry(float).md_source)
            ),
            (preview::PreviewView::Text, preview::PreviewView::Markdown),
            "one file, two faces, at the same instant"
        );
        assert!(
            buffer.is_editable(true) && !buffer.is_editable(false),
            "the source face has a caret and the rendered page has not"
        );
        assert_ne!(
            preview_document_key(buffer, true, 400.0, 1.0),
            preview_document_key(buffer, false, 400.0, 1.0),
            "so the two faces cannot share one cached document"
        );

        // And the buffer itself is still one buffer: the ruling moved the view
        // mode, not the file.
        let buffer = pool.get_mut(&source).expect("the one buffer");
        buffer.edit_content(|content| {
            content.push_str("more\n");
            true
        });
        assert!(buffer.dirty, "an edit through either face dirties the file");
        assert_eq!(
            pool.buffers().count(),
            1,
            "and there is still exactly one of it"
        );
    }

    /// ⑥ A same-length edit rebuilds the document.
    ///
    /// **The named bug.** The cache key's revision counter was the content's
    /// *length* — written down as "the cheapest honest revision counter until
    /// slice 3 gives a buffer edits to count" — and a length cannot see the
    /// commonest edit there is. Typing over a selected character, correcting a
    /// letter, pressing Delete then typing the replacement: all three keep the
    /// length, and all three left the cached document convinced it was still
    /// looking at the text from before the keystroke.
    ///
    /// Mutation: put `content_len: buffer.content.map_or(0, str::len)` back in
    /// place of `revision` in [`preview_document_key`]. The first assertion then
    /// fails and the second still passes, which is exactly the shape of the bug.
    #[test]
    fn a_same_length_edit_rebuilds_the_cached_document() {
        let mut buffer = text_buffer("a.rs", "let x = 1;\n");
        let before = preview_document_key(&buffer, false, 400.0, 2.0);
        buffer.edit_content(|content| {
            content.replace_range(8..9, "2");
            true
        });
        assert_eq!(buffer.content.as_deref(), Some("let x = 2;\n"));
        let after = preview_document_key(&buffer, false, 400.0, 2.0);
        assert_ne!(
            before, after,
            "one letter for another is still a different document"
        );
        // And nothing else moved: the same buffer at the same width and scale is
        // the same key, or every wheel notch would re-parse the file.
        assert_eq!(after, preview_document_key(&buffer, false, 400.0, 2.0));
        assert_ne!(after, preview_document_key(&buffer, true, 400.0, 2.0));
        assert_ne!(after, preview_document_key(&buffer, false, 401.0, 2.0));
        assert_ne!(after, preview_document_key(&buffer, false, 400.0, 1.0));
    }

    /// ⑤ A caret, a selection and a scroll survive a switch to another buffer
    /// and back.
    ///
    /// Ruling 8⑧, and the half of it a window that never rebuilds its DOM still
    /// has to earn: the prototype's problem was a re-render destroying the live
    /// `<textarea>`, and this one's is the *switcher* — a pool whose whole point
    /// is that "unsaved edits survive switching with zero prompts" would be
    /// telling half a truth if the place you were reading did not survive with
    /// them.
    ///
    /// Mutation: make [`PreviewViewStore::remember`] a no-op, or have
    /// [`PreviewViewStore::restore`] always answer with the default.
    #[test]
    fn a_caret_and_a_scroll_survive_a_switch_to_another_buffer_and_back() {
        let mut store = PreviewViewStore::default();
        let one = &preview::PreviewSource::file(r"C:\w\one.rs");
        let two = &preview::PreviewSource::file(r"C:\w\two.rs");
        // A file never looked at starts at the top with the caret at its head.
        assert_eq!(store.restore(one), PreviewViewState::default());

        let reading = PreviewViewState {
            caret: preview_edit::EditCaret {
                anchor: 40,
                caret: 12,
                desired_column: Some(7),
            },
            scroll: [16.0, 380.0],
        };
        store.remember(one, reading);
        // Away to another file, which has a place of its own.
        store.remember(
            two,
            PreviewViewState {
                caret: preview_edit::EditCaret {
                    anchor: 3,
                    caret: 3,
                    desired_column: None,
                },
                scroll: [0.0, 19.0],
            },
        );
        assert_eq!(
            store.restore(one),
            reading,
            "and back to the first: the caret, what it had selected, and how far down"
        );
        assert_eq!(store.restore(two).scroll, [0.0, 19.0]);
        assert_eq!(store.restore(one).caret.range(), 12..40);
    }

    /// ⑦ A long markdown and a long table scroll, and neither scrolls past its
    /// own end.
    ///
    /// **Slice 2's open account.** Both bodies clamped to `[0, 0]` — the extent
    /// function answered `(0.0, 0)` for them — so a `README.md` longer than its
    /// pane and a `.csv` with a hundred rows were *drawn* past their own ends
    /// and could never be scrolled to. Neither scrolls sideways, and that is a
    /// ruling rather than an omission: markdown wraps to the pane and a table's
    /// columns are as wide as its own cells.
    ///
    /// Mutation: return `[0.0, 0.0]` for either arm of
    /// [`preview_document_max_scroll`], which restores the bug exactly.
    #[test]
    fn a_long_markdown_and_a_long_table_scroll_and_stop_at_their_own_ends() {
        let body = [0.0, 0.0, 400.0, 200.0];
        let scale = 1.0;
        let metrics = seats::preview_markdown_metrics(scale);
        // Forty blocks of one line each, laid out the way the runtime lays them.
        let blocks: Vec<preview::MarkdownBlock> = (0..40)
            .map(|index| {
                preview::MarkdownBlock::Paragraph(vec![preview::Span::plain(&format!(
                    "line {index}"
                ))])
            })
            .collect();
        let mut layout: Vec<MarkdownBlockLayout> = Vec::new();
        let mut top = 0.0_f32;
        for _ in &blocks {
            top += metrics.paragraph_gap;
            layout.push(MarkdownBlockLayout {
                top,
                height: metrics.line_height,
                ..MarkdownBlockLayout::default()
            });
            top += metrics.line_height;
        }
        let last = layout.last().unwrap();
        let expected = last.top + last.height + metrics.padding_y * 2.0 - (body[3] - body[1]);
        let markdown = PreviewDocument::Markdown {
            blocks,
            intrinsic: Vec::new(),
            layout,
        };
        let max = preview_document_max_scroll(&markdown, body, scale, 8.0, 0.0, 0);
        assert!(max[1] > 0.0, "a document taller than its pane can scroll");
        assert_eq!(max[1], expected, "and stops exactly at its own last line");
        assert_eq!(max[0], 0.0, "markdown wraps, so there is nowhere sideways");

        let rows: Vec<Vec<String>> = (0..60)
            .map(|index| vec![format!("row {index}"), "value".to_owned()])
            .collect();
        let table = PreviewDocument::Table {
            rows,
            column_cells: vec![8, 5],
        };
        let max = preview_document_max_scroll(&table, body, scale, 8.0, 0.0, 0);
        let geometry = seats::preview_table_geometry(body, &[8, 5], 60, 8.0, scale, [0.0, 0.0]);
        assert_eq!(max, geometry.max_scroll);
        assert!(max[1] > 0.0, "sixty rows do not fit in two hundred pixels");

        // A short one still cannot be scrolled at all, on either axis.
        let short = PreviewDocument::Table {
            rows: vec![vec!["a".to_owned()]],
            column_cells: vec![2],
        };
        assert_eq!(
            preview_document_max_scroll(&short, body, scale, 8.0, 0.0, 0),
            [0.0, 0.0]
        );
    }

    /// PIN (user ruling, 2026-08-13) — **the text surface folds and has no
    /// sideways; the diff keeps `pre` and has one.**
    ///
    /// The two halves of one ruling, asserted together because the ruling is
    /// about the difference. A preview is a quick look and content reachable
    /// only by a hidden gesture reads as content that is not there — so the text
    /// body wraps and its horizontal extent collapses to nothing, because there
    /// is nowhere sideways to go. A patch is the exception and its own reason:
    /// the alignment between the two columns and the full-width tint under every
    /// row are what a patch *means*, and reflow destroys both.
    ///
    /// MUTATION ①: answer `buffer.max_columns` for a wrapping text body in
    /// `preview_content_extent` and the "nowhere sideways" assertion goes red —
    /// the pane grows a scrollbar for a document that has no width.
    /// MUTATION ②: hand the diff a `WrapLayout::wrapped` and the last assertion
    /// goes red, which is a patch losing its columns.
    #[test]
    fn the_text_body_folds_with_no_sideways_and_the_diff_keeps_both() {
        // Deliberately shorter than the folded document, so "can be scrolled to
        // its own last row" is a question with an answer.
        let body = [0.0, 0.0, 240.0, 60.0];
        let scale = 1.0;
        let advance = 8.0;
        let metrics = seats::preview_text_metrics(scale);
        let columns = preview_wrap_columns(body, metrics, advance)
            .expect("a 240px pane at 8px a cell holds cells");
        assert!(columns > 4, "the fixture pane is wide enough to be a pane");

        // One line far wider than the pane, and one that fits.
        let long = "x".repeat(columns * 4);
        let lines = vec![long.clone(), "short".to_owned()];
        let wrap = preview_edit::WrapLayout::wrapped(&lines, columns);
        assert_eq!(
            wrap.rows(),
            5,
            "four rows for the long line and one for the short"
        );

        // ① The vertical extent is the *rows*, so the scroller can reach the end
        //    of a folded document; the horizontal one is nothing at all.
        let document = PreviewDocument::Text {
            lines: lines.clone(),
            wrap: wrap.clone(),
            highlight: highlight::Highlighting::default(),
        };
        // The file's own width is handed in, exactly as the runtime hands it in:
        // the ruling that a folded body cannot reach it is the function's, not
        // the caller's, and a caller that pre-zeroed it would prove nothing.
        let max = preview_document_max_scroll(
            &document,
            body,
            scale,
            advance,
            metrics.line_height * wrap.rows() as f32,
            long.chars().count(),
        );
        assert_eq!(max[0], 0.0, "a folded body has nowhere sideways to go");
        assert!(max[1] > 0.0, "and can be scrolled to its own last row");

        // ② The painter draws one paragraph per *row*, and the rows put the
        //    whole line back together with nothing lost off the right edge.
        let palette = bt_render::chrome_palette();
        // A pane tall enough to hold every row at once: the painter culls what
        // is off screen, and this assertion is about the folding, not the cull.
        let tall = [body[0], body[1], body[2], 400.0];
        let geometry = seats::preview_mono_geometry(
            tall,
            metrics,
            metrics.line_height * wrap.rows() as f32,
            0,
            advance,
            [0.0, 0.0],
        );
        let built = build_preview_text_body(
            &geometry,
            &lines,
            &wrap,
            &highlight::Highlighting::default(),
            advance,
            None,
            &palette,
        );
        // A row is however many runs its highlighting needs (#49) — one on this
        // fixture, several on a highlighted one — so a row's *text* is its runs
        // joined, never its first run.
        let drawn: Vec<String> = built
            .paragraphs
            .iter()
            .map(|p| p.runs.iter().map(|run| run.text.as_str()).collect())
            .collect();
        assert_eq!(drawn.len(), 5, "five rows drawn, not two lines");
        assert_eq!(
            drawn[..4].concat(),
            long,
            "and the four rows of the long line are the long line, entire"
        );
        assert!(
            drawn
                .iter()
                .take(4)
                .all(|row| row.chars().count() <= columns),
            "no row is wider than the pane it folded into"
        );
        // Consecutive rows sit one line height apart — a folded line's second
        // row is a row, not an overprint of its first.
        for pair in built.paragraphs.windows(2) {
            assert_eq!(pair[1].rect[1] - pair[0].rect[1], geometry.line_height);
        }

        // The diff is the exception, on both counts.
        let rows = vec![DiffRow {
            text: long.clone(),
            kind: preview::DiffLineKind::Add,
            top: 0.0,
        }];
        let diff = PreviewDocument::Diff(rows);
        let diff_max = preview_document_max_scroll(
            &diff,
            body,
            scale,
            advance,
            seats::preview_diff_metrics(scale).line_height,
            long.chars().count(),
        );
        assert!(
            diff_max[0] > 0.0,
            "a patch does not reflow, so it keeps the horizontal scroll it needs"
        );
    }

    /// **A patch wider than its pane wears a rule along its bottom, and the
    /// rule can be taken** (user report, 2026-08-17: long `+# …` lines cut at
    /// the pane's right edge with no scroller).
    ///
    /// The extent was never the missing half — a diff's `max_scroll[0]` has been
    /// right since the ruling above, and `Shift`+wheel already reached it. What
    /// was missing was the *picture*: `preview_body_bar` was written with its
    /// axis nailed to `Vertical`, so the one body kind in this window with a
    /// horizontal extent had no track, no thumb and nothing to put a hand on.
    /// The bar is one function and one geometry for both axes
    /// (`preview::scroll_bar`), so what the patch grew is the bar the card and
    /// the pane already wear, stood on its side — same thickness, same grab
    /// tolerance, same linear map from thumb to offset.
    ///
    /// Four claims: the extent is there, the bar is there, the thumb reads back
    /// to an offset at both ends of its track, and the offset actually moves the
    /// ink.
    ///
    /// MUTATION: put `ScrollAxis::Vertical` back into `preview_body_bar` in
    /// place of the parameter. The `across` binding goes `None` and the patch is
    /// silently uncrossable again.
    #[test]
    fn a_patch_wider_than_its_pane_grows_a_rule_a_hand_can_take() {
        let body = [0.0, 0.0, 240.0, 60.0];
        let scale = 1.0;
        let advance = 8.0;
        let metrics = seats::preview_diff_metrics(scale);
        let long = format!("+{}", "# a long comment line".repeat(12));
        let columns = long.chars().count();
        let rows = vec![DiffRow {
            text: long.clone(),
            kind: preview::DiffLineKind::Add,
            top: 0.0,
        }];
        let document = PreviewDocument::Diff(rows.clone());

        // ① The extent, which is what the whole bar is a picture of.
        let max = preview_document_max_scroll(
            &document,
            body,
            scale,
            advance,
            metrics.line_height,
            columns,
        );
        assert!(
            max[0] > 0.0,
            "a patch does not reflow, so it keeps the horizontal scroll it needs"
        );

        // ② The bar. `page + max_scroll` is the content width by construction —
        //    the same inverse `preview_surface_bar` takes.
        let content = (body[2] - body[0]) + max[0];
        let across = preview_body_bar(
            body,
            preview::ScrollAxis::Horizontal,
            [0.0, 0.0],
            content,
            scale,
        )
        .expect("a patch wider than its pane has a rule along the bottom");
        assert_eq!(across.axis, preview::ScrollAxis::Horizontal);
        assert!(
            across.track[3] <= body[3] && across.track[1] >= body[1],
            "the rule lies against the body's own bottom edge, {:?}",
            across.track
        );
        assert!(
            (across.overflow - max[0]).abs() < 0.01,
            "and it promises exactly as far as the clamp allows: {} against {}",
            across.overflow,
            max[0]
        );

        // ③ The thumb reads backwards to an offset, at both ends of its track.
        assert_eq!(
            preview::scroll_dragged_to(&across, across.track_start(), 0.0),
            0.0,
            "the thumb at the near end is the document at its own left"
        );
        assert!(
            (preview::scroll_dragged_to(&across, across.track[2], 0.0) - across.overflow).abs()
                < 0.01,
            "and dragged to the far end it lands exactly where the wheel stops"
        );

        // ④ And the offset moves the ink. The band under an added line does
        //    *not* move — it is the viewport's, by `band_rect`'s own ruling —
        //    so this asks the paragraph, which is the text.
        let palette = bt_render::chrome_palette();
        let drawn_at = |scroll: [f32; 2]| {
            let geometry = seats::preview_mono_geometry(
                body,
                metrics,
                metrics.line_height,
                columns,
                advance,
                scroll,
            );
            build_preview_diff_body(&geometry, &rows, &palette).paragraphs[0].rect[0]
        };
        let still = drawn_at([0.0, 0.0]);
        let shifted = drawn_at([max[0], 0.0]);
        assert!(
            (still - shifted - max[0]).abs() < 0.01,
            "scrolling to the far end moves the run left by the whole extent: \
             {still} then {shifted}, extent {}",
            max[0]
        );
    }

    /// PIN — the caret, the band and the click all agree about which **row** a
    /// column of a folded line is on.
    ///
    /// Three readings of one arithmetic that used to be one reading: the caret's
    /// drawn position, the selection band under it and the byte a click names.
    /// Left disagreeing they produce the classic reflow bug — a caret drawn on
    /// the first row of a paragraph while the text it is editing is on the
    /// third.
    ///
    /// MUTATION: build the paint with `WrapLayout::unwrapped` and the caret's row
    /// goes to zero while its column runs off the pane — the pre-ruling drawing
    /// of a wrapped surface.
    #[test]
    fn a_caret_on_a_folded_line_is_drawn_on_the_row_it_is_really_on() {
        let lines = vec!["aaaa bbbb cccc dddd".to_owned()];
        let wrap = preview_edit::WrapLayout::wrapped(&lines, 10);
        assert_eq!(wrap.rows(), 2);

        // Column 12 is the third character of "cccc", which is on the second row
        // and two cells into it.
        assert_eq!(preview_caret_row(&wrap, 0, 12), (1, 2));
        // And a caret at the head of the line is on the first row at column
        // zero, which is the case a wrap-blind painter also gets right — so it
        // is asserted next to one it does not.
        assert_eq!(preview_caret_row(&wrap, 0, 0), (0, 0));

        // The band for a selection covering columns 8..14 is cut in two, one
        // piece per row, each measured from its own row's left edge.
        let content = "aaaa bbbb cccc dddd";
        let starts = preview_edit::line_starts(content);
        let selection = 8..14;
        let selected = preview_edit::selected_columns(content, &starts, 0, &selection)
            .expect("the selection covers this line");
        assert_eq!(selected, (8, 14));
        let bands = preview_edit_bands(content, &starts, &selection, &wrap, 0..wrap.rows());
        assert_eq!(
            bands,
            vec![(0, 8, 10), (1, 0, 4)],
            "the band turns the corner with the text it is under"
        );

        // And Down from the first row lands on the same column of the second,
        // rather than leaving the line entirely.
        let mut caret = preview_edit::EditCaret {
            anchor: 2,
            caret: 2,
            desired_column: None,
        };
        step_preview_caret_by_row(content, &mut caret, preview_edit::Motion::Down, &wrap, 10)
            .expect("Down is a vertical motion");
        assert_eq!(
            caret.caret, 12,
            "Down walks one drawn row, not one paragraph"
        );
        assert_eq!(caret.desired_column, Some(2));
        // Up returns to where it started.
        step_preview_caret_by_row(content, &mut caret, preview_edit::Motion::Up, &wrap, 10)
            .expect("Up is one too");
        assert_eq!(caret.caret, 2);
        // Home and End are not this function's business: they belong to the
        // logical line, which is the textarea convention the ruling names.
        assert!(
            step_preview_caret_by_row(
                content,
                &mut caret,
                preview_edit::Motion::LineEnd,
                &wrap,
                10
            )
            .is_none()
        );
    }

    /// PIN — the selection's band is drawn **under** the text, in the same body,
    /// and the caret stands in it.
    ///
    /// The band has to ride in [`bt_render::PreviewBody::quads`] rather than go
    /// out as seat chrome: chrome is drawn a whole pass earlier and would sit
    /// under the *pane*, so a band painted there would stay put while the
    /// document it is about scrolled away from it.
    ///
    /// Mutation: derive the band's right edge from the paragraph's own text
    /// instead of from the columns, which drops the break at the end of every
    /// line inside a multi-line selection.
    #[test]
    fn a_selection_band_is_drawn_under_the_text_of_its_own_body() {
        let palette = bt_render::chrome_palette();
        let body = [0.0, 0.0, 400.0, 200.0];
        let metrics = seats::preview_text_metrics(1.0);
        let lines = vec!["one".to_owned(), "two".to_owned(), "three".to_owned()];
        let geometry = seats::preview_mono_geometry(
            body,
            metrics,
            metrics.line_height * 3.0,
            5,
            8.0,
            [0.0, 0.0],
        );
        let paint = PreviewEditPaint {
            bands: vec![(0, 1, 4), (1, 0, 4)],
            caret: Some((1, 3)),
            caret_width: 1.0,
            preedit: None,
        };
        let wrap = preview_edit::WrapLayout::unwrapped(&lines);
        let built = build_preview_text_body(
            &geometry,
            &lines,
            &wrap,
            &highlight::Highlighting::default(),
            8.0,
            Some(&paint),
            &palette,
        );
        assert_eq!(built.quads.len(), 3, "two bands and one caret");
        assert_eq!(built.quads[0].color, palette.preview_selection);
        let row = geometry.line_rect(0);
        assert_eq!(
            built.quads[0].rect,
            [row[0] + 8.0, row[1], row[0] + 32.0, row[3]]
        );
        // The second line's band runs one column past its own three characters:
        // the break is selected too.
        let second = geometry.line_rect(1);
        assert_eq!(built.quads[1].rect[2], second[0] + 32.0);
        let caret = built.quads[2];
        assert_eq!(caret.color, palette.preview_caret);
        assert_eq!(
            caret.rect,
            [second[0] + 24.0, second[1], second[0] + 25.0, second[3]]
        );
        // And the text is still there, over the top of all three.
        assert_eq!(built.paragraphs.len(), 3);
        assert_eq!(built.paragraphs[0].runs[0].text, "one");

        // With no edit surface there are no quads at all, which is the read-only
        // body slice 2 shipped.
        let plain = build_preview_text_body(
            &geometry,
            &lines,
            &wrap,
            &highlight::Highlighting::default(),
            8.0,
            None,
            &palette,
        );
        assert!(plain.quads.is_empty());
    }

    /// The per-keystroke cost of the edit surface, on a file the size of the
    /// whole head read.
    ///
    /// **Re-laying the whole document per key is the design**, not a compromise
    /// waiting for an incremental one: a 64KB head is the largest body this
    /// surface can ever hold (§7.1.3 refuses more), and what a key costs is one
    /// splice, one re-split into lines and one walk for the widest line. This
    /// pins that the whole of it stays inside a frame's budget, so that the day
    /// an incremental relayout is proposed there is a number to argue with.
    ///
    /// The bound is deliberately loose — this is a wall clock on a shared
    /// machine, and a test that fails on a busy build server teaches people to
    /// ignore it. The number that matters is reported, not asserted.
    #[test]
    fn a_keystroke_relays_a_full_head_read_inside_a_frame() {
        let line = "    let value = compute(argument, other) + 1; // a line of source\n";
        let mut body = String::with_capacity(preview::PREVIEW_HEAD_BYTES);
        while body.len() < preview::PREVIEW_HEAD_BYTES {
            body.push_str(line);
        }
        body.truncate(preview::PREVIEW_HEAD_BYTES);
        let mut buffer = text_buffer("big.rs", &body);
        let mut caret = preview_edit::EditCaret {
            anchor: body.len() / 2,
            caret: body.len() / 2,
            desired_column: None,
        };

        const KEYS: usize = 60;
        let started = Instant::now();
        for index in 0..KEYS {
            buffer.edit_content(|content| preview_edit::insert(content, &mut caret, "x"));
            // What the painter does with the result, every key: the document is
            // re-derived from the new revision.
            let lines = preview_edit::display_lines(buffer.content.as_deref().unwrap());
            assert!(!lines.is_empty(), "key {index}");
            std::hint::black_box(&lines);
        }
        let per_key = started.elapsed() / KEYS as u32;
        println!(
            "preview quick-edit: {:.3} ms/key over {} bytes",
            per_key.as_secs_f64() * 1000.0,
            body.len()
        );
        assert!(
            per_key < Duration::from_millis(40),
            "a keystroke took {per_key:?}, which is not a frame by any reading"
        );
    }

    /// PIN — K156, and the day the second door closed. **Every file opens its
    /// preview.**
    ///
    /// This test used to assert the opposite for everything that was not a
    /// picture, and that half of it was written down as an interim from the
    /// beginning: `DESIGN.md` §7.1.3 rules that activating any file opens the
    /// preview, with "no preview" cards for what cannot be shown. The preview
    /// block built the cards, so the interim ended and the assertion inverted.
    ///
    /// The picture half stays, and stays measured against the *terminal's* own
    /// list rather than a list written here, because the property it pins is
    /// unchanged: a `.webp` clicked on a line of output and a `.webp`
    /// double-clicked in the tree must land in the same pane — now on the same
    /// seat by the same lane, chosen by [`path_is_previewable_image`].
    ///
    /// Mutation: restore the `DefaultApp` branch for non-pictures in
    /// [`files_row_activation`].
    #[test]
    fn every_file_opens_in_the_preview_and_a_rootless_column_opens_nothing() {
        let root = r"C:\work";
        for name in [
            "/shot.png",
            "/a/b/SHOT.JPEG",
            "/icon.svg",
            "/anim.gif",
            "/notes.md",
            "/Cargo.toml",
            "/README",
            "/image.bmp",
            "/setup.exe",
        ] {
            assert_eq!(
                files_row_activation(root, name),
                RowActivation::Preview(files::full_path(root, name)),
                "{name} opens in the preview"
            );
        }
        for picture in ["/shot.png", "/a/b/SHOT.JPEG", "/icon.svg", "/anim.gif"] {
            assert!(
                path_is_previewable_image(&files::full_path(root, picture)),
                "{picture} takes the decode lane"
            );
        }
        for document in ["/notes.md", "/Cargo.toml", "/README", "/setup.exe"] {
            assert!(
                !path_is_previewable_image(&files::full_path(root, document)),
                "{document} takes the buffer lane"
            );
        }
        assert_eq!(
            files_row_activation("", "/notes.md"),
            RowActivation::Nowhere,
            "a column that was never pointed anywhere has no path to open"
        );
        assert_eq!(
            files_row_activation(root, "/notes.md"),
            RowActivation::Preview(PathBuf::from(root).join("notes.md")),
            "L167: the id's slashes never reach the filesystem"
        );
    }

    /// PIN — M175. The restore prompt names a files-only tab by the folder it
    /// was looking at, not by nothing at all.
    ///
    /// The red gate: the fallback built `Seed::Files { root: String::new() }`
    /// literally, one function away from the walker that could have answered.
    /// The row still drew — this is why no test caught it — it just drew a place
    /// with no name, so the prompt offered to bring back a tab it could not
    /// describe.
    #[test]
    fn a_files_only_tab_is_named_on_the_restore_prompt_by_the_folder_it_held() {
        let files = |root: &str| {
            LayoutNodeV1::Leaf(LeafNodeV1::Files(bt_persist::FilesLeafV1 {
                view: bt_persist::FilesViewV1::Files,
                root: root.to_owned(),
                open: Vec::new(),
                sel: None,
                width: 240,
                remotes_open: false,
            }))
        };
        assert_eq!(
            restore_row_seed(&files(r"C:\Users\dev\project")),
            seed::Seed::Files {
                root: r"C:\Users\dev\project".to_owned()
            }
        );

        // A tab with a shell in it is still named by the shell, whichever side
        // of the split the folder is on.
        let mixed = LayoutNodeV1::Split(bt_persist::SplitNodeV1 {
            dir: bt_persist::SplitDirV1::Row,
            ratio: 250_000,
            children: [
                Box::new(files(r"C:\repo")),
                Box::new(LayoutNodeV1::Leaf(LeafNodeV1::Term(TermLeafV1 {
                    profile_id: "pwsh".to_owned(),
                    cwd: r"C:\repo\crates".to_owned(),
                    manual_name: None,
                }))),
            ],
        });
        assert_eq!(
            restore_row_seed(&mixed),
            seed::Seed::Term {
                profile_id: "pwsh".to_owned(),
                cwd: r"C:\repo\crates".to_owned(),
                manual_name: None,
            },
            "a tab's identity is its terminal wherever the column sits"
        );

        // And two columns are named by the first one drawn, which is the same
        // rule `first_term_leaf` follows for shells.
        let two = LayoutNodeV1::Split(bt_persist::SplitNodeV1 {
            dir: bt_persist::SplitDirV1::Row,
            ratio: 500_000,
            children: [Box::new(files(r"C:\first")), Box::new(files(r"C:\second"))],
        });
        assert_eq!(
            restore_row_seed(&two),
            seed::Seed::Files {
                root: r"C:\first".to_owned()
            }
        );
    }

    /// PIN — K143, collapsed. **The menu's first row is one word.**
